object Main {
  def main(args:Array[String]) = {
    val sc = new java.util.Scanner(System.in)
    val s = sc.next
    var dp = new Array[Int](13)
    var dpn = new Array[Int](13)

    // 初期化(最初は余りは「0」)
    dp(0) = 1

    for (c <- s.toCharArray) {
      dpn = new Array[Int](13)
      // 桁上げ処理
      for (i <- 0 to 12) {
        dpn((i*10)%13) = dp(i)
      }
      dp = dpn
      dpn = new Array[Int](13)

      // 固定値なら値に応じてシフト
      if (c != '?') {
        val v = c.asDigit
        for (i <- 0 to 12) {
          dpn((i+v)%13) += dp(i)
        }
      }
      // ?なら値を0-9とみなしてそれぞれシフト
      else {
        for (v <- 0 to 9) {
          for (i <- 0 to 12) {
            dpn((i+v)%13) += dp(i)
            dpn((i+v)%13) %= 1000000007
          }
        }
      }
      dp = dpn
    }
    println(dp(5))
    //println(dp.deep)
  }
}

