class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  def solve(): Unit = {
    val S = ns().reverse // 反転すると楽
    val N = S.length

    val memo = mutable.Map[(String, Boolean), Array[Long]]()
    def cnt(s: Int, t: Int, rev: Boolean): Array[Long] = {
      val str = S.substring(s, t)
      if (memo.contains((str, rev))) memo((str, rev))
      else {
        val c = Array.ofDim[Long](13)
        val lp0 = if (str(0) == '?') 10 else 1
        val lp1 = if (str.length >= 2 && str(1) == '?') 10 else 1
        val lp2 = if (str.length >= 3 && str(2) == '?') 10 else 1
        REP(lp0) { i =>
          val v0 = if (str(0) == '?') i else str(0) - '0'
          REP(lp1) { j =>
            val v1 = if (str.length >= 2 && str(1) == '?') j
              else if (str.length >= 2) str(1) - '0'
              else 0
            REP(lp2) { k =>
              val v2 = if (str.length >= 3 && str(2) == '?') k
                else if (str.length >= 3) str(2) - '0'
                else 0

              c((v0 + v1 * 10 + v2 * 100) % 13) += 1
            }
          }
        }
        if (rev) reverse(c)
        memo((str, rev)) = c
        c
      }
    }

    val dp = ArrayBuffer[Array[Long]]()
    REP((N + 3 - 1)/3) { i =>
      val c = cnt(i * 3, min(N, (i+1) * 3), i % 2 == 1)
      dp += c
    }

    debug(dp.map(_.mkString(" ")).mkString(","))
    val dp2 = Array.ofDim[Long](dp.length, 13)
    REP(13) { i =>
      dp2(0)(i) = dp(0)(i)
    }
    REP(dp2.length - 1) { i =>
      REP(13) { j =>
        REP(13) { k =>
          dp2(i + 1)((j + k)%13) += dp(i + 1)(j) * dp2(i)(k) % MOD
        }
      }
      REP(13) { j =>
        dp2(i + 1)(j) %= MOD
      }
    }

    debug(dp2.map(_.mkString(" ")).mkString(","))

    out.println(dp2.last(5))
  }

  def reverse(as: Array[Long]): Unit = {
    REP(6, 1) { i =>
      val j = 13 - i
      val t = as(i)
      as(i) = as(j)
      as(j) = t
    }
  }
}

