    val ret = new Array[Long](13)
    if (digit == '?') {
      for {
        i <- (0 to 9)
        j <- (0 to 12)
      } {
        ret((j * 10 + i) % 13) += rems(j)
        ret((j * 10 + i) % 13) %= Mod
      }
    } else {
      for {
        i <- Seq((digit - '0').toInt)
        j <- (0 to 12)
      } {
        ret((j * 10 + i) % 13) += rems(j)
        ret((j * 10 + i) % 13) %= Mod
      }
    }
    ret
  }

  val init = s.head match {
    case '?' => Array.tabulate(13)(i => if (i < 10) 1L else 0L)
    case c => Array.tabulate(13)(i => if (i == c - '0') 1L else 0L)
  }

  val result = s.tail.foldLeft(init){(z, d) => dp(z, d)}
