// 2進数にする
vector<ll> to_binary(ll a){
    vector<ll> A;
    if(a==0){
        A.push_back(0);
        return A;
    }
    while(a){
        ll r = a%2;
        a/=2;
        A.push_back(r);
    }
    return A;
}

