int getDigit(char c) {
    return c - '0';
}

long long int power(long long int x, long long int y){
    long long int res=1;
    if(y<=0)
        return res;
    while(y){
        if(y%2)
            res=(res*x)%13;
        y=y/2;
        x=(x*x)%13;
    }
    return res;
}

