template<size_t nDigits, int mod>
struct Mod{
  int surplus[nDigits][10];
  constexpr Mod():surplus(){
    surplus[0][0]=0;
    surplus[0][1]=1%mod;
    for( size_t i = 0; i < 10; ++i){
      surplus[0][i] = i%mod;
    }
    for(size_t i = 1; i < nDigits; ++i){
      surplus[i][0] = 0;
      surplus[i][1] = (10*surplus[i-1][1])%mod;
      for( size_t j = 2; j < 10; ++j){
        surplus[i][j] = (j*surplus[i][1])%mod;
      }
    }
  }
};

constexpr auto numMod13 = Mod<100000, 13>();

constexpr int maxInt = 1000000000 + 7;

array<lint, 100000*100> memo;

lint f(int digits, int mod, int nums[]){
  if( memo[digits*100+mod] != -1){
    return memo[digits*100+mod];
  }
  if( digits == 0){
    if( nums[digits] == -1){
      rep(i,10){
        if( i%13 == mod){
          return memo[digits*100+mod] = 1;
        }
      }
      return 0;
    }else{
      if( nums[digits]%13 == mod){
        //printline(digits << " " << nums[digits] << " " << mod);
        return memo[digits*100+mod] = 1;
      }
      return memo[digits*100+mod] = 0;
    }
  }
  if( nums[digits] == -1){
    lint ret = 0;
    rep(i,10){
      ret += f(digits-1, (13 + mod-numMod13.surplus[digits][i])%13, nums)%maxInt;
      ret %= maxInt;
    }
    return memo[digits*100+mod] = ret;
  }else{
    return memo[digits*100+mod] = f(digits-1, (13 + mod-numMod13.surplus[digits][nums[digits]])%13, nums)%maxInt;
  }
}



