template<uint64_t m = 1000000007>
class ModInt {
public:
    ModInt(const uint64_t x): x(x) { }

    ModInt operator + (ModInt y) const {
        return (x + y.x) % m;
    }

    ModInt operator * (ModInt y) const {
        return (x * y.x) % m;
    }

    void operator += (ModInt y) {
        x = (x + y.x) % m;
    }

    void operator *= (ModInt y) {
        x = (x * y.x) % m;
    }

    uint64_t data() const {
        return x;
    }

private:
    uint64_t x;
};

void shift(const ModInt<13> n, std::vector<ModInt<> > &next, const std::vector<ModInt<> > &frequency) {
    for(int i = 0; i < 13; ++i) {
        next[(n + i).data()] += frequency[i];
    }
}

int main() {
    std::string s;
    std::cin >> s;

    auto frequency = std::vector<ModInt<> >(13, 0);
    frequency[0] = 1;

    ModInt<13> pow10 = 1;

    for(auto i = s.rbegin(); i != s.rend(); ++i) {
        const char c = *i;
        auto freq = std::vector<ModInt<> >(13, 0);

        if(c == '?') {
            for(int i = 0; i <= 9; ++ i) {
                const ModInt<13> r = pow10 * i;

                shift(r, freq, frequency);
            }
        } else {
            const int x = c - '0';
            const ModInt<13> r = pow10 * x;

            shift(r, freq, frequency);
        }

        frequency = std::move(freq);

        pow10 *= 10;
    }

    std::cout << frequency[5].data() << std::endl;

    return 0;
}

