//かなり難しく、解説でギリギリ理解できた程度。
//典型的らしいので必ず解き直す。
// n = 13*a + b と表せるとする。この数の右側に1桁増やしてc(0~9)をおく。
// 10*n+c = 130*a + 10*b + c となる。
//この数を13で割った余りは、10*b + cを13で割った余りに一致。

//言い換え
// ABCDEFGを13で割った余りは、ABCDEFを13で割った余りをmとすると、10*m + Gを13で割った余りに一致。

//非常に大きい数をある数で割った余りは、1つ桁を削った数をある数で割った余りがわかれば計算できる。
//徐々に桁を増やしていけばよく、漸化式的になるため、動的計画法と相性がいい。

int main(){
  string S;
  cin >> S;
  vvll dp(S.size()+1, vll(13, 0)); //dp[i+1][j]はi桁目までで、余りがjとなる数
  dp.at(0).at(0) = 1;
  for(int i = 0; i < S.size(); i++){
    ll c;
    if(S.at(i) == '?') c = -1;
    else c = S.at(i) - '0';

    if(c != -1){
      for(int j = 0; j < 13; j++){
        dp.at(i+1).at((10 * j + c) % 13) += dp.at(i).at(j) % MOD;
        dp.at(i+1).at((10 * j + c) % 13) %= MOD;
      }
    }
    else{
      for(int j = 0; j <= 9; j++){
        for(int k = 0; k < 13; k++){
          dp.at(i+1).at((10 * k + j)%13) += dp.at(i).at(k) % MOD;
          dp.at(i+1).at((10 * k + j)%13) %= MOD;
        }
      }
    }

  }
  cout << dp.at(S.size()).at(5) << endl;
}

