int main(int argc, const char * argv[]) {

    string S = "";
    cin >> S;
    ll N = S.size();

    vector<ll> table = vector<ll>(N, 0);
    table[N-1] = 1;
    for (ll i = N-2; i >= 0; i--) {
        table[i] = (table[i + 1] * 10) % 13;
    }
    vector<ll> dp = vector<ll>(13, 0);

    for (ll i = 0; i < N; i++) {
        vector<ll> tempdp = vector<ll>(13, 0);
        for (ll j = 0; j < 10; j++) {
            if (S[i] != '?' && S[i] != '0' + j) {
                continue;
            }
            ll shift = table[i] * j;
            if (i == 0) {
                tempdp[shift % 13] = 1;
            } else {
                for (ll k = 0; k < 13; k++) {
                    tempdp[(shift + k) % 13] += dp[k];
                }
            }
        }
        for (ll k = 0; k < 13; k++) {
            dp[k] = tempdp[k] % 1000000007;
        }
    }

    cout << dp[5];
    return 0;
}

