using namespace std;
typedef long long ll;
ll mod = 1000000007;

string s;
int n;
ll dp[100005][13];  // dp[i][j] : 先頭i文字として考えられるもののうち13で割ったあまりがjのものの数

void solve() {
    ll ans = 0;
    n = s.size();

    dp[0][0] = 1;
    rep(i, n) {
        int c;
        //s[i]が?だったら-1,それ以外はs[i]がcに入る
        if(s[i] == '?') {
            c = -1;
        }
        else {
            c = s[i] - '0';
        }

        // sのi+1文字目をjとする
        // c = -1のとき j = 0 ～ 9 全てで処理が行われる
        // それ以外は j = c のとき処理が行われる
        rep(j, 10) {

            if(c != -1 && j != c) {
                continue;
            }
            /* 先頭i文字を13で割った余りをkとすると
               i+1文字目までの余りは (10*k + j)%13 になる */
            rep(k, 13) {
                dp[i+1][ (10*k + j)%13 ] += dp[i][k];
            }
        }

        rep(j, 13) {
            dp[i+1][j] %= mod;
        }
    }

    cout << dp[n][5] << endl;
}

int main() {
    cin >> s;

    solve();

    return 0;
}

