typedef long long ll;
const int mod = 1000000007;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%mod+mod)%mod){}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};
int main(){
  mint dp[100010][15];
  int i,j,l;
  string s;
  cin >> s;
  for(i=0;i<s.size();i++){
    for(j=0;j<13;j++){
      dp[i][j]=0;
    }
  }
  if(s[0]=='?'){
    for(i=0;i<10;i++){
      dp[0][i]=1;
    }
  }
  else{
    dp[0][s[0]-'0']=1;
  }
  for(i=1;i<s.size();i++){
    if(s[i]=='?'){
      for(j=0;j<13;j++){
        for(l=0;l<10;l++){
          dp[i][(10*j+l)%13]+=dp[i-1][j];
        }
      }
    }
    else{
      int a=s[i]-'0';
      for(j=0;j<13;j++){
        dp[i][(10*j+a)%13]+=dp[i-1][j];
      }
    }
  }
  printf("%lld\n",dp[s.size()-1][5]);
  return 0;
}

