void solve() {
    string s;
    cin >> s;
    int n = s.length();
    vector<ll> a(n);
    for (int i = 0; i < n; ++i) {
        if (s[i] == '?')
            a[i] = -1;
        else 
            a[i] = s[i] - '0';
    }

    ten[0] = 1;
    for (int i = 1; i < 100100; ++i)
        ten[i] = ten[i - 1] * 10 % 13;

    vector<vector<ll>> dp(n + 1, vector<ll>(13, 0));
    dp[n][0] = 1;
    for (ll i = n - 1; i >= 0; --i) {
        if (a[i] == -1) {
            for (ll k = 0; k < 13; ++k)
                for (ll d = 0; d <= 9; ++d)
                    dp[i][(ten[n - 1 - i] * d + k) % 13] = (dp[i][(ten[n - 1 - i] * d + k) % 13] + dp[i + 1][k]) % MOD;
        } else {
            for (ll k = 0; k < 13; ++k)
                dp[i][(ten[n - 1 - i] * a[i] + k) % 13] = (dp[i][(ten[n - 1 - i] * a[i] + k) % 13] + dp[i + 1][k]) % MOD;
        }
    }
    cout << dp[0][5] % MOD;
}   


