void solve(){
	cin >> s;
	int n = s.size();

	dp[n][0] = 1;
	i64 d = 1;
	for(int i = n-1; i >= 0; i--){
		for(int j = 0; j < 13; j++){
			if(s[i] == '?'){
				for(int k = 0; k < 10; k++){
					int cnt = (d*k + j)%13;
					dp[i][cnt] += dp[i+1][j];
					dp[i][cnt] %= INF;
				}
			}
			else{
				int cnt = (d*(s[i]-'0') + j)%13;
				dp[i][cnt] += dp[i+1][j];
				dp[i][cnt] %= INF;
			}
		}
		d = mod(d*10, 13);
	}
	cout << dp[0][5] << endl;
}

