    lint len = S.size();
    vec<vec<lint>> dp(len + 1, vec<lint>(13, 0));
    dp.at(0).at(0) = 1;
    lint base = 1;
    range(i, 1, len + 1) {
        const char c = S.at(i - 1);
        if (c != '?') {
            lint d = (c - '0') * base % 13;
            range(r, 0, 13) {
                dp.at(i).at((d + r) % 13) += dp.at(i - 1).at(r);
                dp.at(i).at((d + r) % 13) %= MOD;
            }
        }
        else {
            range(d, 0, 10) {
                lint dd = d * base % 13;
                range(r, 0, 13) {
                    dp.at(i).at((dd + r) % 13) += dp.at(i - 1).at(r);
                    dp.at(i).at((dd + r) % 13) %= MOD;
                }
            }
        }
        base *= 10;
        base %= 13;
    }
    cout << dp.at(len).at(5) << '\n';
}

