const int inf = 1e5 + 9;
const int mod = 1e9 + 7;

typedef long long ll;

int ten[inf];
ll memo[inf][13];
string s;

ll solve(int here, int rem) {
    if (here == s.size()) {
        if (rem == 5) return 1LL;
        else return 0LL;
    }
    ll &ret = memo[here][rem];
    if (ret != -1LL) return ret;
    if (s[here] != '?') return ret = solve(here + 1, (rem + ten[here] * (s[here] - '0')) % 13);
    else {
        ret = 0;
        for (int i = 0; i < 10; i++) {
            ret += solve(here + 1, (rem + ten[here] * i) % 13);
            ret %= mod;
        }
        return ret;
    }
}

