		for(int i = 0 ; i <= 9 ; i += 1){
			ret += ans(curr-1,(mod + mods[v]*i) % 13);
			ret %= 1000000007;
		}
	}else{
		ret += ans(curr-1,(mod + mods[v]*(s[curr]-'0')) % 13);
		ret %= 1000000007;
	}
	dp[curr][mod] = ret;
	return ret;
}

