    for (int i = 1; i < S.length(); i++) {
        if (S[i] == '?') {
            for (int j = 0; j < 13; j++) {
                for (int k = 0; k <= 9; k++) {
                    dp[i][(j*10 + k)%13] += dp[i-1][j];
                    dp[i][(j*10 + k)%13] %= MOD;
                }
            }
        }
        else {
            for (int j = 0; j < 13; j++) {
                dp[i][(j*10 + S[i]-'0')%13] += dp[i-1][j];
                dp[i][(j*10 + S[i]-'0')%13] %= MOD;
            }
        }
    }

    cout << dp[S.length()-1][5] << endl;
}


