/* 10^p % 13 */
long tenpowmod13(long p) {
    if (p == 0)
        return 1;
    if (p == 1)
        return 10;
    if (p % 2 == 0) {
        long tmp = tenpowmod13(p/2);
        return tmp * tmp % 13;
    } else {
        long tmp = tenpowmod13((p-1)/2);
        return (tmp * tmp * 10) % 13;
    }
}

