void ABC135D()
{
	int residuals[6][13];
	int base = 1;
	for (int i = 0; i < 6; ++i)
	{
		int base2 = base;
		for (int j = 0; j < 13; ++j)
		{
			residuals[i][j] = (base2 * j) % 13;
		}
		base *= 10;
	}
	// check
	//for (int i = 0; i < 6; ++i)
	//{
	//	for (int j = 0; j < 13; ++j)
	//	{
	//		cout << residuals[i][j];
	//		if (j < 12)
	//			cout << ' ';
	//	}
	//	cout << endl;
	//}


	string str;
	cin >> str;
	int n = str.size();

	vector<int> unknowns;
	int known = 0;
	for (int i = 0; i < n; ++i)
	{
		int loc = i % 6;
		char a = str[n - 1 - i];
		if (a == '?')
		{
			unknowns.push_back(loc);
		}
		else
		{
			int x = atoi(&a);
			known += residuals[loc][x];
		}
		if (known > 12)
			known -= 13;
	}
	if (unknowns.empty())
	{
		int res = known == 5 ? 1 : 0;
		cout << res << endl;
		return;
	}
	int m = unknowns.size();
	int target = 13 + 5 - known;
	if (target > 12)
		target -= 13;

	// DP
	const int MOD = 1000000007;
	vector<long long int> vals(13);
	vals[0] = 1;
	for (int i = 0; i < m; ++i)
	{
		auto prevVals = vals;
		fill(vals.begin(), vals.end(), 0);
		auto& x = residuals[unknowns[i]];
		for (int j = 0; j < 13; ++j)
		{
			auto p = prevVals[j];
			for (int k = 0; k < 10; ++k)
			{
				int currRes = x[k] + j;
				if (currRes > 12)
					currRes -= 13;
				vals[currRes] += p;
				if (vals[currRes] > MOD - 1)
					vals[currRes] -= MOD;
			}
		}
	}
	cout << vals[target] << endl;
}

