    if (i == 0)
      return dp[key] = ((n % M) == r) ? 1 : 0;
    ll s = (M - (((pow10i[i] * n) % M) - r)) % M;
    return dp[key] = f(S, DpKey{i - 1, s}, pow10i, dp);
  }
  if (i == 0)
    return dp[key] = (r < 10) ? 1 : 0;
  ll sum = 0LL;
  for (ll const &n : range(10LL)) {
    ll s = (M - (((pow10i[i] * n) % M) - r)) % M;
    sum += f(S, DpKey{i - 1, s}, pow10i, dp);
    sum %= MOD;
  }
  return dp[key] = sum;
}
vector<ll> init(ll mod, ll N) {
  auto ret = vec(N, 1LL);
  partial_sum(ret.begin(), ret.end(), ret.begin(),
              [mod](auto prev, auto n) { return (prev * 10) % mod; });
  return ret;
}
