const int MOD = 1e9 + 7;

inline void addstates(vi& nextdp, const vi& dp, int dig, int mul) {
    for (int i=0; i<13; ++i) {
        int newrem = (dig*mul + i)%13;
        nextdp[newrem] += dp[i];
        nextdp[newrem] %= MOD;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    vi dp(13);
    dp[0] = 1;
    int mul = 1;
    for (int i=s.size()-1; i>=0; --i) {
        vi nextdp(13);
        if (s[i] == '?') {
            for (int j=0; j<10; ++j)
                addstates(nextdp, dp, j, mul);
        }
        else
            addstates(nextdp, dp, s[i]-'0', mul);
        mul = (mul*10)%13;
        swap(nextdp, dp);
    }
    cout << dp[5] << "\n";
}

