int dp[NM][13]; // dp[i][j] : i桁目までで、13で割ってあまりがjになる数の個数

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    string s; cin>>s;
    reverse(s.begin(), s.end());
    int n = s.size();
    if(s[0]=='?'){
        rep(i, 10) dp[0][i]=i;
    } else {
        int idx = s[0]-'0';
        dp[0][idx]=1;
    }
    int digit = 1;
    for(int i=1; i<n; i++){
        digit *= 10;
        digit %= 13;
        if(s[i]=='?'){
            for(int j=0; j<10; j++){ // ?の候補
                for(int k=0; k<13; k++) {
                    int idx = (k+j*digit) % 13;
                    dp[i][idx]+=dp[i-1][k];
                    dp[i][idx]%=MOD;
                }
            }
        }else{
            for(int k=0; k<13; k++){
                int j = (s[i]-'0');
                int idx = (k+j*digit)%13;
                dp[i][idx] = dp[i-1][k];
                dp[i][idx] %= MOD;
            }
        }
    }
    cout << dp[n-1][5]<<endl;
}

