const int Mod = (int)1e9 + 7;
const int MAXN = 100005;
string str;
int p[MAXN];
int memo[MAXN][13];

int solve(int idx, int rem) {
    if (idx == str.size())
        return rem == 5;
    int &ret = memo[idx][rem];
    if (~ret)
        return ret;
    ret = 0;
    if (str[idx] == '?') {
        for (int i = 0; i < 10; ++i) {
            ret += solve(idx + 1, (rem + i * p[idx] % 13) % 13);
            ret %= Mod;
        }
    } else {
        ret = solve(idx + 1, (rem + (str[idx] - '0') * p[idx] % 13) % 13);
        ret %= Mod;
    }
    return ret;
}

