      for(int r=0; r<10; ++r){
        int m = T[k%6][r];
        for(int n=0; n<13; ++n) dp_new[(n+m)%13] += dp[n];
      }
    }else{
      int m = T[k%6][(int)(s[i]-'0')];
      for(int n=0; n<13; ++n) dp_new[(n+m)%13] = dp[n];
    }

    dp_swap = dp_new; dp_new = dp; dp = dp_swap;
    for(int j=0; j<13; ++j) dp[j]%=mod;
  }

  std::cout << dp[5] << std::endl;
  return 0;
}

