// 数が書いてある場合
void proceed_constant(vector<int64_t> &rem, int d) {
  // 10倍の処理と1の位の処理
  vector<int64_t> temp(13);
  for (int i = 0; i < 13; i++) {
    temp[(i * 10 + d) % 13] = rem[i];
  }
  rem = temp;
//  view_5(rem);
}

// ?の場合
void proceed_variant(vector<int64_t> &rem) {
  // 10倍の処理
  vector<int64_t> temp(13, 0);
  for (int i = 0; i < 13; i++) {
    temp[(i * 10) % 13] = rem[i];
  }
  rem = temp;

  temp = vector<int64_t>(13, 0);
  // 1の位の処理
  for (int i = 0; i < 13; i++) {
    for (int j = 0; j <= 9; j++) {
      temp[(i + j) % 13] += rem[i];
    }
  }

  for (int i = 0; i < 13; i++) {
    temp[i] = temp[i] % (1000 * 1000 * 1000 + 7);
  }

  rem = temp;
}

