        }else{
            int next = c - '0';
            rep(j,0,13){
                //int num = next * 10 + j;
                int num = next * digit[(i+0) % 6] + j;
                num %= 13;
                dp[i+1][num] = dp[i][j];
            }
        }
    }
    //rep(i,0,13)cout << i << ":" << dp[S.size()][i] << endl;
    cout << dp[S.size()][5] << endl;
}

