int ctoi(char c) {
	if (c >= '0' && c <= '9') {
		return c - '0';
	}

	return -1;
}

int main() {
	string S;
	cin >> S;

	int N = S.size();

	// 左からi+1文字で構成される整数 % 13
	// = （左からi文字で構成される整数を13で割った余り * 10 + 左からi+1文字目の数字） % 13
	// 参考） http://9871225.blog.fc2.com/blog-entry-310.html

	dp[0][0] = 1;
	for (int i=0; i<N; i++) {
		if (S[i] != '?') {
			int c = ctoi(S[i]);

			for (int j=0; j<13; j++) {
				dp[i+1][(j * 10 + c) % 13] += dp[i][j];
			}
		} else {
			// S[i] == '?' の時は0-9全ての数字の場合を考える
			for (int c=0; c<10; c++) {
				for (int j=0; j<13; j++) {
					dp[i+1][(j * 10 + c) % 13] += dp[i][j];
				}
			}
		}

		for (int j=0; j<13; j++) {
			dp[i+1][j] %= MOD;
		}
	}

	int ans = dp[N][5];

	cout << ans << endl;

	return 0;
}

