#define MAX (int)1e+3
#define M 13
typedef long long ll;

char S[MAX];
static const ll p = 1000000007;

void solve() {
    ll dp[MAX+1][M];
    int base = 1;
    int n = strlen(S);
    int c;

    //initialize
    for (int i=1; i<M; i++) dp[0][i] = 0;
    dp[0][0] = 1;

    //dp
    for (int i=1; i<=n; i++) {
        if (S[n-i]=='?') c = -1;
        else c = S[n-i] - '0';

        for (int j=0; j<M; j++) dp[i][j] = 0;

        for (int j=0; j<10; j++) {
            if (c == -1 || c == j) {
                for (int k=0; k<M; k++) dp[i][(k+j*base)%M] += dp[i-1][k];
            }
        }

        for (int j=0; j<M; j++) dp[i][j] %= p;
        base *= 10; base %= M;
    }

    //result
    printf("%lld\n", dp[n][5]);
}

int main() {
    scanf("%s", S);

    solve();

    return 0;
}

