typedef long long LL;
typedef pair<LL,LL> ii;
const double PI = 3.1415926535898;
const double E = 2.718281828459;
const int INF = 0x7fffffff;
const int mod = 1e9+7;
const int maxn = 1e5+10;
LL k,x,y;
vector<ii> v;
bool solve(LL x,LL y){
    if(k%2 == 0 && (x+y)%2 != 0) return false;
    LL cx = 0,cy = 0;
    while((x-cx) >= k && (x-cx)+(y-cy) > 2*k){
        cx += k;
        v.push_back(ii(cx,cy));
    }
    while((y-cy) >= k && (x-cx)+(y-cy) > 2*k){
        cy += k;
        v.push_back(ii(cx,cy));
    }
    if(cx == x && cy == y) return true;
    if(x-cx+y-cy == k){
        v.push_back(ii(x,y));
        return true;
    }
    LL yu = x-cx+y-cy;
    if(yu&1){
        if(x-cx >= y-cy){
            LL t = min(k,x-cx);
            cx += t,cy -= (k-t);
        }else{
            LL t = min(k,y-cy);
            cx -= (k-t),cy += t;
        }
        v.push_back(ii(cx,cy));
    }
    yu = x-cx+y-cy;
    if(yu > 0){
        LL t = yu/2;
        if(x-cx >= t)
            cx += t,cy -= (k-t);
        else cy += t,cx -=(k-t);
        v.push_back(ii(cx,cy));
        v.push_back(ii(x,y));
    }
    return true;
}
