struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}

template <uint64_t MOD> class modint {
  using u64 = uint64_t;
public:
  u64 x;
  constexpr modint(const u64 x = 0) noexcept : x(x% MOD) {}
  constexpr u64& value() noexcept { return x; }
  constexpr const u64& value() const noexcept { return x; }
  constexpr modint operator+(const modint r) const noexcept { return modint(*this) += r; }
  constexpr modint operator-(const modint r) const noexcept { return modint(*this) -= r; }
  constexpr modint operator*(const modint r) const noexcept { return modint(*this) *= r; }
  constexpr modint operator/(const modint r) const noexcept { return modint(*this) /= r; }
  constexpr modint& operator+=(const modint r) noexcept {
    x += r.x;
    if (x >= MOD) x -= MOD;
    return *this;
  }
  constexpr modint& operator-=(const modint r) noexcept {
    if (x < r.x) x += MOD;
    x -= r.x;
    return *this;
  }
  constexpr modint& operator*=(const modint r) noexcept {
    x = x * r.x % MOD;
    return *this;
  }
  constexpr modint& operator/=(modint r) noexcept {
    u64 exp = MOD - 2;
    while (exp) {
      if (exp % 2) *this *= r;
      r *= r;
      exp /= 2;
    }
    return *this;
  }
  friend istream& operator>>(istream& in, modint& m) {
    in >> m.x;
    return in;
  }
  friend ostream& operator<<(ostream& out, const modint& m) {
    out << m.x;
    return out;
  }
};

