using DpKey = tuple<ll, ll>;
ll f(string const &S, DpKey key, vector<ll> const &pow10i,
     u_map<DpKey, ll> &dp) {
  ll i = get<0>(key);
  ll r = get<1>(key);
  ll c = S[S.size() - 1 - i];
  ll M = 13LL;
  if (i == 0) {
    if (c != '?') {
      ll n = (c - '0');
      return ((n % M) == r) ? 1 : 0;
    }
    return (r >= 10) ? 0 : 1;
  }
  if (dp.find(key) != dp.end())
    return dp[key];

  if (c != '?') {
    ll n = (c - '0');
    ll s = ((M + r) - ((pow10i[i] * n) % M)) % M;
    return dp[key] = (f(S, DpKey{i - 1, s}, pow10i, dp) % MOD);
  }
  ll ret = 0LL;
  for (ll const &n : range(10LL)) {
    ll s = ((M + r) - ((pow10i[i] * n) % M)) % M;
    ret += f(S, DpKey{i - 1, s}, pow10i, dp);
    ret %= MOD;
  }
  return dp[key] = ret;
}
