int solve(int idx, int sum) {
	// cout<<idx<<" "<<sum<<endl;
	if(idx == s.length())
		return sum == 5;

	if(dp[idx][sum] != -1) 
		return dp[idx][sum];


	int sm = sum;
	int ans = 0;

	sum *= 10;
	if(s[idx] != '?') {
