/*********** Constants ***********/
const auto INF  = static_cast<int>(1e10);
const auto INFL = static_cast<ll>(1e18);
const auto MOD  = static_cast<ll>(1e9 + 7);
const auto NIL  = nullptr;

/*********** Variables ***********/
string S;
vector<vector<ll>> DP;
ll ANS;

/************* Utils *************/

/*********** Functions ***********/
bool init() {
    cin >> S;
    DP.resize(S.size() + 1, vector<ll>(13, 0));
    ANS = 0;
    return true;
}

void solve() {
    if (S[0] == '?') {
        for (ll i = 0; i < 10; i++)
            DP[1][i] = 1;
    }
    else {
        DP[1][S[0] - '0'] = 1;
    }
    for (ll digit = 2; digit <= S.size(); digit++) {
        if (S[digit - 1] == '?') {
            for (ll i = 0; i < 13; i++) {
                for (ll j = 0; j < 10; j++) {
                    DP[digit][(10 * i + j) % 13]
                        = (DP[digit][(10 * i + j) % 13] + DP[digit - 1][i]) % MOD;
                }
            }
        }
        else {
            ll i = S[digit - 1] - '0';
            for (ll j = 0; j < 13; j++) {
                DP[digit][(j * 10 + i) % 13] = DP[digit - 1][j];
            }
        }
    }
    ANS = DP[S.size()][5];
}

void output() {
    cout << ANS % MOD << endl;
}

int main() {
    init();
    solve();
    output();
    return 0;
}

