// a^k mod p
int modpow(int a, int k, int p) {
	int ans = 1;
	while (k > 0) {
		if (k % 2 == 1) {
			ans *= a;
			ans %= p;
		}
		a = (a * a) % p;
		k = k / 2;
	}
	return ans;
}

