const int INF = 1e9;
const ll MOD = 1e9 + 7;
double EPS = 1e-8;

const int MAX_N = 1e5+10;
ll dp[MAX_N][13];

int main(){
    string s;
    cin >> s;
    dp[0][0] = 1;
    int n = s.size();
    rep(i, n) {
        rep(j, 13) {
            if(s[i] == '?') {
                rep(k, 10) {
                    (dp[i+1][(j*10+k) % 13] += dp[i][j]) %= MOD;
                }
            }
            else {
                int k = s[i] - '0';
                (dp[i+1][(j*10+k) % 13] += dp[i][j]) %= MOD;
            }
        }
    }
    cout << dp[n][5] << endl;
    return 0;
}

