//============================================================================
// 解法
// 漸化式：
// dp[i][j] = 先頭i文字目として考えられるもののうち、13で割った余りがjのもの
// 
// iの昇順にdpを見ると、i-1文字目までを13で割ったあまり(dp[i-1][j]のj)と
// s[i]としてあり得る数字をすべて試すことでdp[i][0] ~ dp[i][12]の値がわかる
// 13で割った余りが5となるものを出力すればよい。(dp[n][5]が答え)
//============================================================================

int main() {
	int i, j, k;
	string s;
	cin >> s;

	int n = s.length();
	dp[0][0]=1;

	roop(i, n) {
		if(s[i]=='?'){
			roop(k, 10){
				roop(j, N) {
					dp[i + 1][(10*j+k) % N] += dp[i][j];
					dp[i + 1][(10*j+k) % N] %= mod;
				}
			}
		} else {
			int k = s[i]-'0';
			roop(j, N) {
				dp[i + 1][(10*j+k) % N] += dp[i][j];
				dp[i + 1][(10*j+k) % N] %= mod;
			}
		}
	}
	ull ans = dp[n][5]%mod;
	cout << ans << endl;
	return 0;
}

