            for (int k = 0; k < 13; k++) {
                new_reminds[(i * position + k) % 13] += reminds[k];
                new_reminds[(i * position + k) % 13] %= mod;
            }
        }
        position *= 10;
        position %= 13;

        std::copy(std::begin(new_reminds), std::end(new_reminds), reminds);
