int main() {
  std::string s;
  std::cin >> s;

  std::vector<int64_t> l1(13, 0), l2(13, 0);

  if (s[0] == '?') {
    for (int64_t i = 0; i < 10; i++) {
      l1[i] = 1;
    }
  } else {
    l1[s[0] - '0'] = 1;
  }

  constexpr int64_t mod = 1000000007;
  for (int64_t i = 1; i < s.size(); i++) {
    if (s[i] == '?') {
      std::fill(l2.begin(), l2.end(), 0l);
      for (int64_t j = 0; j < 10; j++) {
        for (int64_t k = 0; k < 13; k++) {
          l2[(k * 10 + j) % 13] += l1[k];
          l2[(k * 10 + j) % 13] %= mod;
        }
      }
    } else {
      const int64_t n = s[i] - '0';

      for (int64_t j = 0; j < 13; j++) {
        l2[(j * 10 + n) % 13] = l1[j];
      }
    }
    std::swap(l1, l2);
  }

  std::cout << l1[5] << std::endl;

  return 0;
}

