void C_City_Saver(void) {

	int N; cin >> N;
	vector<int> A(N + 1), B(N);
	for (int& it : A) cin >> it;
	for (int& it : B) cin >> it;

	long long counter = 0;
	rep(index, N) {
		int enemy = min(A[index] + A[index + 1], B[index]);
		counter += enemy;
		A[index + 1] -= max(enemy - A[index], 0);
	}

	cout << counter << endl;
	return;
}

