    if (digit >= S.size()) {
        return rest == 5;
    }

    if (memo[digit][rest] != -1) {
        return memo[digit][rest];
    }

    LL ans = 0;
    if (S[digit] == '?') {
        int upper = 9;
        for (int i = 0; i < upper + 1; ++i) {
            (ans += digit_dp(digit + 1, (rest * 10 + i) % 13, S)) %= MOD;
        }
    }
    else {
        int d = S[digit] - '0';
        (ans += digit_dp(digit + 1, (rest * 10 + d) % 13, S)) %= MOD;
    }

    return memo[digit][rest] = ans;
}

