template<typename T, T mod>
struct ModInt {
    T val;
    ModInt(T val=0) : val(((val % mod) + mod) % mod) {}

    const ModInt operator+() const { return *this; }
    const ModInt operator-() const { return (-val + mod) % mod; }
    const ModInt reciprocal() const { return power(mod-2); }

    ModInt& operator+=(const ModInt& rhs) { (val += rhs.val) %= mod; return *this; }
    ModInt& operator-=(const ModInt& rhs) { return *this += -rhs; }
    ModInt& operator*=(const ModInt& rhs) { (val *= rhs.val) %= mod; return *this; }
    ModInt& operator/=(const ModInt& rhs) { return *this *= rhs.reciprocal(); }

    const ModInt operator+(const ModInt& rhs) const { return ModInt(*this) += rhs; }
    const ModInt operator-(const ModInt& rhs) const { return ModInt(*this) -= rhs; }
    const ModInt operator*(const ModInt& rhs) const { return ModInt(*this) *= rhs; }
    const ModInt operator/(const ModInt& rhs) const { return ModInt(*this) /= rhs; }

    const ModInt power(long long n) const {
        ModInt ret = 1, tmp = val;
        while (n > 0) {
            if (n & 1) ret *= tmp;
            tmp *= tmp;
            n >>= 1;
        }
        return ret;
    }

    bool operator==(const ModInt& rhs) const { return val == rhs.val; }
    bool operator!=(const ModInt& rhs) const { return !(*this == rhs); }
};

template<typename T, T mod>
const ModInt<T, mod> operator+(const T& lhs, const ModInt<T, mod>& rhs) {
    return ModInt<T, mod>(lhs) + rhs;
}
template<typename T, T mod>
const ModInt<T, mod> operator-(const T& lhs, const ModInt<T, mod>& rhs) {
    return ModInt<T, mod>(lhs) - rhs;
}
template<typename T, T mod>
const ModInt<T, mod> operator*(const T& lhs, const ModInt<T, mod>& rhs) {
    return ModInt<T, mod>(lhs) * rhs;
}
template<typename T, T mod>
const ModInt<T, mod> operator/(const T& lhs, const ModInt<T, mod>& rhs) {
    return ModInt<T, mod>(lhs) / rhs;
}

template<typename T, T mod>
bool operator==(const T& lhs, const ModInt<T, mod>& rhs) {
    return ModInt<T, mod>(lhs) == rhs;
}
template<typename T, T mod>
bool operator!=(const T& lhs, const ModInt<T, mod>& rhs) {
    return ModInt<T, mod>(lhs) != rhs;
}

template<typename T, T mod>
auto& operator<<(ostream& s, const ModInt<T, mod>& obj) { s << obj.val; return s; }

