int main(){

  string S; cin >> S;

  int length = S.length();

  ll DP[length][13];

  for (int i = 0; i < length; i++){
    for (int j = 0; j < 13; j++){
      DP[i][j] = 0;
    }
  }


  if (S[0] == '?'){
    for (int i = 0; i <= 9; i++){
      DP[0][i] = 1;
    }
  }else{
    int A = S[0] - '0';
    DP[0][A] = 1;
  }

  for (int i = 1; i < length; i++){
    if (S[i] == '?'){
      for(int A = 0; A < 10; A++){
        for (int j = 0; j < 13; j++){
          DP[i][(j * 10 + A) % 13] += DP[i - 1][j];
        }
      }
    }else{
      int A = S[i] - '0';
      for (int j = 0; j < 13; j++){
        DP[i][(j * 10 + A) % 13] += DP[i - 1][j];
      }
    }

    for (int j = 0; j < 13; j++){
      DP[i][j] = DP[i][j] % nmax;
    }
  }
  cout << DP[length - 1][5] << endl;

  return 0;
}

