int main(){
    string S;
    cin >> S;
    int N = S.size();

    const int64_t MOD = 1e9+7;

    // dp[i][j] : i文字目までを見た時に作れる数で、13で割った余りがjであるものの個数（を、MODで割った余り）
    static int64_t dp[100001][13] = {0};
    // 初期状態。dp[0][0]に「数字を1文字も付け足していないもの」1通りを追加
    dp[0][0] = 1;

    for(int i=0; i<N; i++){
        // 13通りの遷移元を全て回る
        for(int j=0; j<13; j++){
            // Sのi+1文字目を確認するが、0-indexedなのでS[i]として見る
            if(S[i] == '?'){
                // ?なら10通り遷移
                for(int b=0; b<=9; b++){
                    int j2 = (10*j+b) % 13;
                    dp[i+1][j2] = (dp[i+1][j2] + dp[i][j]) % MOD;
                }
            }else{
                // 数字ならその数だけ遷移
                int b = S[i] - '0';
                int j2 = (10*j+b) % 13;
                dp[i+1][j2] = (dp[i+1][j2] + dp[i][j]) % MOD;
            }
            // dpの計算の途中で随時、MOD=1e9+7で割った余りを取る
        }
    }

    // これが答え
    cout << dp[N][5] << endl;
    return 0;
}

