int solve(int pos, int mod) {
	if(pos == n)
		return mod == 5;

	if(memo[pos][mod] != -1)
		return memo[pos][mod];

	int res = 0;
	if(S[pos] == '?') {
		for(int i = 0; i <= 9; i++)
