ll dp[100001][13];

ll rec(ll d = 0, ll rem = 0) {
  ll &cc = dp[d][rem];
  if (~cc) return cc;
  if (d == N) return cc = rem%13 == 5;
  char c = S[d];
  if (c != '?') {
    ll m_d = (ll)(c - '0');
    m_d = (m_d * mul[d] + rem) % 13;
