            for (int k=0; k<10; k++) {
                for (int j=0; j<13; j++) {
                    dp[i+1][(digit*k+j)%13] += dp[i][j];
                }
            }
        }

        for (int k=0; k<13; k++) dp[i+1][k] %= MOD;
        digit *= 10;
        digit %= MOD;
    }

