	n = (int)s.length();
	reverse(s.begin(), s.end());

	pow10[0] = 1;
	for (int i = 1; i < n; i++)
		pow10[i] = (pow10[i - 1] * 10LL) % MOD2;

	dp[0][0] = 1;
	for (int i = 0; i < n; i++)
		for (int j = 0; j < MOD2; j++)
		{
			if (s[i] == '?')
			{
				for (int k = 0; k < 10; k++)
				{
					int newRem = (j + pow10[i] * k) % MOD2;
					dp[i + 1][newRem] += dp[i][j];
					if (dp[i + 1][newRem] >= MOD)
						dp[i + 1][newRem] -= MOD;
				}
			}
			else
			{
				int newRem = (j + pow10[i] * (s[i] - '0')) % MOD2;
				dp[i + 1][newRem] += dp[i][j];
				if (dp[i + 1][newRem] >= MOD)
					dp[i + 1][newRem] -= MOD;
			}
		}
	cout << dp[n][5] << endl;
}

