        }
    }
    dp[0][0]=1;
    for(int i=1; i<=n; i++){
        if(s[i-1]!='?'){
            int number = s[i-1] - '0';
            rep(m,13){
                dp[i][(m*10+number)%13] = (dp[i-1][m]) % MOD;
