#define MOD 1000000007
ll mod_pow(ll x, ll p){
	ll res=1;
	ll n=x;
	while(p>0){
		if(p&1==1)res=(res*n)%13;
		n=(n*n)%13;
		p=(p>>1);
	}
	return res;
}
