    int N=S.size();
    vector<vl> dp(N+1,vl(13,0));
    if(S[0]=='?'){
        for (int i = 0; i < 10; i++){
            int rem=(i*mod_pow(10,N-1))%13;
            dp[0][rem]++;
        }
    }else{
        dp[0][ctoi(S[0])]=1;
    }
    for (int i = 1; i <= N; i++){
        if(S[i-1]=='?'){
            for (int j = 0; j < 10; j++){
                int rem=(j*mod_pow(10,N-i))%13;
                if(i==1){
                    dp[1][rem]++;
                }else{
                    for (int k = 0; k < 13; k++){
                        dp[i][(k+rem)%13]+=dp[i-1][k];
                        dp[i][(k+rem)%13]%=MOD;
                    }
                }
            }
        }else{
            int rem=(ctoi(S[i-1])*mod_pow(10,N-i))%13;
            if(i==1){
                dp[0][ctoi(S[0])]=1;
            }else{
                for (int k = 0; k < 13; k++){
                    dp[i][(k+rem)%13]+=dp[i-1][k];
                    dp[i][(k+rem)%13]%=MOD;
                }
            }
        }
    }
