#define MOD 1000000007

const int K = 13;
const int R = 5;
string S;
vector<ll> A;
int N;
ll dp[100001][15];
ll rec(int n = 0, ll rem = 0) {
  ll &cc = dp[n][rem];
  if (~cc) return cc;
  // cout << S[n] << " " << rem << endl;
  if (n == N) return cc = rem == R;
  if (S[n] != '?') {
    ll d = S[n] - '0';
    rem += d * A[n];
    return cc = rec(n+1, rem % K);
  }

  ll ways = 0;
  for (ll d=0; d<10; d++) {
    ll r = (rem + d * A[n]) % K;
    ways += rec(n+1, r);
    ways %= MOD;
  }
  return cc = ways;
}
void solve() {
  cin >> S;
  N = S.size();
  A.resize(N);
  reverse(S.begin(), S.end());
  A[0] = 1;
  loop(n,1,N) A[n] = A[n-1] * 10;
  memset(dp, -1, sizeof(dp));

  cout << rec() << endl;
}
int main() {
  // cout.precision(15); cout << fixed;

  solve();

  return 0;
}

