        } else {
            for (int p = 0; p < 10; p++) {
                int r = (p * digit) % 13;
                for (int j = 0; j < 13; j++) {
                    dp[i][j] = mod_add(dp[i][j], dp[i - 1][(13 + j - r) % 13]);
                }
            }
        }
        digit = (digit * 10) % 13;
    }
    cout << dp[len][5] << endl;
    return 0;
}

