    if(n[i]=='?') {
        for(int num=0; num < 10; num++) {
            for(int j=0; j < 13; j++) {
                dp[i+1][(j*10+num)%13] += dp[i][j];
                dp[i+1][(j*10+num)%13] %= MOD;
