#include <bits/stdc++.h>
using namespace std;

const int64_t MOD = 1e9 + 7;
struct mint
{
    int64_t x;
    mint(int64_t x = 0) : x((x % MOD + MOD) % MOD) {}
    mint operator-() const { return mint(-x); }
    mint &operator+=(const mint a)
    {
        if ((x += a.x) >= MOD)
            x -= MOD;
        return *this;
    }
    mint &operator-=(const mint a)
    {
        if ((x += MOD - a.x) >= MOD)
            x -= MOD;
        return *this;
    }
    mint &operator*=(const mint a)
    {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator+(const mint a) const { return mint(*this) += a; }
    mint operator-(const mint a) const { return mint(*this) -= a; }
    mint operator*(const mint a) const { return mint(*this) *= a; }
    mint pow(int64_t n) const
    {
        if (n == 0)
            return 1;
        mint t = pow(n >> 1);
        t *= t;
        if (n & 1)
            t *= *this;
        return t;
    }
    mint inv() const { return pow(MOD - 2); }
    mint &operator/=(const mint a) { return *this *= a.inv(); }
    mint operator/(const mint a) const { return mint(*this) /= a; }
};

void solve(string S)
{
    reverse(S.begin(), S.end());
    vector<vector<mint>> dp(S.size() + 1, vector<mint>(13));
    dp.at(0).at(0) = 1;
    vector<int> r(10);
    for (int i = 0; i < 10; i++)
    {
        r.at(i) = i;
    }

    for (int i = 0; i < S.size(); i++)
    {
        if (S.at(i) != '?')
        {
            int c = S.at(i) - '0';
            for (int j = 0; j < 13; j++)
            {
                int j_next = (j + r.at(c)) % 13;
                dp.at(i + 1).at(j_next) += dp.at(i).at(j);
            }
        }
        else
        {
            for (int c = 0; c < 10; c++)
            {
                for (int j = 0; j < 13; j++)
                {
                    int j_next = (j + r.at(c)) % 13;
                    dp.at(i + 1).at(j_next) += dp.at(i).at(j);
                }
            }
        }
        for (int i = 0; i < 10; i++)
        {
            r.at(i) = 10 * r.at(i) % 13;
        }
