long long modpow(long long x, long long y){
    if (y == 0) return 1;
    if (y % 2 == 0) return modpow(x, y / 2) * modpow(x, y / 2) % mod;
    return x * modpow(x, y - 1) % mod;
}

void dfs(vector<int> &cnt, vector<int> &tmp, vector<int> &data, long long &ans, vector<vector<long long>> &pre){
    bool flag = false;
    int check = - 1;
    for (int i = 0; i < 6; i++){
        if (data[i] == - 1) {
            flag = true;
            check = i;
        }
        if (flag) break;
    }
    if (flag){
        for (int i = 0; i < 13; i++){
            data[check] = i;
            dfs(cnt, tmp, data, ans, pre);
            data[check] = - 1;
        }
    }
    else {
        int check = 0;
        for (int i = 0; i < 6; i++) check += data[i];
        if (check % 13 == 5){
            long long tmp = 1;
            for (int i = 0; i < 6; i++){
                tmp *= pre[i][data[i]];
                tmp %= mod;
            }
            ans += tmp;
            ans %= mod;
        }
    }
}

