const int MOD = 1000000007;

int main()
{
	string S;
	cin >> S;

	int n = S.size();

	// 動的計画法
	vector<vector<long>> dp(n + 1, vector<long>(13, 0));

	// dpの初期化
	dp[0][0] = 1;

	for (int i = 0; i < n; i++)
	{
		int c = 0;
		if (S[i] == '?')
		{
			c = -1;
		}
		else {
			c = S[i] - '0';
		}

		for (int j = 0; j < 10; j++)
		{
			if (c != -1 && c != j)
			{
				continue;
			}

			for (int k = 0; k < 13; k++)
			{
				dp[i + 1][(k * 10 + j) % 13] += dp[i][k];
			}
		}

		for (int j = 0; j < 13; j++)
		{
			dp[i + 1][j] %= MOD;
		}
	}


	// 答えの5あまる数を出力する
	long answer = dp[n][5];
	cout << answer << endl;

	return 0;
}

