const int MOD = 1e9+7;
const int N_MAX = 1e5;
long long int dp[N_MAX + 1][13];

void do_dp(int a, int dig, int mod_13){
  for(int k = 0; k <= 12; k++){
    if(k >= dig) dp[a][k] += dp[a+1][k-dig];
    else dp[a][k] += dp[a+1][13+k-dig];

    dp[a][k] %= MOD;
  }
}

int main(){
  string s; cin>>s;
  int n = s.size();

  memset(dp, 0, sizeof dp);

  int mod_13 = 10;

  if(s[n-1] == '?'){
    for(int i = 0; i <= 9; i++) dp[n-1][i] = 1;
  }else{
    dp[n-1][s[n-1] - '0'] = 1;
  }

  for(int i = n-2; i>=0; i--){
    int dig;
    if(s[i] == '?'){
      for(int j = 0; j <= 9; j++){
        dig = (mod_13 * j) % 13;
        do_dp(i, dig, mod_13);
      }
    }else{
      dig = s[i] - '0';
      dig = (mod_13 * dig) % 13;
      do_dp(i, dig, mod_13);
    }

    mod_13 = (mod_13 * 10) % 13;
  }

  cout<< dp[0][5]<<endl;
}

