const int M = 1e5 + 10;
int dp[M][13], powers[M];

int solve(int i, int j)
{
    if (dp[i][j] != -1)
        return dp[i][j];

    if (i == n-1)
    {
        if (s[i] != '?')
        {
            if ((s[i]-'0') == j)
                return 1;
            return 0;
        }

        if (j <= 9)
            return 1;
        return 0;
    }

    if (s[i] != '?')
    {
        int val = ((s[i]-'0')*powers[i])%13;
        int d = (j-val+13)%13;
        dp[i][j] = solve(i+1, d);
    }

    else
    {
        int ans = 0;
        FOR(k,0,10)
        {
            int val = (k*powers[i])%13;
            int d = (j-val+13)%13;
            ans = (ans + solve(i+1, d))%modulo;
        }
        dp[i][j] = ans;
    }

    return dp[i][j];

}

