                // ?なら10通り遷移
                for(int b=0; b<=9; b++){
                    int j2 = (10*j+b) % 13;
                    dp[i+1][j2] = (dp[i+1][j2] + dp[i][j]) % MOD;
                }
            }else{
                // 数字ならその数だけ遷移
                int b = S[i] - '0';
                int j2 = (10*j+b) % 13;
                dp[i+1][j2] = (dp[i+1][j2] + dp[i][j]) % MOD;
            }
            // dpの計算の途中で随時、MOD=1e9+7で割った余りを取る
        }
    }

    // これが答え
