                dp[k+1][(i*10%13+(s[k+1] - '0'))%13] += dp[k][i];
                dp[k+1][(i*10%13+(s[k+1] - '0'))%13] %= MODNum;
            }
        }
    }
    cout << dp[s.size()-1][5] << endl;
    return 0;
}

