// x の n 乗 を m で余りをとったもの
ll mod_pow(ll x, ll n, ll mod) {
    ll res = 1;
    while ( n > 0) {
        if (n & 1) { res = res * x % mod; } // 最下位ビットが立っているときに x^(2^i) を掛ける
        x = x * x % mod;                    // x を順次 2 乗していく
        n >>= 1;
    }
    return res;
}

string S;
ll dp[MAX_N][20];

// 右から k 番目を見ていて、現在のあまりが mod のときのパターン数
ll dfs(ll k, ll mod) {
    if(k < 0) {
        return (mod == 5) ? 1 : 0;
    }

    ll x = (S[k] == '?') ? -1 : (S[k] - '0');  // 今見ている数字

    ll& res = dp[k][mod];
    if(~res) { return res; }
    res = 0;

    ll k_inv = S.length() - k - 1;

    if(x == -1) {
        for(ll i = 0; i <= 9; ++i) {
            ll tmp = i * mod_pow(10, k_inv, 13);
            tmp %= 13;
            tmp += mod;
            tmp %= 13;
            res += dfs(k-1, tmp);
            res %= MOD;
        }
    }
    else {
        ll tmp = x * mod_pow(10, k_inv, 13);
        tmp %= 13;
        tmp += mod;
        tmp %= 13;
        res += dfs(k-1, tmp);
        res %= MOD;
    }
    return res;
}

