// index が条件を満たすかどうか
bool isOK(vector<ll>& v, int index, int key) {
	if (v[index] >= key) return true;
	else return false;
}

// 汎用的な二分探索	
ll bs(vector<ll> & v, int key) {
	int ng = -1; //「index = 0」が条件を満たすこともあるので、初期値は -1
	int ok = SZ(v); // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

	/* ok と ng のどちらが大きいかわからないことを考慮 */
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;

		if (isOK(v, mid, key)) ok = mid;
		else ng = mid;
	}
	return ok;
}

// 最大公約数
ll gcd(ll a, ll b) {
	if (a < b)	swap(a, b);
	ll r = a % b;
	while (r != 0) {
		a = b;
		b = r;
		r = a % b;
	}
	return b;

}

// 素因数分解 
// cnt_pf[i]にi+1で割った回数を格納している
// cnt_pf[0]に入力が素数だった場合にその素数が入る
vector<ll> prime_factorization(ll n) {
	vector<ll> cnt_pf(ceil(sqrt(n)), 0);
	FOR(i, 1, SZ(cnt_pf)) {
		while (n % (i + 1) == 0) {
			cnt_pf[i]++;
			n /= (i + 1);
		}
		if (n == 1)	break;
	}
	if (n != 1) {
		cnt_pf[0] = n;
	}
	return cnt_pf;
}

