int modulo(int e) {
    ll b = 10, ret = 1;
    while (e) {
        if (e & 1) ret *= b;
        ret %= 13;
        e >>= 1;
        b *= b;
        b %= 13;
    }
    return (int)ret;

}

int main(void) {
