    if (S[N-1] == '?') {
        for (int j=0;j<10;j++) dp[1][j] = 1;
    } else {
        dp[1][S[N-1]-'0'] = 1;
    }
    for (int i=2;i<=N;i++) {
        int m = modulo(i-1);
        if (S[N-i] == '?') {
            for (int j=0;j<10;j++) for (int k=0;k<13;k++) {
