ll modPow(ll a, ll n,ll p) {
  if (n == 0) return 1; // 0乗にも対応する場合
  if (n == 1) return a % p;
  if (n % 2 == 1) return (a * modPow(a, n - 1,p)) % p;
  ll t = modPow(a, n / 2,p);
  return (t * t) % MOD;
}

