#define mop 1000000007
using namespace std;

ll fastPow(ll a, ll b, ll mod=0){
    if(a == 0 and b == 0){
        return -1;
    }
    if(a == 0){
        return 0;
    }
    if(b == 0){
        return 1;
    }
    ll tmp = fastPow(a,b/2,mod);
    if(mod != 0) {
        if (b % 2 == 0) {
            return (tmp * tmp) % mod;
        } else {
            return ((tmp*tmp) % mod * (a % mod)) % mod;
        }
    }else{
        if (b % 2 == 0) {
            return (tmp*tmp);
        } else {
            return tmp * tmp * a;
        }
    }
}

int main() {

    const ll X = 100001;
    string s;
    cin >> s;
    ll numList[X] = {};
    for(ll i=s.length();i>0;i--){
        if(s[i-1] == '?'){
            numList[s.length() - i + 1] = -1;
        }else{
            numList[s.length() - i + 1] = s[i-1] - '0';
        }
    }
    ll dp[2][13] = {};
    dp[0][0] = 1;

    for (ll i=0;i<s.length();i++){
        ll fast = fastPow(10,i,13);
        for(ll j=0;j<13;j++){
            if(numList[i+1] == -1) {
                for (ll k = 0; k <= 9; k++) {
                    ll tmp = j - (fast * k) % 13;
                    if (tmp < 0) {
                        tmp += 13;
                    }
                    dp[1][j] += dp[0][tmp];
                }
            }else{
                for (ll k = numList[i+1]; k <= numList[i+1]; k++) {
                    ll tmp = j - (fast * k) % 13;
                    if (tmp < 0) {
                        tmp += 13;
                    }
                    dp[1][j] += dp[0][tmp];
                }
            }
        }
        for(ll j=0;j<13;j++){
            dp[0][j] = dp[1][j] % mop;
            dp[1][j] = 0;
        }
    }

    cout << dp[0][5] << endl;
}

