int main()
{
  string s;
  cin >> s;
  reverse(s.begin(), s.end());

  vector<vector<long long>> digit(s.size(), vector<long long>(10));
  for (long long i = 0; i < 10; i++) {
    digit.at(0).at(i) = i;
  }
  for (long long i = 1; i < (long long)digit.size(); i++) {
    for (long long d = 1; d < 10; d++) {
      digit.at(i).at(d) = (digit.at(i-1).at(d) * 10) % 13;
    }
  }

  vector<vector<long long>> dp(s.size(), vector<long long>(13));
  if (s.front() == '?') {
    for (long long i = 0; i < 10; i++) {
      dp.at(0).at(i) = 1;
    }
  } else {
    long long x = s.front() - '0';
    dp.at(0).at(x) = 1;
  }
  for (long long i = 1; i < (long long)s.size(); i++) {
    char c = s.at(i);
    if (c == '?') {
      for (long long x = 0; x < 10; x++) {
        for (long long r = 0; r < 13; r++) {
          long long next_r = (r + digit.at(i).at(x)) % 13;
          dp.at(i).at(next_r) += dp.at(i-1).at(r);
          dp.at(i).at(next_r) %= kMod;
        }
      }
    } else {
      long long x = c - '0';
      for (long long r = 0; r < 13; r++) {
        long long next_r = (r + digit.at(i).at(x)) % 13;
        dp.at(i).at(next_r) += dp.at(i-1).at(r);
        dp.at(i).at(next_r) %= kMod;
