#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll mod = 1e9 + 7, mod2 = 13, dp[15][100005];
ll modpow(ll base, ll power)
{
	ll res = 1;
	while (power) {
		if (power & 1)
			res = res * base % mod2;
		base = base * base % mod2;
		power >>= 1;
	}
	return res;
}
inline void shift(ll rem, ll pos)
{
	for (int i = 0; i < 13; ++i)
		dp[i][pos] = (dp[i][pos] + dp[(i - rem + mod2) % mod2][pos + 1]) % mod;
}
void solve(string &s)
{
	if (isdigit(s[s.length() - 1]))
		dp[s[s.length() - 1] - '0'][s.length() - 1] = 1;
	else
		for (int i = 0; i < 10; ++i)
			dp[i][s.length() - 1] = 1;
	for (int i = s.length() - 2, p = 1; i >= 0; --i, ++p) {
		ll t = modpow(10, p), rem;
		if (s[i] != '?') {
			ll num = s[i] - '0';
			rem = (num * t) % mod2;
			shift(rem, i);
		}
		else {
			for (int j = 0; j < 10; ++j) {
				rem = j * t % mod2;
				shift(rem, i);
			}
		}
	}
}
int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);
	string s;
	cin >> s;
	solve(s);
	cout << dp[5][0] << '\n';
	return 0;
}

