long long solve(int in, int md) {

	if(in == n) return md==0;
	if(dp[in][md]!=-1) 
		return dp[in][md];
	long long ans =0;
	if(s[in]=='?') {
		int i;
		for(i=0;i<=9;i++){
			int x = ( (md - i*pow10th[n-1-in])%13 + 13)%13;
			ans+=solve(in+1, x);
			ans%=MOD;
		}
	} else {
		int d = s[in]-'0';
		int x = ( (md - d*pow10th[n-1-in])%13 + 13)%13;
		ans =  solve(in+1, x);
	}
	return dp[in][md] = ans;
}


