typedef  long long ll;
#define mop 1000000007
using namespace std;

ll fastPow(ll a, ll b, ll mod=0){
//    cout << a << " " << b << " " << mod << endl;
    if(a == 0 and b == 0){
        return -1;
    }
    if(a == 0){
        return 0;
    }
    if(b == 0){
        return 1;
    }
    if(mod != 0) {
        if (b % 2 == 0) {
//            return 1;
            return (fastPow(a, b / 2, mod) * fastPow(a, b / 2, mod)) % mod;
        } else {
//            return 0;
            return ((fastPow(a, b / 2, mod) * fastPow(a, b / 2, mod)) % mod * a % mod) % mod;
        }
    }else{
        if (b % 2 == 0) {
//            return 1;
            return (fastPow(a, b / 2, mod) * fastPow(a, b / 2, mod));
        } else {
//            return 0;
            return fastPow(a, b / 2, mod) * fastPow(a, b / 2, mod) * a;
        }
    }
}

