namespace algolib {
namespace NT {

template <typename Int>
inline std::tuple<Int, Int, Int> euclid(Int a, Int b) {
    Int r0 = a, s0 = 1, t0 = 0;
    Int r1 = b, s1 = 0, t1 = 1;
    Int q, rtmp, stmp, ttmp;
    while (r1) {
        q = r0 / r1;
        rtmp = r0 - q*r1, stmp = s0 - q*s1, ttmp = t0 - q*t1;
        r0 = r1, s0 = s1, t0 = t1;
        r1 = rtmp, s1 = stmp, t1 = ttmp;
    }
    return {r0, s0, t0};
}

template <typename Int>
inline Int gcd(Int a, Int b) {
    return std::get<0>(euclid(a, b));
}

template <typename Int>
inline Int lcm(Int a, Int b) {
    return (intmax_t)a*b/gcd(a, b);
}

template <typename Int>
inline auto factor(Int n) {
    std::vector<std::pair<Int, int>> ret;
    for (Int i = 2; i <= n; ++i) {
        int ct = 0;
        while (n % i == 0) {
            n /= i;
            ++ct;
        }
        if (ct) ret.push_back({i, ct});
    }
    return ret;
}

template <typename Int>
inline Int pow(Int n, int64_t k) {
    Int res = 1;
    for (int x = 1; x <= k; x <<= 1) {
        if (k & x) res *= n;
        n *= n;
    }
    return res;
}

template <typename Int>
inline Int totient(Int n) {
    auto v = factor(n);
    Int res = 1;
    for (const auto& [p, k] : v) {
        res *= pow(p, k) - pow(p, k-1);
    }
    return res;
}

template <typename Int>
inline int moebius(Int n) {
    auto v = factor(n);
    int res = 1;
    for (const auto& [p, k] : v) {
        if (k > 1) return 0;
        res *= -1;
    }
    return res;
}

template <typename Int>
inline Int sigma(Int n, int x = 1) {
    auto v = factor(n);
    Int res = 1;
    for (const auto& [p, k] : v) {
        res *= (pow(p, (k+1)*x) - 1) / (pow(p, x) - 1);
    }
    return res;
}

}
