namespace algolib {
namespace NT {

template <int M>
struct Modulo {
    static const int MOD = M;
    int val;
    Modulo() : val(0) {}
    Modulo(int64_t val) : val((val % M + M) % M) {}
    Modulo& operator+=(const Modulo& rhs) { return *this = val + rhs.val; }
    Modulo operator+() const { return +val; }
    Modulo operator-() const { return -val; }
    Modulo& operator-=(const Modulo& rhs) { return *this = *this + (-rhs); }
    Modulo& operator*=(const Modulo& rhs) { return *this = 1LL * val * rhs.val; }
    Modulo inv() const {
        auto [d, x, _] = euclid(val, M);
        assert(d == 1 && "val should be coprime to M.");
        return x;
    }
    Modulo pow(int64_t k) const {
        if (k < 0) return inv().pow(-k);
        return NT::pow(*this, k);
    }
    Modulo& operator/=(const Modulo& rhs) { return *this *= rhs.inv(); }
    Modulo& operator++() { return *this += 1; }
    Modulo operator++(int) { int tmp = val; ++*this; return tmp; }
    Modulo& operator--() { return *this -= 1; }
    Modulo operator--(int) { int tmp = val; --*this; return tmp; }
    friend Modulo operator+(Modulo lhs, const Modulo& rhs) { return lhs += rhs; }
    friend Modulo operator-(Modulo lhs, const Modulo& rhs) { return lhs -= rhs; }
    friend Modulo operator*(Modulo lhs, const Modulo& rhs) { return lhs *= rhs; }
    friend Modulo operator/(Modulo lhs, const Modulo& rhs) { return lhs /= rhs; }
    friend bool operator==(const Modulo& lhs, const Modulo& rhs) { return lhs.val == rhs.val; }
    friend bool operator!=(const Modulo& lhs, const Modulo& rhs) { return lhs.val != rhs.val; }
    friend std::istream& operator>>(std::istream& is, Modulo& x) { int64_t n; is >> n; x = Modulo(n); return is; }
    friend std::ostream& operator<<(std::ostream& os, const Modulo& x) { return os << x.val; }
};

