template <typename Int>
inline Int CRT(const std::vector<std::pair<Int, Int>>& remainders) {
    Int totmod = 1;
    for (const auto& [_, modulus] : remainders) totmod *= modulus;
    Int res = 0;
    for (const auto& [rem, modulus] : remainders) {
        Int term = rem;
        for (const auto& [_, mod] : remainders) if (mod != modulus) {
            auto [d, modinv, _] = euclid(mod, modulus);
            assert(d == 1);
            term = (((term * mod) % totmod) * modinv) % totmod;
        }
        res = (res + term) % totmod;
    }
    return res;
}

}
