constexpr int MOD = 1e9 + 7;
using Mod = algolib::NT::Modulo<MOD>;

Mod solve(const string& S) {
    vector<Mod> ct(13);
    ct[0] = 1;
    for (char c : S) {
        auto old = ct;
        fill(ct.begin(), ct.end(), 0);
        auto add = [&] (int r0, int d) {
            int r = (r0 * 10 + d) % 13;
            ct[r] += old[r0];
        };
        if (c == '?') {
            REP(d, 10) REP(r, 13) add(r, d);
        } else {
            REP(r, 13) add(r, c-'0');
        }
    }
    return ct[5];
}

