bool used[N][15];
string s;

int recurse(int pos, int rem) {
  if(pos>=(int)(s.size())) {
    return rem==5;
  }

  if(used[pos][rem]) return state[pos][rem];

  long long ans = 0;

  if(s[pos]=='?') {
    for(int i=0;i<10;i++) {
      ans += recurse(pos + 1, (rem * 10 + i) % 13);
    }

    ans %= MOD;
  } else {
    ans = recurse(pos + 1, (rem * 10 + s[pos] - 48) % 13);
  }

  used[pos][rem] = true;
  return state[pos][rem] = ans;
}

