LL dp[100010][13];
string s;
LL mod = 1e9+7;

LL func(LL pos, LL rem, LL p10) // func(pos,rem) ---> way
{
    if(dp[pos][rem]!=-1) return dp[pos][rem];

    if(pos==s.size() && rem==5)
    {
        return 1;
    }
    else if(pos==s.size()) return 0;

    LL way=0;

    if(s[pos]=='?')
    {
        for(int i=0;i<=9;i++)
        {
            way+=func(pos+1,(rem+i*p10)%13, (p10*10)%13 );
            way%=mod;
        }
    }
    else
    {
        way+=func(pos+1,(rem+(s[pos]-'0')*p10)%13, (p10*10)%13);
        way%=mod;
    }

    return dp[pos][rem]=way;
}

