inline int sub(int a, int b) { a -= b; if (a < 0) a += MOD; return a; }
inline int mul(int a) { return a; }
template<typename... T> inline int mul(int a, T... b) { return (int) ((ll) a * (ll) mul(b...) % MOD); }
inline int power(int a, int b) {
  int res = 1;
  while (b) {
    if (b & 1) {
      res = mul(res, a);
    }
    a = mul(a, a);
    b >>= 1;
  }
  return res;
}

