int rec(int i, int m) {
  if(i == n) {
    return int(m == 5);
  }
  if(dp[i][m] != -1) return dp[i][m];
  dp[i][m] = 0;
  if(s[i] != '?') {
    dp[i][m] = rec(i + 1, (10 * m + int(s[i] - '0')) % M); 
  } else {
    for(int d = 0; d < 10; ++d) {
      dp[i][m] = add(dp[i][m], rec(i + 1, (10 * m + d) % M));
    }
  }
  return dp[i][m];
}

