    int div = 1e9+7;

    dp[n][0] = 1;

    int r = 1;
    for (int i = 0; i < n; i++) {
        if (s[i] == '?') {
            for (int j = 0; j < 13; j++) {
                for (int k = 0; k < 10; k++) {
                    int tmp = k * r;
                    dp[i][(j+tmp)%13] = (dp[i][(j+tmp)%13] + dp[i+1][j]) % div;
                }

            }
        } else {
            int k = atoi(s[i]);
            for (int j = 0; j < 13; j++) {
                int tmp = k * r;
                    dp[i][(j+tmp)%13] = (dp[i][(j+tmp)%13] + dp[i+1][j]) % div;
            }
        }
        r = (r * 10) % 13;
    }
    cout << dp[0][5] % div << "\n";

}

