using namespace std;

const ll MOD = 1000000007;
const ll DIV = 13;

int main() {
	string s;
	cin >> s;

	ll N = s.size();
	vector<vector<ll>> dp(N+1, vector <ll> (13, 0));
	ll base = 1;
	for (ll ii = N-1; ii >= 0; --ii){
		ll keta = N-1 - ii;
		base = (base * 10) % DIV;  
		ll num = (s[ii] == '?') ? -1 : s[ii] - '0';

		if (keta == 0){
			if (num == -1){
				for (int kk = 0; kk < 10; ++kk){
					dp[keta+1][kk] = 1;
				}
			} else {
				dp[keta+1][num] = 1;
			}
		} else {
			if (num == -1){
				for (int kk = 0; kk < 10; ++kk){
					ll cont = (base * kk) % DIV;
					for (int jj = 0; jj < DIV; ++jj){
						dp[keta+1][(jj+cont)%DIV] = (dp[keta+1][(jj+cont)%DIV] + dp[keta][jj]) % MOD;
					}
				}
			} else {
				ll cont = (base * num) % DIV;
				for (int jj = 0; jj < DIV; ++jj){
					dp[keta+1][(jj+cont)%DIV] = dp[keta][jj];
				}
			}
		}
	}

	cout << dp[N][5] << endl;

	return 0;
}

