int calc(int k, int i)
{
    //k*10**(i+1)を13でわったあまり
    int n=i%6;
    int V[6];
    V[0]=10;
    V[1]=9;
    V[2]=12;
    V[3]=3;
    V[4]=4;
    V[5]=1;
    int ans=V[n];
    ans = ans*k%13;
    return ans;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    string S;
    cin >> S;
    ll dp[10001][13];

    char c = S.back();
    int N=S.size();
    //initislization
    REP(i, 13)
    {
        dp[0][i] = 0;
        if (c == '?')
        {
            if (i <= 9)
                dp[0][i] = 1;
        }
        else
        {
            if (i == c - 48)
            {
                dp[0][i] = 1;
            }
        }
    }
    //update
    REP(i, N - 1)
    {
        c = S[N - 2 - i];
        REP(j, 13)
        {
            dp[i + 1][j] = 0;
            if (c == '?')
            {
                REP(k, 10)
                {
                    int num = j - calc(k,i);
                    int index = num >= 0 ? num : 13 + num;
                    dp[i + 1][j] += dp[i][index];
                }
            }
            else
            {
                int num = j - calc((int)c-48,i);
                int index = num >= 0 ? num : 13 + num;
                dp[i + 1][j] = dp[i][index];
            }
            dp[i+1][j]=dp[i+1][j]%MOD;
        }
    }
    cout << dp[N - 1][5] << endl;
    return 0;
}

