int expo(int a, int n){
    int r = 1;
    while(n){
        if(n % 2) r = r * a % 13;
        a = a * a % 13;
        n /= 2;
    }
    return r;
}

int fun(int ind, int cur){
    if(ind < 0){
        if(cur % 13 == 5) return 1;
        else return 0;
    }
    if(dp[ind][cur] != -1) return dp[ind][cur];

    if(s[ind] != '?'){
        int x = (s[ind] - '0') * expo(10, ind-n+1) % 13;
        return dp[ind][cur] = fun(ind-1, (cur + x)%13);
    }
    else{
        int here = 0;
        for(int i = 0; i <= 9; i++){
            int x = i * expo(10, ind-n+1) % 13;
            here = (here + fun(ind-1, (cur+x)%13)) % mod;
        }
        return dp[ind][cur] = here;
    }
}

void solve(){
    cin >> s;
    n = sz(s);
    memset(dp, -1, sizeof dp);
    cout << fun(n-1, 0) % mod;
}

