  for(int i = 0; i < n; i++){
    vector<ll> ndp(13, 0);
    int val = (s[i] == '?' ? -1 : s[i] - '0');
    for(int j = 0; j < 13; j++){
      if(val == -1){
        for(int k = 0; k < 10; k++){
          int nex = (j * 10 + k) % 13;
          (ndp[nex] += dp[j]) %= MOD;
        }
      }
      else{
        int nex = (j * 10 + val) % 13;
        (ndp[nex] += dp[j]) %= MOD;
      }
    }
