typedef long long int ll;
const int MAX = 1e5 + 10;
const ll MOD=1e9 + 7;




void rev(string &s){
	int n=s.length();
	for(int i=0,j=n-1;i<=j;i++,j--){
		swap(s[i],s[j]);
	}
}


ll mod9(ll x){
	x %= MOD;
	if(x < 0) x += MOD;
	return x;
}


ll pow(ll x,ll n){
	if(n==0) return 1;
	ll t = pow(x,n/2);
	t=mod9(t*t);
	if(n%2==1)t=mod9(t*x);
	return t;
}




ll mod13(ll x){
	x %= 13;
	if(x < 0) x += 13;
	return x;
}

int main()
{
