			}
		}
		else{
			for(int lr=0;lr<13;lr++){
					dp[i][mod13(lr + pow(10,i)*(s[i]-'0'))] = mod9(dp[i][mod13(lr + pow(10,i)*(s[i]-'0'))] + dp[i-1][lr]);
				}
