#include <bits/stdc++.h>
using namespace std;


const int modulo = 1000000007;

int ctoi(char a){
  return a - '0';
}

int main(){
  string s; cin >> s;
  vector<vector<long> > dp(s.length(), vector<long>(13, 0));
  // init
  if(s[0] == '?'){
    for (int i = 0; i < 10; i++) dp[0][i] = 1;
  } else {
    dp[0][ctoi(s[0])] = 1;
  }

  for (int i = 1; i < s.length(); i++) {
    for(int j = 0; j < 13; j++) {
      if(s[i] == '?') {
        for(int n = 0; n < 10; n++) {
          dp[i][(j * 10 + n) % 13] += dp[i - 1][j];
          dp[i][(j * 10 + n) % 13] = dp[i][(j * 10 + n) % 13] % modulo;
        }
      }
      else{
        int n = ctoi(s[i]);
        dp[i][(j * 10 + n) % 13] += dp[i - 1][j];
        dp[i][(j * 10 + n) % 13] = dp[i][(j * 10 + n) % 13] % modulo;
      }
    }
  }

  cout << dp[s.length() - 1][5] % modulo << "\n";
}

