            for(int q=0; q<10; q++){
                int val = q*mod13[i]%13;
                for(int prev=0; prev<13; prev++){
                    dp[i][(val+prev)%13] = (dp[i][(val+prev)%13] + dp[i-1][prev])%mod;
                }
