template<typename T> T modinv(T a, T m) {
	T b = m, u = 1, v = 0;
	while (b) {
		T t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= m;
	if (u < 0) u += m;
	return u;
}
template<typename T> T modpow(T x, int k) {
	if (k == 0)return 1;
	if (k % 2 == 0) return modpow(x * x, k / 2);
	else return x * modpow(x, k - 1);
}

template<int mod> class Modint {
public:
	ll val;
	Modint(ll a) {
		val = a % mod;
	}
	Modint operator+(const Modint& r) {
		return Modint((this->val + r.val) % mod);
	}
	Modint operator-(const Modint& r) {
		return Modint((this->val - r.val) % mod + ((this->val - r.val) % mod < 0) * mod);
	}
	Modint operator*(const Modint& r) {
		return Modint((((this->val % mod) * (r.val % mod))) % mod);
	}
	Modint operator/(const Modint& r) {
		return Modint(this->val * modinv<ll>(r.val, mod) % mod);
	}
	Modint& operator+=(const Modint& r) {
		*this = *this + r;
		return *this;
	}
	Modint& operator-=(const Modint& r) {
		*this = *this - r;
		return *this;
	}
	Modint& operator*=(const Modint& r) {
		*this = *this * r;
		return *this;
	}
	Modint& operator/=(const Modint& r) {
		*this = *this / r;
		return *this;
	}

};

