class Solution {
public:
    int digits_parade(const string& s) {
        vector<int> d(13);
        vector<int> dnext(13);
        d[0] = 1;
        int pow_mod_13 = 1;
        for (int p = s.size() - 1; p >= 0; --p) {
            for (int m = 0; m < 13; ++m) {
                dnext[m] = 0;
                for (int digit = 0; digit <= 9; ++digit) {
                    if (s[p] != '?' && s[p] - '0' != digit) {
                        continue;
                    }
//                    for (int l = 0; l < 13; ++l) {
//                        int cur_mod = ((digit * pow_mod_13) % 13 + l) % 13;
//                        if (cur_mod == m) {
//                            dnext[m] += d[l];
//                            dnext[m] %= MOD;
//                        }
//                    }
                    int digit_mod = (digit * pow_mod_13) % 13;
                    int target_mod = m < digit_mod ? m + 13 : m;
                    dnext[m] += d[target_mod - digit_mod];
                    dnext[m] %= MOD;
                }
            }
            pow_mod_13 *= 10;
            pow_mod_13 %= 13;
            swap(d, dnext);
        }
        return d[5];
    }

private:

};

