long long fac[MAX], finv[MAX], inv[MAX];
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
      fac[i] = fac[i-1] * i % MOD;
      inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
      finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
//組み合わせ
long long COM (int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % MOD) % MOD;
}

void solve() {
		string s; cin >> s;
		int n; n = 13;
		vector<int64> dp(n);
		//dp[k] -> 13で割った余りがkのパターン数(今の状態)
		//余りが0は必ず存在するので1をカウントする
		dp[0] = 1;
		int mul = 1;
		//後ろからカウントする
		//3 -> >?3 -> 2?3のように遷移する
		for (int i = s.length() - 1; i >= 0; --i) {
			//次の状態
			vector<int64> next_dp(n);
			char c = s[i];
			if (c  == '?') {
				//文字が?である場合は0〜9まで遷移させる
				for (int k = 0; k < 10; ++k) {
					//各桁について、13の余りを全て加算して次の桁の余りのパターンをカウントする
					for (int j = 0; j < n; ++j) {
						next_dp[(k * mul  + j) % n] += dp[j];
						next_dp[(k * mul  + j) % n] %= MOD;
					}
				}
			} else {
				int k = (int)(c  - '0');
				for (int j = 0; j < n; ++j) {
					next_dp[(k * mul  + j) % n] += dp[j];
					next_dp[(k * mul  + j) % n] %= MOD;
				}
			}
			mul *= 10;
			mul %= n;
			dp = next_dp;
		}
		cout << dp[5] << endl;
    return;
}

int main() {
    solve();
    return 0;
}

