const int N = (int)1e5 + 3;
const int MOD = (int)1e9 + 7;

string s;
int cnt[15], tmp[15];
int n;

void calc(int l, int r, const VI& poz, int nr) {
  if (nr == (int)poz.size()) {
    int num = 0;
    for (int i = l; i <= r; ++i)
      num = 10*num+(s[i]-'0');
    ++tmp[num%13];
    return;
  }
  for (int i = 0; i < 10; ++i) {
    s[poz[nr]] = (char)(i+'0');
    calc(l, r, poz, nr+1);
  }
}

void jeb(int l, int r, int id) {
  VI poz;
  for (int i = 0; i < 15; ++i)
    tmp[i] = 0;
  for (int i = l; i <= r; ++i)
    if (s[i] == '?')
      poz.PB(i);
  calc(l, r, poz, 0);
  int now[15];
  for (int i = 0; i < 15; ++i)
    now[i] = 0;
  for (int i = 0; i < 13; ++i) {
    for (int j = 0; j < 13; ++j) {
      int val = i;
      if (id&1)
        val = (13-val)%13;
      val += j;
      val %= 13;
      now[val] += tmp[i]*cnt[j]%MOD;
      if (now[val] >= MOD)
        now[val] -= MOD;
    }
  }
  for (int i = 0; i < 13; ++i)
    cnt[i] = now[i];
}

signed main() {
