  int last = n;
  cnt[0] = 1;
  for (int i = n-3; i >= 0; i -= 3) {
    jeb(i, i+2, t);
    ++t;
    last = i;
  }
  if (last != 0)
    jeb(0, last-1, t);
  cout<<cnt[5]<<"\n";
}

