            if (c == -1 || c == j) {
                for (int k=0; k<M; k++) dp[i][(k+j*base)%M] += dp[i-1][k];
            }
        }

        for (int j=0; j<M; j++) dp[i][j] %= p;
        base *= 10; base %= M;
    }

    //result
    printf("%lld\n", dp[n][5]);
}

