constexpr long long int mod = 1000000007LL;
long long int solve(const int position, const int target, const std::vector<int>& questions, std::vector<std::vector<long long int>>& memo) {
	if (position == memo.size()) return (target == 0) ? 1LL : 0LL;
	else if (memo[position][target] >= 0) return memo[position][target];
	else {
		memo[position][target] = 0LL;
		for (auto i = 0; i < 10; ++i) {
			memo[position][target] += solve(position + 1, ((target - questions[position] * i) % 13 + 13) % 13, questions, memo);
		}
		return memo[position][target] %= mod;
	}
}
