		if (str[i] == '?') {
			questions.push_back(digit);
		}
		else {
			whole += digit * (str[i] - '0');
			whole %= 13;
		}
		digit = (digit * 10) % 13;
	}
	const auto target = (18 - whole) % 13;
	std::vector<std::vector<long long int>> memo(questions.size(), std::vector<long long int>(13, -1));
	for (auto i = 1; i < questions.size(); i += 1000) {
		solve(questions.size() - i, 0, questions, memo);
	}
	std::cout << solve(0, target, questions, memo) << std::endl;
}

