int main(void) {
    string S;
    cin >> S;

    dp[0][0] = 1; // dpの初期化。0文字目までの筆算の余りが0になるような置き換えが1通りあると考える。

    //今、筆算をしているのがi文字目
    for (int i = 1; i <= S.length(); i++) {
        // i-1文字目まで筆算した余りを決め打ちしているループ変数remain
        for (int remain = 0; remain < 13; remain++) {
            // i文字目が'?'であるかどうか
            if (S[i-1] == '?') {
                // i文字目が'?'であったら、それをjに置き換えた場合について、それぞれ計算
                for (int j = 0; j <= 9; j++) {
                    int next_remain = (remain * 10 + j) % 13;　// (i-1)文字目までの余りがremainで、i文字目の'?'をjに置き換えた場合の、i文字目まで筆算した余り

                    // dpの遷移
                    dp[i][next_remain] += dp[i-1][remain];
                    dp[i][next_remain] %= MOD;
                }
            } else {
                int i_num = S[i-1] - '0'; // i文字目の数字をi_numに代入
                int next_remain = (remain * 10 + i_num) % 13; // (i-1)文字目までの余りがremainである場合の、i文字目まで筆算した余り

                // dpの遷移
                dp[i][next_remain] += dp[i-1][remain];
                dp[i][next_remain] %= MOD;
            }
        }
    }

    cout << dp[S.length()][5] << endl; // 答えは、S.length()文字目(つまり最後の文字)まで筆算した余りが5になるような'?'の置き換えが何通りあるか。
    return 0;
}

