ll modadd(ll a,ll b,ll mod=MOD){
    return (a%mod+b%mod)%mod;
}

ll modsub(ll a,ll b,ll mod=MOD){
    a%=mod;
    b%=mod;
    if(a>=b) return a-b;
    else return mod-b+a;
}

ll modmul(ll a,ll b,ll mod=MOD){
    return ((a%mod)*(b%mod))%mod;
}

ll modpow(ll a, ll n,ll mod=MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

ll moddiv(ll a,ll b,ll mod=MOD) {
    return modmul(a, modpow(b, mod-2));
}


int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    string S;
    cin>>S;

    ll sum=0;
    vvll A;
    for(int i=0;i<S.size();i++){
        if(S[i]=='?'){
            ll powered=modpow(10,S.size()-1-i,13);
            vll tmp(13,0);
            for(int i=0;i<=9;i++){
                tmp[modmul(i,powered,13)]++;
            }
            A.push_back(tmp);
        }else{
            sum=modadd(sum,modmul(modpow(10,S.size()-1-i,13),S[i]-'0',13),13);
        }
    }

    vvll dp(A.size(),vll(13));

    for(int i=0;i<A.size();i++){
        if(i==0){
            for(int j=0;j<13;j++){
                dp[0][j]=A[i][j];
            }
        }else{
            for(int j=0;j<13;j++){
                for(int k=0;k<13;k++){//k+x=j
                    if(j-k>=0)dp[i][j]=modadd(dp[i][j],modmul(dp[i-1][k],A[i][j-k]));
                    else dp[i][j]=modadd(dp[i][j],modmul(dp[i-1][k],A[i][j+13-k]));
                }
            }
        }
    }

    if(sum<=5) cout<<dp[A.size()-1][5-sum]<<endl;
    else cout<<dp[A.size()-1][18-sum]<<endl;

    return 0;
}

