void solve()
{
      string s; cin>>s;
      ll n=s.size();
      ll dp[n+1][13];
      memset(dp,0,sizeof dp);
      dp[0][0]=1;
      // dp[i][j] - till index i cnt of no. with modulo = j
      for(ll i=1; i<=n; i++)
      {
            if(s[i-1]=='?')
            {
                  // can put any value here from zero to 9
                  for(ll c=0; c<10; c++)
                  {
                        for(ll m=0; m<13; m++)
                        {
                              ll cur=(10*m + c) % 13;
                              dp[i][cur] = (dp[i][cur] + dp[i-1][m]) % mod;
                        }
                  }
            }
            else
            {
                  ll c=s[i-1]-'0';
                  for(ll m=0; m<13; m++)
                  {
                        ll cur=(10*m + c) % 13;
                        dp[i][cur] = (dp[i][cur] + dp[i-1][m]) % mod;
                  }
            }
      }
      ll ans = dp[n][5];
      cout<<ans<<endl;
}

int main() {
	ll T = 1;
	speed_up
	//cin>>T;
	while(T--)
	    solve();
	return 0;
}

