#include <bits/stdc++.h>

using namespace std;

#define	MOD	1000000007

int main(int argc, char *argv[])
{
	string s;
	cin >> s;
	int n = s.size();
	vector<vector<long long> > dp(n, vector<long long>(13));
	reverse(s.begin(), s.end());

	if (s[0] == '?')
		for (int i = 0; i < 10; i++) dp[0][i] = 1;
	else
		dp[0][s[0] - '0'] = 1;

	long long t = 10;
	for (int k = 1; k < n; k++) {
		if (s[k] == '?') {
			for (int i = 0; i < 10; i++)
				for (int j = 0; j < 13; j++)
					dp[k][(i * t + j) % 13] = (dp[k][(i * t + j) % 13] + dp[k - 1][j]) % MOD;
		} else {
			int c = (s[k] - '0') * t;
			for (int j = 0; j < 13; j++)
				dp[k][(c + j) % 13] = (dp[k][(c + j) % 13] + dp[k - 1][j]) % MOD;
		}
		t = (t * 10) % 13;
	}

	cout << dp[n - 1][5] << endl;

	return 0;
}

