const int MOD = 1000000007;

int main(){
  string s; cin >> s;
  int n = s.size();

  int mul = 1;
  vector<vector<int>> dp(n+1,vector<int>(13,0));
  dp[0][0] = 1;
  int deep = 1;
  for(int i = n-1;i >= 0;i--){
    if (s[i] == '?'){
      for(int j=0; j<10;j++){
        int move = j * mul % 13;
        for(int k = 0; k < 13; k++){
          dp[deep][(k+move)%13] += dp[deep-1][k];
          dp[deep][(k+move)%13] %= MOD;
        }
      }
    }else{
      int k = s[i] - '0';
      int move = k * mul % 13; //スライドさせる距離
      for(int j = 0; j < 13;j++){
        dp[deep][(j+move)%13] += dp[deep-1][j];
        dp[deep][(j+move)%13] %= MOD;
      }
    }
    deep++;
    mul *= 10;
    mul %= 13;
  }

  cout << dp[n][5];
  return 0;

}

