#define REP(i, a, n) for (ll i = 0; i < ((ll) n); i++)
using namespace std;
typedef long long ll;

const ll MOD = 1000000007;

int main(void) {
  string S;
  cin >> S;
  ll N = S.length();

  vector<vector<ll>> dp(N + 1, vector<ll>(13));
  dp[0][0] = 1;
  REP(i, 0, N) {
    REP(j, 0, 13) {
      if (S[i] == '?') {
        REP(d, 0, 10) {
          ll r = (j * 10 + d) % 13;
          dp[i + 1][r] += dp[i][j];
          dp[i + 1][r] %= MOD;
        }
      } else {
        ll d = S[i] - '0';
        ll r = (j * 10 + d) % 13;
        dp[i + 1][r] += dp[i][j];
        dp[i + 1][r] %= MOD;
      }
    }
  }

  cout << dp[N][5] << endl;
}

