      if (s[i - 1] == '?') {
        for (i64 x = 0; x <= 9; ++x) {
          i64 l = (j + x * k) % 13;
          dp[i][l] += dp[i - 1][j];
          dp[i][l] %= mod;
        }
      } else {
        i64 x = s[i - 1] - '0';
        i64 l = (j + x * k) % 13;
