int addMod(int a, int b, int mod) {
    return ((a % mod) + (b % mod)) % mod;
}

int multiplyMod(int a, int b) {
	return (1LL * (a % MOD) * (b % MOD)) % MOD;
}

int modPow(int a, int n) {
	int res = 1;
	while(n) {
		if(n & 1)
			res = multiplyMod(res, a);
		a = multiplyMod(a, a);
		n >>= 1;
	}
	return res;
}

