			ans = addMod(ans, res, int(1e9 + 7));
		}
	} else {
		int i = s[idx] - '0';
		int newRem = addMod(rem, multiplyMod(i, power[n - idx - 1]), 13);
		int res = dp(idx + 1, newRem);
		ans = addMod(ans, res, int(1e9 + 7));
	}
	return memo[idx][rem] = ans;
}

