					tempDp[target] %= mod;
				}
			}
		}
		else {
			int j = (int)(S[i] - '0');
			//それぞれのkに対して余りを足した場合の更新をかける
			for (int k = 0; k < N;++k) {
				int target = ((j*mul) % N + k) % N;
				tempDp[target] += dp[k];
				tempDp[target] %= mod;
			}
