    rep(i,5){
        for(int j = 1; j < 10; j++){
        memo[i+1][j] = 10*memo[i][j]%13;
        }
    }

    string s; cin >> s;

    int range = s.size(); //s.size()を何回も呼び出すのはダメ、先に記録しておく

    rep(i,range) rep(j,13) dp[i][j] = 0;

    if(s[range-1] == '?') rep(j,10) dp[range-1][j] = 1;
    else dp[range-1][(s[range-1]-'0')] = 1;

    for(int i = range-2; i >= 0; i--){ //10のi乗*s[i]%13について考える
        if(s[i] == '?'){
            rep(j,10){ //?に何を入れるかで全探索
                rep(k,13){ //各剰余について計算
                    dp[i][(memo[(range-1-i)%6][j]+k)%13] = (dp[i][(memo[(range-1-i)%6][j]+k)%13] + dp[i+1][k]) % MOD;
                }
            }
        }else{
            rep(j,13){ //普通に各剰余から次への推移を考える
                dp[i][(memo[(range-1-i)%6][(s[i]-'0')] + j) % 13] = (dp[i][(memo[(range-1-i)%6][(s[i]-'0')] + j) % 13] + dp[i+1][j]) % MOD;
            }
        }
    }

    cout << dp[0][5] % MOD << endl;
}

