          dp[idx + 1][k] = (dp[idx + 1][k] + dp[idx][i]) % MOD;
        }
      }
    } else {
      for (int i = 0; i < 13; ++i) {
        int j = (i + (n * base) % 13) % 13;
        dp[idx + 1][j] = (dp[idx + 1][j] + dp[idx][i]) % MOD;
      }
    }

    base = (base * 10) % 13;
  }

  cout << dp[N][5] << endl;

  return 0;
}

