Unionfind::Unionfind() {
    par.resize(MAX_N);
    siz.resize(MAX_N);
    rank.resize(MAX_N);
    rep(i, MAX_N) {
        par[i] = i;
        siz[i] = 1;
        rank[i] = 0;
    }
}
ll Unionfind::root(ll x) {
    if(par[x] == x) return x;
    else {
        return par[x] = root(par[x]);
    }
}
void Unionfind::merge(ll x, ll y) {
    x = root(x);
    y = root(y);
    if(x == y) return;
    if(rank[x] < rank[y]) {
        par[x] = y;
        siz[y] += siz[x];
    }
    else {
        par[y] = x;
        siz[x] += siz[y];
        if(rank[x] == rank[y]) rank[x]++;
    }
}
bool Unionfind::issame(ll x, ll y) {
    return root(x) == root(y);
}
ll Unionfind::size(ll x) {
    return siz[root(x)];
}

void z_algorithm(string s, vector<int> &a) {
    a.at(0) = s.size();
    int i = 1, j = 0;
    while(i < s.size()) {
        while((i+j < s.size()) && (s.at(j) == s.at(i+j))) j++;
        a.at(i) = j;
        if(j == 0) {
            i++;
            continue;
        }
        int k = 1;
        while ((i+k < s.size()) && (k+a.at(k) < j)) {
            a.at(i+k) = a.at(k);
            k++;
        }
        i += k;
        j -= k;
    }
}

