                dp[i][(ten[n - 1 - i] * a[i] + k) % 13] = (dp[i][(ten[n - 1 - i] * a[i] + k) % 13] + dp[i + 1][k]) % MOD;
        }
    }
    cout << dp[0][5] % MOD;
}   


