static const int MOD = 13;
static const int MODMOD = (1e+9) + 7;

template<class T>
T modpow(T base, T exp, T mod)
{
    base %= mod;
    T res = 1;

    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % mod;
        }

        base = (base * base) % mod;
        exp >>= 1;
    }

    return res;
}

