13で割って5余る・・・
ユークリッド

常識的に言って、
0~10000までの中で13で割って5余る数って言ったら
10000 / 13 の値がだいたい相当する

保留

i文字までで13で割って5余る数dp[i]
 */

int dp[100001][13];

int main() {
    string s;
    cin >> s;
    int n = s.size();
    int div = 1e9+7;

    dp[n][0] = 1;

    int r = 1;
    for (int i = n-1; i >= 0; i--) {
        if (s[i] == '?') {
            for (int j = 0; j < 13; j++) {
                for (int k = 0; k < 10; k++) {
                    int tmp = k * r;
                    dp[i][(j+tmp)%13] = (dp[i][(j+tmp)%13] + dp[i+1][j]) % div;
                }

            }
        } else {
            int k = ctoi(s[i]);
            for (int j = 0; j < 13; j++) {
                int tmp = k * r;
                    dp[i][(j+tmp)%13] = (dp[i][(j+tmp)%13] + dp[i+1][j]) % div;
            }
        }
        r = (r * 10) % 13;
    }
    cout << dp[0][5] % div << "\n";

}

