#define MOD (1000000007)

int modpow(int a) {
	int base = 1;
	for (int i = 0; i < a; ++i) {
		base *= 10;
		base %= 13;
	}
	return base;
}

int main() {
	string s;
	cin >> s;
	int len = s.length();
	vector<vector<int64_t>> pts(len+1,vector<int64_t>(13,0));
	pts[0][0] = 1;
	for (int i = 0; i < len; ++i) {
		int base = modpow(i);
		char c = s[len - 1 - i];
		if ('0' <= c && c <= '9') {
			int ci = (int)(c - '0');
			int shift = (base*ci) % 13;
			for(int j=0;j<13;++j){
				pts[i + 1][(j + shift) % 13] = pts[i][j];
			}
		}
		else {
			for (int ci = 0; ci < 10; ++ci) {
				int shift = (base*ci) % 13;
				for (int j = 0; j < 13; ++j) {
					int new_ind = (j + shift) % 13;
					pts[i + 1][new_ind] += pts[i][j];
					pts[i + 1][new_ind] %=MOD;
				}
			}
		}
	}
	cout << pts[len][5] << endl;
	return 0;
}

