const int MOD = 1000000007;

int main() {
    char s[100010];
    scanf("%s", s);

    int length = strlen(s);

    vector< vector<int> > dp;

    dp.resize(length);

    for (int i = 0; i < length; ++i) {
        dp[i].assign(13, 0);
    }

    for (int i = 0; i < length; ++i) {
        for (int j = 0; j < 13; ++j) {
            int r;

            if (i == 0) {
                r = (j == 0) ? 1 : 0;
            } else {
                r = dp[i-1][j];
            }

            if (s[i] == '?') {
                for (int k = 0; k < 10; ++k) {
                    int r2 = (j * 10 + k) % 13;
                    dp[i][r2] += r;
                    dp[i][r2] %= MOD;
                }
            } else {
                int r2 = (j * 10 + (int)s[i] - 48) % 13;
                dp[i][r2] += r;
                dp[i][r2] %= MOD;
            }
        }
    }

    printf("%d\n", dp[length - 1][5]);

    return 0;
}

