template<class F> dou mgrd_time(dou ok, dou ng, F f,int time = 1980) {
    bool han = true;
    if (ok < ng)
        while(1) {
            dou mid = (ok + ng) /2;
            if (f(mid))ok = mid, han = true; else ng = mid, han = false;
            deb(mid,han);
            if(timeup(time)){
                break;
            }
        }
    else
        while(1) {
            dou mid = (ok + ng) /2;
            if (f(mid))ok = mid, han = true; else ng = mid, han = false;
            deb(mid,han);
            if(timeup(time)){
                break;
            }
        }
    return ok;
}
