int get_rem(int pow) {
    if (pow == 0) {
        return 1;
    } else if (pow % 2 == 1) {
        return (10 * get_rem(pow - 1)) % 13;
    } else {
        int res = get_rem(pow / 2);
        return (res * res) % 13;
    }
}

int main() {
    scanf(" %s", s);
    n = strlen(s);

    if (s[n - 1] == '?') {
        for (int i = 0; i < 10; i++) {
            DP[n - 1][i] = 1;
        }
    } else {
        DP[n - 1][s[n - 1] - '0'] = 1;
    }

    for (int i = n - 2; i >= 0; i--) {
        if (s[i] == '?') {
            for (int k = 0; k < 10; k++) {
                for (int j = 0; j < 13; j++) {
                    DP[i][(k * get_rem(n - i - 1) + j) % 13] = (DP[i][(k * get_rem(n - i - 1) + j) % 13] + DP[i + 1][j]) % MOD;
                }
            }
        } else {
            for (int j = 0; j < 13; j++) {
                DP[i][((s[i] - '0') * get_rem(n - i - 1) + j) % 13] = (DP[i][((s[i] - '0') * get_rem(n - i - 1) + j) % 13] + DP[i + 1][j]) % MOD;
            }
        }
    }

    printf("%lld\n", DP[0][5]);

    return 0;
}

