class Solution {
public:
    const int MOD = 1e9 + 7;

    int Count(string S, int K, int R) {
        vector<int> ret(K, 0);
        int n = S.size();
        if (S[0] == '?') {
            for (int i = 0; i <= 9; i++) {
                ret[i % K]++;
            }
        }
        else {
            ret[(S[0] - '0') % K]++;
        }
        for (int i = 1; i < n; i++) {
            vector<int> newRet(K, 0);
            if (S[i] == '?') {
                for (int o = 0; o <= 9; o++) {
                    for (int j = 0; j < K; j++) {
                        newRet[(j * 10 + o) % K] += ret[j];
                        newRet[(j * 10 + o) % K] %= MOD;
                    }
                }
            }
            else {
                int offset = S[i] - '0';
                for (int j = 0; j < K; j++) {
                    newRet[(j * 10 + offset) % K] += ret[j];
                    newRet[(j * 10 + offset) % K] %= MOD;
                }
            }
            ret = newRet;
        }
        return ret[R];
    }
};


