	int s1l = s1.size();
	int s2l = s2.size();
	for (size_t i = 1; i <= s1l; i++)
	{
		for (size_t j = 1; j <= s2l; j++)
		{
			if (s1[i - 1] == s2[j - 1]) {
				dp[i][j] = dp[i - 1][j - 1] + 1;
			}
			else {
				dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);

			}
		}
	}
	return dp[s1l][s2l];
}
