        if(i==0){
            rep(j, 10){
                mt[i][j] = j;
            }
        }
        else if(i==1){
            rep(j, 10){
                mt[i][j] = (j*10)%13;
            }
        }
        else{
            rep(j, 10){
                ll t = j*100 % 13;
                mt[i][j] = (mt[i-2][1]*t) % 13;
            }
        }
