  //   std::cout << (int)sindex.index[i][j] << ",";
  // }
  // std::cout << std::endl;
  // }

  uint64_t row_sum = 0;

  {  // テーブル初期化
    int val = -1;
    if (s[0] != '?') val = s[0] - '0';
    if (val == -1) {
      for (size_t i = 0; i < 10; ++i) {
        dp[i % 13] = 1;
      }
      row_sum = 10;
    } else {
      dp[val % 13] = 1;
      row_sum = 1;
    }
    // % 13は不要だけど定義に帰るため
  }

  for (size_t i = 1, e = s.length(); i < e; ++i) {
    int val = -1;
    if (s[i] != '?') val = s[i] - '0';
    if (val == -1) {
      auto temp_sum = row_sum + 3 * MOD;
      for (size_t here = 0; here < 13; ++here) {
        uint64_t no_need = 0;
        for (size_t j = 0; j < 3; ++j) {
          no_need += dp[sindex.index[here][j]];
        }
        dp[13 + here] = temp_sum - no_need;
      }
    } else {
      for (size_t pre = 0; pre < 13; ++pre) {
        dp[13 + imod.mod[pre][val]] = dp[pre];
      }
    }

    //     for (int i = 0; i < 2; ++i) {
    //     for (int j = 0; j < 13; ++j) {
    //       std::cout << dp[i * 13 + j] << ",";
    //     }
    //     std::cout << std::endl;
    //   }
    //
    row_sum = 0;
    for (size_t i = 0; i < 13; ++i) {
      dp[i] = dp[13 + i] % MOD;
      row_sum += dp[13 + i];
      // dp[i] = dp[13 + i];
    }
    row_sum %= MOD;
  }

  std::cout << dp[5] % MOD << "\n";
  return 0;
}

