#define ll long long
const ll MOD=13;
ll mod_pow(ll x,ll y){//x^yを返す//計算量は0(log(y))
  ll t=x,r=1;
  while(y){
    if(y%2){r=r*t%MOD;}
    y>>=1;
    t=t*t%MOD;
  }
  return r;
}
