ll modPow(ll a, ll n, ll md){
  if (n == 0) return 1;
  if (n == 1) return a % md;
  if (n % 2 == 1) return (a * modPow(a, n-1, md)) % md;
  ll t = modPow(a, n/2, md);
  return (t * t) % md;
}

