int main() {
  char s[100001];
  cin >> s;
  int len = strlen(s);

  int dp[len + 1][13];
  fill(dp[0], dp[len + 1], 0);
  dp[0][0] = 1;
  int rems[6] = { 1, 10, 9, 12, 3, 4 };
  for(int i = 0; i < len; i++) {
    char c = s[i];
    int dig = len - 1 - i;
    int rem = rems[dig % 6];
    if(c >= '0' && c <= '9') {
      int num = (int) (c - '0');
      for(int j = 0; j < 13; j++) {
        int prevj = (j + 13 - (num * rem) % 13) % 13;
        dp[i + 1][j] += dp[i][prevj] % MOD;
      }
    }
    if(c == '?') {
      for(int num = 0; num <= 9; num++) {
        for(int j = 0; j < 13; j++) {
          int prevj = (j + 13 - (num * rem) % 13) % 13;
          dp[i + 1][j] += dp[i][prevj];
          dp[i + 1][j] = dp[i + 1][j] % MOD;
        }
      }
    }
  }
  cout << dp[len][5] << "\n";

  return 0;
}

