#include <bits/stdc++.h>
using namespace std;

const long long int mod = 10*10 *10*10*10*10*10*10*10 + 7;

int p(long long int i, long long int j, string s) {
  if (i == 0) {
    if (s.at(0) != '?') {
      long long int x = s.at(0) - '0';
      if (j == x) {
        return 1;
      }
      else {
        return 0;
      }
    }
    else if (s.at(0) =='?') {
        if (j < 10) {
          return 1;
        }
        else {
          return 0;
        }
    }
  }
  else {
    if (s.at(i) != '?') {
      for (int k = 0; k < 13; k++) {
        long long int y = s.at(i) - '0';
        int x = k * 10 + y;
        x = x % 13;
        if (j == x) {
          return p(i - 1, k, s) % mod;
        }
      }
    }
    else {
      for (int k = 0; k < 13; k++) {
        for (int l = 0; l < 9; l++) {
          int x = k  * 10 + l;
          x = x % 13;
          if (j == x) {
            return p(i - 1, k, s) % mod;
          }
        }
      }
    }
  }
}

