//計算結果メモ用
//周期性を利用して、10のi乗*s[j]%13を予め求めておく
//右から文字を見ていくので、右からn桁までの数を13で割った余りを計算したい時は、
//n-1桁までの余りに10**n*(右からn桁目の数)%13を足せばよいことになる
//10**6 % 13 == 1なので、周期6で上手く行く
//後は各10のべき乗に0~9を書けて13で割った余りを計算していくとよい
int memo[6][10];

ll dp[100001][13]; //右からi桁目まで見て、13で割った余りがjになるような数の個数は何通りか
int main(){

    //memoの計算
    rep(i,10) memo[0][i] = i;
    rep(i,6) memo[i][0] = 0;
    rep(i,5){
        for(int j = 1; j < 10; j++){
            memo[i+1][j] = 10*memo[i][j]%13;
        }
    }

    //sの入力
    string s; cin >> s;
    int n = s.size(); //s.size()を何回も呼び出すのはダメ、先に記録しておく

    //dpの計算
    if(s[n-1] == '?') rep(j,10) dp[n-1][j] = 1;
    else dp[n-1][(s[n-1]-'0')] = 1;
    for(int i = n-2; i >= 0; i--){ //10の(n-1-i)乗*s[i]%13をmemoから求める
        if(s[i] == '?'){
            rep(j,10){ //?に何を入れるかで全探索する
                rep(k,13){ //各剰余について計算
                //推移は右からなのでiの部分は1減らして、剰余の状態については各kにmemoを足せばよい
                    dp[i][(memo[(n-1-i)%6][j]+k)%13] += dp[i+1][k]; 
                }
            }
        }else{
            rep(j,13){ //各剰余から次への推移を考える
                dp[i][(memo[(n-1-i)%6][(s[i]-'0')] + j) % 13] += dp[i+1][j];
            }
        }
        rep(j,13) dp[i][j] %= MOD; //MODを取っておく
    }

    //答えの出力
    cout << dp[0][5] % MOD << endl;
}

