#include <bits/stdc++.h>
using namespace std;
#define THIRTEEN 13

int mod_13(int p) {
    if (p == 0) {
        return 1;
    } else {
        return (10 * mod_13(p - 1)) % THIRTEEN;
    }
}

int main() {
    long MOD = 1e9 + 7;
    ios::sync_with_stdio(false);
    cin.tie(0);

    string S;
    cin >> S;

    long count[S.size()][THIRTEEN];

    for (int n_s = 0; n_s < S.size(); n_s++) {
        for (int na = 0; na < THIRTEEN; na++) {
            count[n_s][na] = 0;
        }
    }

    if (S[S.size() - 1] == '?') {
        for (int j = 0; j < THIRTEEN; j++) {
            if (j < 10) {
                count[S.size() - 1][j] = 1;
            }
        }
    } else {
        count[S.size() - 1][S[S.size() - 1] - '0'] = 1;
    }

    for (int i = 2; i <= S.size(); i++) {
        int mod = mod_13(i - 1);
        if (S[S.size() - i] == '?') {
            for (int m = 0; m < 10; m++) {
                for (int j = 0; j < THIRTEEN; j++) {
                    int idx = ((j - (mod * m)) % THIRTEEN + THIRTEEN) % THIRTEEN;
                    count[S.size() - i][j] = (count[S.size() - i][j] + count[S.size() - i + 1][idx]) % MOD;
                }
            }
        } else {
            int m = S[S.size() - i] - '0';
            for (int j = 0; j < THIRTEEN; j++) {
                int idx = ((j - (mod * m)) % THIRTEEN + THIRTEEN) % THIRTEEN;
                count[S.size() - i][j] = (count[S.size() - i][j] + count[S.size() - i + 1][idx]) % MOD;
            }
        }
    }
    cout << count[0][5] << "\n";

    return 0;
}

