int main()
{
    std::string s;
    std::cin >> s;
    std::reverse(s.begin(), s.end());

    std::vector<long long> reminders(13, 0);
    reminders[0] = 1;

    int pos = 1;
    const int mod = 1000000007;

    for (auto c : s) {
        std::vector<long long> new_reminders(13, 0);
        if (c == '?') {
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < 13; j++) {
                    new_reminders[(i * pos + j) % 13] += reminders[j];
                    new_reminders[(i * pos + j) % 13] %= mod;
                }
            }
        } else {
            int i = c - '0';
            for (int j = 0; j < 13; j++) {
                new_reminders[(i * pos + j) % 13] += reminders[j];
                new_reminders[(i * pos + j) % 13] %= mod;
            }
        }

        pos *= 10;
        pos %= 13;
        reminders = new_reminders;
    }

    std::cout << reminders[5] << std::endl;
}

