int power(int a, int b) {
	int result = 1;
	while(b) {
		if(b % 2) result = (result * a) % 13;
		a = (a * a) % 13;
		b /= 2;
	}

	return result;
}

int divide13(int a, int b) {
	return a * power(b, 11) % 13;
}

void solve() {
	string s;
	cin >> s;

	int n = s.length();
	vvi dp(n + 1, vi(13, 0));
	dp[0][0] = 1;

	int pw = 1;
	for(int i = 0; i < n; i++) pw = (pw * 10) % 13;

	for(int i = 0; i < n; i++) {
		pw = divide13(pw, 10);
		if(s[i] == '?') {
			for(int j = 0; j < 13; j++) {
				for(int k = 0; k < 10; k++) {
					(dp[i + 1][(j + (k) * pw) % 13] += dp[i][j]) %= P;
				}
			}
		} else {
			for(int j = 0; j < 13; j++) {
				(dp[i + 1][(j + (s[i] - '0') * pw) % 13] += dp[i][j]) %= P;
			}
		}
	}

	cout << dp[n][5] << endl;
}

