constexpr int MOD = 1000000007;
constexpr int MAX_N = 100000;
const int R_LOOP[6] = {1, 10, 9, 12, 3, 4};
int num_digits[6];
long long all_num_possibles[MAX_N + 1][13];

long long ComputePossibles(long long prev_possibles, int prev_r, int target_r, int index) {
  if (index == 5) {
    long long possibles = 0;
    int r = (target_r + 13 - prev_r) % 13;
    for (int i = 0; i < 13; ++i) {
      if (R_LOOP[index] * i % 13 == r) {
        possibles = (possibles + prev_possibles * all_num_possibles[num_digits[index]][i]) % MOD;
      }
    }
    return possibles;
  }
  long long possibles = 0;
  for (int i = 0; i < 13; ++i) {
    long long cur_possibles = prev_possibles * all_num_possibles[num_digits[index]][i] % MOD;
    int cur_r = (prev_r + R_LOOP[index] * i) % 13;
    possibles = (possibles + ComputePossibles(cur_possibles, cur_r, target_r, index + 1)) % MOD;
  }
  return possibles;
}

int main() {
  std::string S;
  std::cin >> S;
  int fixed_r = 0;
  for (int i = 0; i < 6; ++i) {
    num_digits[i] = 0;
  }
  for (int i = 0; i < S.length(); ++i) {
    char ch = S[S.length() - i - 1];
    if (ch != '?') {
      int d = ch - '0';
      fixed_r = (fixed_r + d * R_LOOP[i % 6]) % 13;
    } else {
      num_digits[i % 6]++;
    }
  }
  int target_r = (18 - fixed_r) % 13;
  int max_num_digits = 0;
  for (int i = 0; i < 6; ++i) {
    max_num_digits = std::max(max_num_digits, num_digits[i]);
  }
  all_num_possibles[0][0] = 1;
  for (int j = 1; j < 13; ++j) {
    all_num_possibles[0][j] = 0;
  }
  for (int i = 1; i <= max_num_digits; ++i) {
    for (int j = 0; j < 13; ++j) {
      all_num_possibles[i][j] = 0;
    }
    for (int j = 0; j <= 9; ++j) {
      for (int k = 0; k < 13; ++k) {
        all_num_possibles[i][(j + k) % 13] = (all_num_possibles[i][(j + k) % 13] + all_num_possibles[i - 1][k]) % MOD;
      }
    }
  }
  std::cout << ComputePossibles(1, 0, target_r, 0) << std::endl;
  return 0;
}

