ll mod_pow(ll x, ll a,ll m)
{
  switch (a)
  {
  case 0:
    return 1;
    break;
  case 1:
    return x;
    break;  
  default:
    if(a%2==1){
      ll tmp = mod_pow(x,a-1,m);
      return (x*tmp)%m;
    } else {
      ll tmp = mod_pow(x,a/2,m);
      return tmp*tmp%m;
    }
    break;
  }
}

