int bigmod(int a, int p, int m) { 
    if (p == 0)  return (1 % m) ; 
    if (p & 1){ 
        int p1 = a % m ;
        int p2 = bigmod( a, p-1, m ) ; 
        return  (p1 * p2) % m ; 
    } 
    int p1 = bigmod( a, p/2, m ) ; 
    return  (p1 * p1) % m ; 
}

