string S;
int x[100010];
ll memo[100010][13];
ll solve (ll k, int a) {
	if (k == -1) {
		return (a == 5);
	}
	if (memo[k][a] != -1) return memo[k][a];
	ll res = 0;
	if (S[k] == '?') {
		for (int i = 0; i <= 9; i++) {
			res += solve(k-1, (a + x[k]*i) % 13);
		}
	}
	else {
		res = solve(k-1, (a + x[k]*(S[k]-'0'))%13);
	}
	res %= mod;
	return memo[k][a] = res;
}
