		x[i] = x[i + 1] * 10;
		x[i] %= 13;
	}
	for (int i = 0; i < 100010; i++) for (int j = 0; j < 13; j++) memo[i][j] = -1;
	cout << solve(S.length()-1, 0) << endl;
}

