vl UFpar(MAX_N);
vl UFrank(MAX_N);
void UFinit(ll n){
    REP(i, n){
        UFpar[i] = i;
        UFrank[i] = 0;
    }
}
ll UFfind(ll x){
    if(UFpar[x] == x){
        return x;
    }else{
        return UFpar[x] = UFfind(UFpar[x]);
    }
}
void UFunite(ll x, ll y){
    x = UFfind(x);
    y = UFfind(y);
    if(x == y){return;}
    if(UFrank[x] < UFrank[y]){
        UFpar[x] = y;
    }else{
        UFpar[y] = x;
        if(UFrank[x] == UFrank[y]){UFrank[x]++;}
    }
}
bool UFsame(ll x, ll y){
    return UFfind(x) == UFfind(y);
}

