/* 10のk乗を13で割った余りを求める */
int ModPower(int k){
    if (k == 0) return 1;
    int t = ModPower(k / 2); // 10のk/2乗の場合を計算
    if (k & 1){ // kが奇数の場合
        return t * t * 10 % 13;
    }
    return t * t % 13; // kが偶数の場合
}

signed main(){
    /* 入力の受け取り */
    string s;
    cin >> s;
    int n = s.length(); // sの桁数

    /*
        dp[i][j] : 上からi桁目までを見て、余りjをつくる作り方
    というDPを行う。
    初期条件
        dp[0][0] = 1
        それ以外は0
    遷移
        sのi+1桁目がk(=0,1,...,9)なら
            dp[i][j] -> dp[i+1][(j+k*ModPower(n-i-1))%13]
        に移る。
     */
    // dpテーブルの作成
    ll** dp = new ll*[n+1];
    for (int i = 0;i <= n;++i)
        dp[i] = new ll[13];
    // dpテーブルの初期化
    for (int i = 0;i <= n;++i)
        for (int j = 0;j < 13;++j)
            dp[i][j] = 0;
    dp[0][0] = 1;
    // dpテーブルの更新
    for (int i = 0;i < n;++i){
        for (int j = 0;j < 13;++j){
            if (s[i] != '?'){
                int k = s[i] - '0';
                int j_ = (j + k * ModPower(n-i-1)) % 13; 
                dp[i+1][j_] += dp[i][j];
                dp[i+1][j_] %= MOD;
            }
            else {
                for (int k = 0;k < 10;++k){
                    int j_ = (j + k * ModPower(n-i-1)) % 13; 
                    dp[i+1][j_] += dp[i][j];
                    dp[i+1][j_] %= MOD;
                }
            }
        }
    }
    // dpテーブルの出力
#ifdef TEST
    for (int i = 0;i <= n;i++){
        for (int j = 0;j < 13;j++)
            cout << dp[i][j] << " ";
        cout << endl;
    }
#endif
