      for (int k = 0; k < 13; ++k) {
        tmp[k] += memo[k - int(b) >= 0 ? k - int(b) : k - int(b) + 13];
        tmp[k] %= mod;
      }
    }
    for (int j = 0; j < 13; ++j) {
      memo[j] = tmp[j];
