int main() {
    string str;
    cin >> str;

    int n = str.size();

    long long dp[n][13];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 13; j++) dp[i][j] = 0;
    }

    // 初期値
    if (str[n - 1] != '?') {
        int num = str[n - 1] - '0';
        dp[0][num] = 1;
    } else {
        for (int i = 0; i < 10; i++) dp[0][i] = 1;
    }

    int power = 10;
    for (int i = n - 2; i >= 0; i--) {
        if (str[i] != '?') {
            // 一つ前余り数と今の余りの数を知りたい
            int num = ((str[i] - '0') * power) % 13; // X00000...0の余り
            // 一つ前っていうのは二時限目なので、0 - 12 まである。
            // 0 - 12 と X000....0 の余りを足す　→　i番目までの数字の余り
            for (int j = 0; j < 13; j++) dp[n - i - 1][(j + num) % 13] += dp[n - i - 2][j] % MOD;
        } else {
            for (int j = 0; j < 10; j++) {
                int num = (j * power) % 13;
                for (int k = 0; k < 13; k++) dp[n - i - 1][(k + num) % 13] += dp[n - i - 2][k] % MOD;
            }
        }
        power *= 10;
        power %= 13;
    }

    cout << dp[n - 1][5] << endl;
}

