ll fastPow(ll a, ll b, ll mod=0){
//    cout << a << " " << b << " " << mod << endl;
    if(a == 0 and b == 0){
        return -1;
    }
    if(a == 0){
        return 0;
    }
    if(b == 0){
        return 1;
    }
    ll tmp = fastPow(a,b/2,mod);
    if(mod != 0) {
        if (b % 2 == 0) {
//            return 1;
            return (tmp * tmp) % mod;
        } else {
//            return 0;
            return ((tmp*tmp) % mod * (a % mod)) % mod;
        }
    }else{
        if (b % 2 == 0) {
//            return 1;
            return (tmp*tmp);
        } else {
//            return 0;
            return tmp * tmp * a;
        }
    }
}

