  int n = s.length();
  int A[n];
  for (int i = 0; i < n; i++) {
    if (s[i] == '?') {
      A[i] = -1;
    } else {
      A[i] = int(s[i] - '0');
    }
  }

  dp[0][0] = 1;
  long long mul = 1;
  for (int i = 0; i < n; i++) {//digit from the top
    for (int j = 0; j < 10; j++) {//0~9 for each digit
      if (A[n-i-1] != -1 && A[n-i-1] != j) { continue; }
      for (int k = 0; k < 13; k++) {//residual when divided by 13
        /*
        Point 1: 桁ごとに分割できる
          ??2??5 = (100000 * ?) + (10000 * ?) + (1000 * 2) + (100 * ?) + (10 * ?) + (1 * 5)

        Point 2: 桁を13で割ったあまりに落とし込める
          100000%13 = 4
          10000%13 = 3
          1000%13 = 12
          100%13 = 9
          10%13 = 10
          1%13 = 1
          なので、
          ??2??5を13で割ったときのあまりを考える際は
          ??2??5 = (4 * ?) + (3 * ?) + (12 * 2) + (9 * ?) + (10 * ?) + (1 * 5)
          のようにさらに単純化できる
        */
        //1桁目から数えてi桁目時点であまりkになる場合の数は、i桁目のあまりkの数に
        dp[i+1][(j*mul + k)%13] += dp[i][k];
        dp[i+1][(j*mul + k)%13] %= mod;
      }
    }
    mul *= 10;
    mul %= 13;
  }
  cout << dp[n][5] << endl;
  return 0;
}

