　　　　　　　　　//前回何使ったかどう判別するかはまず3桁目を1としてこれを追加すると501となる、これは50*10+1でmod13の上では、
                //50*10+1 = 11*10+1mod13となる、なので前回のあまりがわかっている状態なら前回のあまり(mo)*10+今回mod13で今回のあまりも計算できる
                rep(next,10){
                   dp[i+1][(mo*10+next)%13] += dp[i][mo];             
                }
            }else{
                dp[i+1][(mo*10+(S[i]-'0'))%13] += dp[i][mo];
            }
        }
    }

    fin(dp[N][5]);
}

