Combination comb(100001, 13);

int dfs(int n, int m) {
  if ( n == N ) {
    if ( m == 5 ) return 1;
    else return 0;
  }
  if ( dp[n][m] >= 0 ) return dp[n][m];

  int p = comb.pow(10, N-n-1);
  int ret = 0;
  if ( s[n] != '?' ) {
    ret = dfs(n+1, (m+p*(s[n]-'0'))%13);    
  } else {
    for ( int i = 0; i < 10; i++ ) {
      ret += dfs(n+1, (m+p*i)%13);
      ret %= MOD;      
    }
  }

  ret %= MOD;      
  return dp[n][m] = ret;  
}

