/*
	Order Statistics Tree ( OST )

	find_by_order()
		takes an integer k and returns an iterator to the k'th largest element counting from zero
	order_of_key()
		takes an element, here an integer and returns the number of elements strictly smaller than input
*/


int const MOD = 1e9 + 7;

int const N = 1e5 + 10;
bool mark[N] ;

void sieve()
{
    for(int i = 2; i < N; i++){
        if(!mark[i]){
            for(int j = 2 * i ; j < N; j += i) 
                mark[j] = 1;
        }
    }
}
ll dp[N][20];
string s;
ll DP(int pos,int mod)
{
    if(pos == s.size()) return (mod == 5);
    ll &ret = dp[pos][mod] ;
    ret = 0;
    if(s[pos] != '?'){
        ret = DP(pos+1,(mod*10 + (s[pos] - '0'))%13 );
    }
    else{
        for(int i =0; i < 10; i++){
            ret += DP(pos+1,(mod*10 + i) % 13 ) ;
            ret %= MOD;
        }
    }
    return ret;
}
int main()
{
    ios::sync_with_stdio(0); cin.tie(0);

    cin >> s;

    memset(dp,-1,sizeof dp);
    cout << DP(0,0) << endl;
    return 0;

}

