using i64 = long long;

#define REP(i, stop) for (int i = 0, i##_len = stop; i < i##_len; ++i)

i64 dp[100010][13];
const i64 M = 1000000007;
signed main() {
	i64 k = 0;
	dp[0][0] = 1;
	while(true) {
		char c = getchar();
		if (c == '\n') {
			break;
		} else if (c == '?') {
			REP(r, 13) {
				i64 s = 0;
				REP(j, 10) {
					s += dp[k][(j - r + 13) * 9 % 13];
				}
				dp[k + 1][r] = s % M;
			}
		} else {
			i64 d = c - '0';
			REP(r, 13) {
				i64 s = dp[k][(d - r + 13) * 9 % 13];
				dp[k + 1][r] = s % M;
			}
		}
		k += 1;
	}
	printf("%d", dp[k][5]);
}

