                    int rem = (10*k + next)%13;
                    dp[i+1][rem] += dp[i][k];
                    dp[i+1][rem] = dp[i+1][rem]%mod;
                }
                if(s[i]!='?') break;
            }
        }
        cout<<dp[n][5];
