    FOR(i, 0, S.size())
        if (S[i] == '?')
            Marks[i % 6]++;
        else
            Offset[i % 6] = (Offset[i % 6] + S[i] - '0') % 13;

    const int MOD = 1000000007;
    VEC(VEC(int)) Dp(20011, VEC(int)(13, 0));
    Dp[0][0] = 1;
    FOR(i, 0, 20009) {
        FOR(rem, 0, 13) {
            FOR(d, 0, 10) {
                int& tmp = Dp[i + 1][(rem + d) % 13];
                tmp += Dp[i][rem];
                tmp %= MOD;
            }
        }
    }

    VEC(int) Coeffs {1, 10, 9, 12, 3, 4};
    VEC(int) Table[13][13];
    FOR(a, 0, 13)
        FOR(b, 0, 13)
            Table[a * b % 13][a].push_back(b);

    int ret = 0;

    FOR(r0, 0, 13)
        FOR(r1, 0, 13)
            FOR(r2, 0, 13)
                FOR(r3, 0, 13)
                    FOR(r4, 0, 13)
                        FOR(r5, 0, 13)
                            {
                                VEC(int) R{r0, r1, r2, r3, r4, r5};
