using namespace std;

typedef long long ll;

const ll MOD = 1e9 + 7;

string s;
ll dp[100010][10][13];

ll solve(int pos, int val, int tmp) {
    if (pos >= s.size()) {
        return (tmp % 13 == 5);
    }
    if (dp[pos][val][tmp] != -1) return dp[pos][val][tmp] % MOD;
    ll ret = 0LL;
    if (s[pos] == '?') {
        for (int i = 0; i <= 9; ++i) {
            int k = tmp * 10 + i;
            int x = k / 13;
            int ntmp = k - x * 13;
            ret = (ret % MOD + solve(pos + 1, i, ntmp) % MOD) % MOD;
        }
    }
    else {
        int k = s[pos] - '0';
        int x = (k + tmp * 10) / 13;
        int ntmp = (k + tmp * 10) - x * 13;
        ret = (ret % MOD + solve(pos + 1, k, ntmp) % MOD) % MOD;
    }
    return dp[pos][val][tmp] = ret;
}

int main() {
    cin >> s;
    memset(dp, -1LL, sizeof(dp));
    cout << solve(0, 0, 0) << endl;
    return 0;
}

