ll pow_mod(ll x, ll y, ll mod) {
  if (y == 0) return 1;
  if (y % 2) {
    return (x * pow_mod(x, y - 1, mod)) % mod;
  } else {
    return pow_mod(x * x, y / 2, mod);
  }
}

