int main(){
    string S;
    cin >> S;
    reverse(S.begin(), S.end());
    int N = S.size();

    static int64_t dp[100001][13];
    dp[0][0] = 1;
    int base = 1;
    for(int i=0; i<N; i++){
        for(int j=0; j<13; j++){
            for(int d=0; d<=9; d++){
                if(S[i] == '?' || S[i] - '0' == d){
                    add(dp[i+1][(j+base*d)%13], dp[i][j]);
                }
            }
        }
        base = base * 10 % 13;
    }
    cout << dp[N][5] << endl;
    return 0;
}

