static const  unsigned long long MOD = 1000000007LL;
string S;

int main() {
	unsigned long long dp[13] = { 0 }, dp_next[13];

	dp[0] = 1;
	cin >> S;

	for (const char& s : S) {
		for (int i = 0; i < 13; i++) dp_next[i] = 0;

		if (s == '?') {
			for (int i = 0; i < 10; i++) {
				for (int j = 0; j < 13; j++) {
					dp_next[((j * 10 + i) % 13)] += dp[j];
				}
			}
		}
		else {
			for (int i = 0; i < 13; i++) {
				dp_next[(i * 10 + s-'0') % 13] += dp[i];
			}
		}

		for (int i = 0; i < 13; i++) {
			dp[i] = dp_next[i] % MOD;
		}
	}

	cout << dp[5] << endl;

	return 0;
}

