int main(int argc, const char * argv[]) {
  string S; cin >> S;
  int N = (int)S.size();
  vector<vector<ll>> dp(N+1, vector<ll>(13, 0));
  vector<ll> beki(N+1, 0);
  beki[1] = 1;
  for(int i=2; i<N+1; i++){
    beki[i] = (beki[i-1]*10) % 13;
  }

  dp[0][0] = 1;
  int nr;
  for(int k=1; k<=N; k++){
    for(int r=0; r<13; r++){
      if (S[k-1] == '?'){
        for(int i=0; i<10; i++){
          nr = (r + i*beki[k]) % 13;
          dp[k][nr] = (dp[k][nr] + dp[k-1][r]) % MOD;
        }
      } else {
          int i = (int)S[N-k] - (int)'0';
          nr = (r + i*beki[k]) % 13;
          dp[k][nr] = (dp[k][nr] + dp[k-1][r]) % MOD;
      }
    }
  }

  cout << dp[N][5] << endl;

  return 0;
}

