inline ll gcd(ll a, ll b){
    a = abs(a), b = abs(b);
    while (b)
        a = a % b, swap (a, b);
    return a;
}
inline ll power(ll a, ll p){
    ll res = 1, x = a;
    while (p){
        if (p & 1) res = (res * x);
        x = (x * x), p >>= 1;
    }
    return res;
}
inline ll mul_mod(ll a, ll p, ll m){
    ll res = 0, x = a%m;
    while (p){
        if (p & 1) res = (res + x) % m;
        x = (x << 1) % m, p >>= 1;
    }
    return res;
}
inline ll big_mod(ll a, ll p, ll m){
    ll res = 1 % m, x = a % m;
    while (p){
        if (p & 1) res = (res * x) % m;
        x = (x * x) % m, p >>= 1;
    }
    return res;
}
ll ext_gcd(ll A, ll B, ll *X, ll *Y ){
    ll x2, y2, x1, y1, x, y, r2, r1, q, r;
    x2 = 1, y2 = 0;
    x1 = 0, y1 = 1;
    for (r2 = A, r1 = B; r1 != 0; r2 = r1, r1 = r, x2 = x1, y2 = y1, x1 = x, y1 = y ) {
        q = r2 / r1, r = r2 % r1;
        x = x2 - (q * x1), y = y2 - (q * y1);
    }
    *X = x2; *Y = y2;
    return r2;
}
inline ll mod_inv(ll a, ll m) {
    ll x, y;
    ext_gcd(a, m, &x, &y);
    x %= m;
    if ( x < 0 ) x += m;
    return x;
}

const int INF = 1e9+9;

const int mod = 1e9+7;
const int nax = 1e5+5;
ll dp[nax][20];
string s;
int len;

ll solve(int idx, int rem)
{
    if (idx >= len){
        if (rem % 13 == 5){
            return 1;
        }
        return 0;
    }
    if (dp[idx][rem] != -1){
        return dp[idx][rem];
    }
    ll ret = 0;
    if (s[idx] == '?'){
        for (int num = 0; num <= 9; num++){
            ret += solve(idx+1, (rem*10 + num) % 13);
            ret %= mod;
        }
    }
    else{
        ret = solve(idx+1, (rem*10 + s[idx] - '0') % 13);
    }
    ret %= mod;
    return dp[idx][rem] = ret;
}

