template<typename T>
T power(T x, T p, T prime = 0)
{
  if (prime == 0) {
    if (p == 0) return 1;
    if (p == 1) return x;

    T tmp = power(x, p/2);
    if (p%2 == 0) return tmp * tmp;
    else return x * tmp * tmp;
  } else {
    if (p == 0) return 1;
    if (p == 1) return x % prime;

    T tmp = power(x, p/2) % prime;
    if (p%2 == 0) return (tmp * tmp) % prime;
    else return x * (tmp * tmp % prime) % prime;
  }
}

