    vec<Zp<MOD>> res(13, Zp<MOD>(0));
    for(int i=0; i < 13; i++){
        for(int j=0; j < 13; j++){
            res.at((i + j) % 13) += a.at(i)*b.at(j);
        }
    }

    return res;
}

void solve(std::string S){
    vec<bool> qs;
    vec<int> digits;
    Zp<13> S1(0);
    Zp<13> pow10(1);
    for(int i=S.size() - 1; i >= 0; i--){
        char c = S.at(i);
        if(c == '?'){
            digits.push_back(0);
            qs.push_back(true);
        }else if('0' <= c && c <= '9'){
            digits.push_back(S.at(i) - '0');
            qs.push_back(false);
        }
        S1 = S1 + Zp<13>(digits.back())*pow10;
        pow10 = pow10 * Zp<13>(10);
    }

    // calc 
    vec<Zp<MOD>> counter(13, Zp<MOD>(0));
    counter.at(0) = Zp<MOD>(1);
    pow10 = Zp<13>(1);
    for(int i=0; i < digits.size(); i++){
        if(qs.at(i)){
            vec<Zp<MOD>> xs(13, Zp<MOD>(0));
            for(int n=0; n < 10; n++){
                xs.at((pow10 * Zp<13>(n)).raw()) += Zp<MOD>(1);
            }
            counter = mult(counter, xs);
        }
        pow10 = pow10 * Zp<13>(10);
    }

    Zp<13> rhs = Zp<13>(5) - S1;

    cout << counter.at(rhs.raw()).raw() << endl;


}

