constexpr ll MOD = (ll)1e9 + 7;

ll MODpow(ll n, ll m, ll mod) {
    ll result = 1;
    while (m) {
        if (m % 2 == 1) {
            result *= n;
            result %= mod;
        }

        m /= 2;
        n *= n;
        n %= mod;
    }

    return result;
}

