int const MOD = 1e9 + 7;

int const N = 1e5 + 10;
bool mark[N] ;

void sieve()
{
    for(int i = 2; i < N; i++){
        if(!mark[i]){
            for(int j = 2 * i ; j < N; j += i) 
                mark[j] = 1;
        }
    }
}
ll dp[N][20];
string s;
ll DP(int pos,int mod)
{
    if(pos == s.size()) return (mod == 5);
    ll &ret = dp[pos][mod] ;
    if(ret != -1) return ret;
    ret = 0;

    if(s[pos] != '?'){
        ret = DP(pos+1,(mod*10 + (s[pos] - '0'))%13 );
    }
    else{
        for(int i =0; i < 10; i++){
            ret += DP(pos+1,(mod*10 + i) % 13 ) ;
            ret %= MOD;
        }
    }
    return ret;
}
