ll modExpo(ll x, ll y){
	ll result = 1;
	x %= mod;
	while(y > 0){
		if(y & 1){
			result = ((result % mod) * (x % mod))%mod;
		}
		y >>= 1;
		x = ((x % mod) * (x % mod))%mod;
	}
	return result % mod;
}

ll rec(ll pos, ll rem) {
	if(pos == n) {
		return (rem == 5);
	}
