using namespace std;

uint64_t dp[100000][13];
uint64_t rem_count_table[13][13];  // rem_count_table[N][k] = count(x % 13 == k)
                                   // x: [10N, 10(N+1))

void gen_rem_count_table() {
  for (int N = 0; N < 13; N++) {
    for (int x = 10 * N; x < 10 * (N + 1); x++) {
      rem_count_table[N][x % 13]++;
    }
  }
}

uint64_t calc(string &s, int result_rem) {
  for (int i = 0; i < s.size(); i++) {
    if (i == 0) {
      if (s[i] == '?') {
        for (int k = 0; k < 13; k++) {
          dp[i][k] = k < 10 ? 1 : 0;
        }
      } else {
        for (int k = 0; k < 13; k++) {
          dp[i][k] = (k == (s[i] - '0')) ? 1 : 0;
        }
      }
      continue;
    }
    if (s[i] == '?') {
      for (int k = 0; k < 13; k++) {
        for(int t = 0; t < 13; t++){
          dp[i][k] += rem_count_table[t][k] * dp[i-1][t];
          dp[i][k] %= 1000000007;
        }
      }
    } else {
      for(int t = 0; t < 13; t++){
        int k = (t * 10 + (s[i] - '0')) % 13;
        dp[i][k] += rem_count_table[t][k] * dp[i-1][t];
        dp[i][k] %= 1000000007;
      }
    }
  }
  return dp[s.size() - 1][result_rem];
}

int main(int argc, char *argv[]) {
  string s;
  std::cin >> s;
  gen_rem_count_table();
  cout << calc(s, 5) << endl;

  return 0;
}

