ll recur(ll a[],ll cnt[],ll tmp[],ll magic[],ll index){
    ll i,j,ans=0;

    if(index==6){
        j=0;
        for(i=0;i<6;i++)
            j=(j+(tmp[i]*magic[i])%13)%13;

        if(j==5){
            ll b[6],ans=1;
            for(i=0;i<6;i++){
                b[i]=(13-a[i]+tmp[i])%13;
                if(cnt[i]==0 && b[i]!=0)
                    return 0;
            }

            for(i=0;i<6;i++){
                if(cnt[i]){
                    j=(powa(10,cnt[i])+mod-powa2(10,cnt[i]))%mod;
                    if((powa2(10,cnt[i])+12)%13>=b[i])
                        j=(j*153846155LL+1)%mod;
                    else
                        j=(j*153846155LL)%mod;
                    ans=(ans*j)%mod;    
                }
            }
            return ans;
        }
        return 0;
    }

    for(i=0;i<13;i++){
        j=tmp[index];
        tmp[index]=i;
        ans=(ans+recur(a,cnt,tmp,magic,index+1))%mod;
        tmp[index]=j;
