ll gcd(ll a, ll b) {
	if (a < b)	swap(a, b);
	ll r = a % b;
	while (r != 0) {
		a = b;
		b = r;
		r = a % b;
	}
	return b;

}

// 素因数分解 
// cnt_pf[i]にi+1で割った回数を格納している
// cnt_pf[0]に入力が素数だった場合にその素数が入る
vector<ll> prime_factorization(ll n) {
	vector<ll> cnt_pf(ceil(sqrt(n)), 0);
	FOR(i, 1, SZ(cnt_pf)) {
		while (n % (i + 1) == 0) {
			cnt_pf[i]++;
			n /= (i + 1);
		}
		if (n == 1)	break;
	}
	if (n != 1) {
		cnt_pf[0] = n;
	}
	return cnt_pf;
}

