int main(){
    string S;
    cin >> S;
    int n = S.length();

    int mul = 1;
    vector<int> m(n);       // (10のべき乗)%13
    for(int i = n-1; i >= 0; --i){
        m[i] = mul;
        mul = (mul * 10) % 13;
    }

    // dpテーブルの初期化
    dp[0][0] = 1;

    for(int i = 0; i < n; ++i){
        if(S[i] != '?'){        // 数が確定しているとき
            int temp = S[i] - '0';  // 今見ている桁の数字
            for(int j = 0; j <= 12; ++j){
                dp[i + 1][(j + m[i] * temp) % 13] += dp[i][j];          // 剰余が(j + m[i]*temp) % 13になる
            }
        }
        else{               // 数が確定していないとき
            for(int N = 0; N <= 9; ++N){        // 0-9を代入して剰余を計算
                for(int j = 0; j <= 12; ++j){
                    int id = (j + m[i] * N) % 13;       // 更新するindex
                    dp[i + 1][id] = (dp[i + 1][id] + dp[i][j]) % mod;
                }
            }
        }
    }

    cout << dp[n][5] << endl;
}

