// x^n
int powmod(int x, int n) {
    constexpr int mod = 13;
    int ret = 1LL;
    int t = x % mod;
    while (n > 0) {
        if (n & 1LL) {
            ret *= t;
            ret %= mod;
        }
        t *= t;
        t %= mod;
        n >>= 1;
    }
    return ret;
}

