#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007;

#define MAX 100010

//Fast Exponentiation
ll fexp(ll base, ll exp, ll mod) {
    ll result = 1;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        exp >>= 1;
        base = (base * base) % mod;
    }
    return result;
}

int dp[MAX][13], n;
string s;

int solve(int idx, int rem) {
    if (idx >= n) {
        if (rem != 0) return 0;
        return 1;
    }

    if (dp[idx][rem] != -1) return dp[idx][rem];

    if (s[idx] != '?') {
        int r = s[idx] - '0';
        int x = fexp(10, n - 1 - idx, 13);
        int res = (rem - x * r) % 13;
        while (res < 0) res += 13;

        dp[idx][rem] = solve(idx + 1, res);
        return dp[idx][rem];
    }

    int ans = 0;
    for (int r = 0; r < 10; r++) {
        int x = fexp(10, n - 1 - idx, 13);
        int res = (rem - x * r) % 13;
        while (res < 0) res += 13;
        ans += solve(idx + 1, res);
        if (ans >= MOD) ans -= MOD;
    }

    dp[idx][rem] = ans;
    return ans;
}

int main() {
    cin >> s;
    n = s.length();

    memset(dp, -1, sizeof(dp));

    cout << solve(0, 5);

    return 0;
}

