            for (int j = 0; j < 10; j++) for (int k = 0; k < 13; k++) {
                dp[i][(k * 10 % 13 + j) % 13] = (dp[i][(k * 10 % 13 + j) % 13] + dp[i - 1][k]) % mod;
            }
        } else {
            int d = s[i - 1] - '0';
            for (int j = 0; j < 13; j++) {
                dp[i][(j * 10 % 13 + d) % 13] = (dp[i][(j * 10 % 13 + d) % 13] + dp[i - 1][j]) % mod;
            }
        }
    }

    std::cout << dp[n][5] << std::endl;

    return 0;
}

