const ll M = 1e9 + 7;

ll solve(ll pos, ll mod){
  if(pos==N){
    if(mod == 5) return 1;
    else return 0;
  }
  if(dp[pos][mod]!=-1) return dp[pos][mod];
  ll ans = 0;
  if(s[pos]!='?') {
    ans += solve(pos+1, (mod + ((s[pos]-'0') * dig[pos])) % 13);
  }
  else{
    FORN(i,0,10){
      ll newmod = (mod + (i * dig[pos])) % 13;
      ans += solve(pos+1, newmod);
      ans %= M;
    }
  }
  ans %= M;
  dp[pos][mod] = ans;
  return ans;
}

