int get_nth_digit(int x, int n) {
    auto x_str = to_string(x);
    int digits = x_str.size();

    if(digits < n+1)
        return 0;
    else 
        return int(to_string(x)[digits-1-n] - '0');
}

ll combi(ll n, ll k) {
    map<string, ll> memo;
    // cout << "n: " << n << " k: " << k << endl;
    if (n == k || k == 0)
        return 1;
    else {
        string key = to_string(n) + to_string(k);
        if (memo.count(key) != 0) {
            return memo[key];
        } else {
            ll out = combi(n - 1, k - 1) + combi(n - 1, k);
            memo[key] = out;
            return out;
        }
    }
}

ll get_num_partition(ll n, ll k) {
    if(n==0 || k==0 || k==1) return 1;
    ll res = 0;
    for(int j=1; j<=min(n, k); j++) {
        // cout << "n: " << n << " k: " << k << " j: " << j << endl;
        res += combi(k, j) * get_num_partition(n-j, j);
    }
    return  res;
}

