int QP(int a, int b)
{
    int ans = 1;
    do
    {
        if (b & 1)
            ans = 1ll * ans * a % MOD;
        a = 1ll * a * a % MOD;
    } while (b >>= 1);
    return ans;
}
int QP(int a, int b, int MOD)
{
    int ans = 1;
    do
    {
        if (b & 1)
            ans = 1ll * ans * a % MOD;
        a = 1ll * a * a % MOD;
    } while (b >>= 1);
    return ans;
