// char-position unitvalue unitvalue%13
// 0 1 1
// 1 10 10
// 2 100 9
// 3 1000 12
// 4 10000 3
// 5 100000 4
// 6 1000000 1
// 7 10000000 10
// ...
static int const mods[] = {1, 10, 9, 12, 3, 4};
static int const mods_cycle = sizeof(mods) / sizeof(mods[0]);
static int memo[100000][13];
static string S;

static int const target_mod = 5;

// for recursive call
static int solve(int offset, int mod);

static int
calc(int offset, int mod)
{
  if (S[offset] != '?')
  {
    return solve(offset + 1, mod);
  }
  int count = 0;
  int delta = mods[(S.size() - offset - 1) % mods_cycle];
  for (int i = 0; i < 10; i++)
  {
    count = add_fix(count, solve(offset + 1, (mod + delta * i) % 13));
  }
  return count;
}

static int
solve(int offset, int mod)
{
  if (S.size() <= offset)
  {
    return mod == target_mod ? 1 : 0;
  }
  int value = memo[offset][mod];
  if (value == 0)
  {
    memo[offset][mod] = value = calc(offset, mod) + 1;
  }
  return value - 1;
}

