// powd returns x^y mod m in O(log y).
long long powd(long long x, long long y, const long long md=1000000007){
  long long res=1;
  while(y){
    if(y&1) res=res*x%md;
    x=x*x%md;
    y>>=1;
  }
  return res;
}

