typedef long long ll;

string s;
ll dp[111111][13], cycle[6] = {1, 10, 9, 12, 3, 4};
/* Find about "cycle" in "https://en.wikipedia.org/wiki/Divisibility_rule#Divisibility_by_13" */

int main(void)
{
	ll i, j, k;

	cin >> s;

	dp[s.size()][0] = 1;
	for (i = s.size() - 1; i >= 0; i--)
		if (s[i] != '?')
		{
			ll rmd = (s[i] - '0') * cycle[(s.size() - 1 - i) % 6] % 13;

			for (k = 0; k < 13; k++)
			{
				ll now = (k + rmd) % 13;
				dp[i][now] = (dp[i][now] + dp[i + 1][k]) % MOD;
			}
		}
		else
		{
			for (j = 0; j < 10; j++)
			{
				ll rmd = j * cycle[(s.size() - 1 - i) % 6] % 13;

				for (k = 0; k < 13; k++)
				{
					ll now = (k + rmd) % 13;
					dp[i][now] = (dp[i][now] + dp[i + 1][k]) % MOD;
				}
			}
		}

	cout << dp[0][5];
	return 0;
}

