ll solve(const string& s)
{
    auto N = s.size();

    dp[0][0] = 1;

    for (size_t i = 0; i < N; ++i)
    {
        int a = 0, b = 9;

        if (s[i] != '?')
        {
            auto d = s[i] - '0';

