#include <bits/stdc++.h>
using namespace std;

typedef long long int ll;

int sizeS;
string s;
ll pot[100010], memo[100010][15];

ll mod(ll a, ll b) {
	return ((a % b) + b) % b;
}

ll powMod(ll a, ll n, ll m) {
	ll result = 1;
	while (n) {
		if (n & 1)
			result = mod(result * a, m);
		a = mod(a * a, m);
		n >>= 1;
	}
	return result;
}

ll dp(int pos, int sum) {
	if (pos == sizeS and sum % 13 == 5) return 1;
	if (pos == sizeS and sum % 13 != 5) return 0;
	if (memo[pos][sum] != -1) return memo[pos][sum]; 
	ll ans = 0;
	if (s[pos] != '?') {
		int d = s[pos] - '0';
		d = mod(d * pot[pos], 13);
		ll newSum = mod(sum + d, 13);
		ans = mod(ans + dp(pos + 1, newSum), 1e9 + 7);
	}
	else {
		for (int i = 0; i < 10; i++) {
			ll newSum = sum;
			ll d = mod(i * pot[pos], 13);
			newSum = mod(newSum + d, 13);
			ans = mod(ans + dp(pos + 1, newSum), 1e9 + 7);
		}
	}
	memo[pos][sum] = ans;
	return ans; 
}

int main() {

	cin >> s;
	reverse(s.begin(), s.end());
	sizeS = s.size();
	for (int i = 0; i < sizeS; i++) {
		pot[i] = powMod(10, i, 13);
	}
	memset(memo, -1, sizeof(memo));
	cout << dp(0, 0) << "\n";
	return 0;
}

