//Digts Parade
int main(){
    string s;cin>>s;
    long long dp[100000][13];
    for(int i=0;i<13;i++)dp[0][i]=0;

    for(int i=0;i<s.size();i++){
        for(int j=0;j<13;j++)dp[i+1][j]=0;
        char r=s[i];
        //dp[i][j]=k <=> i文字目までの数値を割ったときの余りがjである個数
        if(r=='?'){//?には0~9の数字を入れることができる
            if(i==0){
                for(int j=0;j<=9;j++){
                    dp[i+1][j]=1;
                }
                continue;
            }

            for(int k=0;k<=9;k++){
                for(int j=0;j<13;j++){
                    int ren=j*10+k;
                    ren%=13;
                    dp[i+1][ren]+=dp[i][j];
                    dp[i+1][ren]%=mod;
                }
            }
            continue;
        }

        int now=(int)(r-'0');
        if(i==0)dp[i][now]=1;
        for(int j=0;j<13;j++){
            int ren=j*10+now;
            ren%=13;
            dp[i+1][ren]+=dp[i][j];
            dp[i+1][ren]%=mod;
        }

    }
    cout<<dp[s.size()][5]<<endl;
}

