#include <bits/stdc++.h>

using namespace std;

const long mod = 1e9 + 7;

signed main()
{
    string s;
    cin >> s;
    reverse(s.begin(), s.end());

    int n = s.size();
    // dp[i][j]: 下からi桁目(10^iの桁の値)までを考慮した時の, 13で割ったあまりがjになるパターンの数
    vector<vector<long>> dp(n + 1, vector<long>(13, 0));
    dp[0][0] = 1;
    // 10のi乗を13で割った値
    long p_mod = 1;
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < 13; ++j){
            for(int k = 0; k < 10; ++k){
                // ?でない, 数字が合ってない場合には処理しない
                if(s[i] != '?' && s[i] != '0' + k)
                    continue;
                // (今までのjの値 + k * のi乗) % 13 に遷移する
                int add_mod = p_mod * k;
                dp[i + 1][(j + add_mod) % 13] += dp[i][j];
                dp[i + 1][(j + add_mod) % 13] %= mod;
            }
        }
        p_mod = (p_mod * 10) % 13;
    }
    cout << dp[n][5] << endl;
    return 0;
}

