void solve(int N, int remain) {
  int cnt=0;
  rep(i, N) {
    if(!q[i]) continue;
    if(cnt==0) {
      rep(j, 10) {
        dp[0][(mod13_pad(N-i-1)*j)%13] += 1;
      }
    } else {
      rep(j, 10) {
        rep(k, 13) {
          dp[cnt][(k+(mod13_pad(N-i-1)*j))%13] += dp[cnt-1][k];
        }
      }
    }
    cnt++;
  }
  cout << dp[cnt-1][remain].x << endl;
}

