ll mod9(ll x){
	x %= MOD;
	if(x < 0) x += MOD;
	return x;
}

ll mod13(ll x){
	x %= 13;
	if(x < 0) x += 13;
	return x;
}


ll pow(ll x,ll n){
	if(n==0) return 1;
	ll t = pow(x,n/2);
	t=mod13(t*t);
	if(n%2==1)t=mod13(t*x);
	return t;
}

