using namespace std;

int main() {
    string S;
    cin >> S;
    while (S.size() % 3 != 0) {
        S = "0" + S;
    }
    reverse(S.begin(), S.end());
    long long mod[13] = {1};
    int sgn = 1;
    while (!S.empty()) {
        string s = S.substr(0, 3);
        reverse(s.begin(), s.end());
        S = S.substr(3);
        bool q[3];
        for (int i = 0; i < 3; ++i) {
            if (s[i] == '?') q[i] = true;
            else q[i] = false;
        }
        long long a[3] = {};
        long long add[13] = {};
        for (int i = 0; i < 10; ++i) {
            if (q[0]) a[0] = i;
            else a[0] = s[0] - '0';
            for (int j = 0; j < 10; ++j) {
                if (q[1]) a[1] = j;
                else a[1] = s[1] - '0';
                for (int k = 0; k < 10; ++k) {
                    if (q[2]) a[2] = k;
                    else a[2] = s[2] - '0';
                    add[(100 * a[0] + 10 * a[1] + a[2]) % 13]++;
                    add[(100 * a[0] + 10 * a[1] + a[2]) % 13] %= MOD;
                    if (!q[2]) break;
                }
                if (!q[1]) break;
            }
            if (!q[0]) break;
        }
        long long newmod[13] = {};
        for (int i = 0; i < 13; ++i) {
            for (int j = 0; j < 13; ++j) {
                if (sgn > 0) {
                    newmod[(i + j) % 13] += mod[i] * add[j];
                    newmod[(i + j) % 13] %= MOD;
                } else {
                    int m = ((i - j) % 13 + 13) % 13;
                    newmod[m] += mod[i] * add[j];
                    newmod[m] %= MOD;
                }
            }
        }
        for (int i = 0; i < 13; ++i) {
            mod[i] = newmod[i];
        }
        sgn *= -1;
    }
    cout << mod[5] << endl;

    return 0;
}

