vector<ll> temp;
void change(vector<ll>& dp, ll num)
{
  temp = dp;
  for (ll i = 0; i < 13; ++i)
  {
    ll inum = i + num;
    inum %= 13;
    if (inum < 0)
    {
      inum += 13;
    }
    dp.at(inum) = temp.at(i);
  }
}

int main()
{
  ll mod = 1000000007;
  string S;
  cin >> S;
  ll N = S.size();
  vector<ll> dp(13, 0);
  dp.at(0) = 1;
  for (ll i = 0; i < N; ++i)
  {
    if (S[N - i - 1] != '?')
    {
      ll num = (S[N - i - 1] - '0') * pow(10, i % 3);
      // cout << num << endl;
      if ((i / 3) % 2 == 0)
      {
        change(dp, num);
      }
      else
      {
        change(dp, -num);
      }
    }
    else
    {
      temp = dp;
      ll power = pow(10, i % 3);
      if ((i / 3) % 2 == 0)
      {
        for (ll j = 1; j < 10; ++j)
        {
          for (ll k = 0; k < 13; ++k)
          {
            dp.at((k + j * power) % 13) += temp.at(k);
            dp.at((k + j * power) % 13) %= mod;
          }
        }
      }
      else
      {
        for (ll j = 1; j < 10; ++j)
        {
          for (ll k = 0; k < 13; ++k)
          {
            ll kj = (k - j * power) % 13;
            if (kj < 0)
            {
              kj += 13;
            }
            dp.at(kj) += temp.at(k);
            dp.at(kj) %= mod;
          }
        }
      }
    }
  }
