using namespace std;

class Solution {
public:
    int solve(string& s) {
        int n = s.length();
        const long long MOD = 1e9 + 7;

        const int N = 13;
        vector<long long> dp(N, 0);
        vector<long long> ndp(dp);
        dp[0] = 1;

        for (int i = 0; i < n; ++i) {
            fill(ndp.begin(), ndp.end(), 0);
            for (int j = 0; j < N; ++j) {
                int l = 0;
                int r = 9;
                if (s[i] != '?') {
                    l = r = s[i] - '0';
                }

                for (int k = l; k <= r; ++k) {
                    int nj = (j * 10 + k) % N;
                    (ndp[nj] += dp[j]) %= MOD;
                }
            }
            swap(ndp, dp);
        }
        return dp[5];
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    string s;
    cin >> s;
    Solution sol;
    cout << sol.solve(s) << "\n";

    return 0;
}

