    return c - '0';
}

int main() {
    string inp;
    cin >> inp;
    int len = inp.length();
    dp[len][0] = 1;

    for(int i = len - 1; i >= 0; --i) {
        int power = pow(10, len - i - 1);

        for(int j = 0; j < 13; ++j) {
            if(inp[i] != '?') {
                int digit = getDigit(inp[i]) * power;
                dp[i][(digit + j) % 13] = (dp[i][(digit + j) % 13] + dp[i+1][j]) % MOD;

            }

            else {
                for(int k = 0; k <= 9; ++k) {
                    int digit = power * k;
                    dp[i][(digit + j) % 13] = (dp[i][(digit + j) % 13] + dp[i+1][j]) % MOD;
                }
            }
        }
    }

    cout << dp[0][5];
    return 0;
}

