modint count_dig(ll dig){
  if(dig==0) return modint(1);
  if(dig==1) return modint(1);
  if(dig==2) return modint(7);
  else return modint(10).pow(dig-2)*modint(7)*dig*(dig-1)/2;
}

int solve(){
  vector<string> T;
  reverse(S.begin(),S.end());
  int i=0;
  while(S.size()>=3){
    string s=S.substr(0,3);
    reverse(s.begin(),s.end());
    if(i%2==0) T.push_back(s);
    if(i%2==1) {T.push_back("-"+s);T.push_back("002");}
    S = S.substr(3);
    i++;
  }
  // DBG(T)

  ll dig0=0;
  ll dig1=0;
  ll dig2=0;
  ll digM=0;

  for(auto t:T){
    while(t.size()<=2) t="0"+t;
    if(t[0]=='-'){
      if(t[1]=='?') dig2++;
      else digM += ('9'-t[1])*100;
      if(t[2]=='?') dig1++;
      else digM += ('9'-t[2])*10;
      if(t[3]=='?') dig0++;
      else digM += ('9'-t[3])*1;
    }
    else{
      if(t[0]=='?') dig2++;
      else digM += (t[0]-'0')*100;
      if(t[1]=='?') dig1++;
      else digM += (t[1]-'0')*10;
      if(t[2]=='?') dig0++;
      else digM += (t[2]-'0')*1;
    }
  }
  digM%=13;

  // DBG(dig0)
  // DBG(dig1)
  // DBG(dig2)
  // DBG(digM)
  struct DIG{
    int d0,d1,d2;
    DIG(int i, int j, int k):d2(i),d1(j),d0(k){};
  };
  vector<DIG> ans;
  REP(i,13) REP(j,13) REP(k,13) {
    if(dig0==0&&k!=0) continue; 
    if(dig1==0&&j!=0) continue; 
    if(dig2==0&&i!=0) continue; 
    if((100*i+10*j+k+digM)%13==5) ans.emplace_back(i,j,k);
    }
  // for(auto a:ans) cout << a.d2 << " " << a.d1 << " " << a.d0 << "\n";
  modint res=0;
  int Maxdig = max({dig0,dig1,dig2});
  modint dp[Maxdig+10][13];
  memset(dp,0,sizeof(dp));
  dp[0][0] = 1;
  REP(i,13) dp[1][i] = (i<=9)?1:0;
  REP(i,Maxdig+1) REP(a,13) REP(k,13) dp[i+2][a] += (((a-k+13)%13)<=9) ? dp[i+1][k] : modint(0);
  for(auto a:ans) res += dp[dig2][a.d2]*dp[dig1][a.d1]*dp[dig0][a.d0];
  cout << res << endl;

  return 0;
}

