const int mod = 1e9+7;
const int maxn = 1e5+5;
int dp[maxn][13]; string s;

int dfs(const int i, const int j)
{
    if (i == s.size())
        return j == 5;
    int& ans = dp[i][j];
    if (-1 == ans) {
        ans = 0;
        if (s[i] != '?') {
            const int k = ((s[i]-'0') + j*10) % 13;;
            ans += dfs(i+1,k);
            ans %= mod;
        }
        else {
            FOR(d,0,10) {
                const int k = (j*10+d) % 13;
                ans += dfs(i+1,k);
                ans %= mod;
            }
        }
    }
    return ans;
}

int main()
{
    while (cin >> s) {
        memset(dp,-1,sizeof(dp));
        cout << dfs(0,0) << endl;
    }
    return 0;
}

