typedef long long ll;
constexpr long long MOD = 1000000007;
std::string S;
std::vector<std::vector<ll>> dp;

ll sol(ll i, ll j){
  if ( dp[i][j] != -1 ) return dp[i][j];

  ll rtn = 0;
  if ( S[i-1] == '?' ) {
    for(ll k=0; k<13; k++) {
      for(ll l=0; l<10; l++) {
        if ( (10*k+l)%13 == j ) {
          rtn += sol(i-1,k) % MOD;
        }
      }
    }
  }
  else {
    ll s = S[i-1] - '0';
    for(ll k=0; k<13; k++) {
      if ( (10*k+s)%13 == j ) {
        rtn += sol(i-1, k) % MOD;
      }
    }
  }
  return dp[i][j] = rtn % MOD;
}


int main (void) {
  std::cin >> S;
  dp.resize(S.size()+1); for(ll i=0; i<S.size()+1; i++) dp[i].assign(13, -1);

  for(ll i=0; i<13; i++) {
    if ( i == 0 ) dp[0][i] = 1;
    else dp[0][i] = 0;
  }

  std::cout << sol(S.size(), 5)%MOD << std::endl;
  return 0;
}

