    int ans=0;
    if(dp[index][mod]!=-1)
        return dp[index][mod];
    if(s[index]!='?'){
        int effective=(s[index]-'0')*ten_mod[index];
        effective%=13;
        ans+=func(s,index+1,n,(effective+mod)%13);
