// MOD
ll gcd(ll p, ll q) { return (q == 0) ? p : gcd(q, p % q); }
ll pow(ll a, ll n, ll m) {
  if (n == 0)
    return 1;
  if (n & 1)
    return ((a % m) * pow(a, n - 1, m)) % m;
  auto b = pow(a, n / 2, m);
  return (b * b) % m;
}
ll inv(ll a, ll p) { return pow(a, p - 2, p); }
constexpr ll MOD = 1e9 + 7;

using DpKey = tuple<ll, ll>;
ll f(string const &S, DpKey const &key, vector<ll> const &pow10i,
     u_map<DpKey, ll> &dp) {
  if (dp.find(key) != dp.end())
    return dp[key];
  ll i = get<0>(key);
  ll r = get<1>(key);
  ll c = S[S.size() - 1 - i];
  ll M = 13LL;
  if (i == 0) {
    if (c == '?')
      return dp[key] = (r < 10) ? 1 : 0;
    ll n = (c - '0');
    return dp[key] = ((n % M) == r) ? 1 : 0;
  }
  if (c == '?') {
    ll sum = 0LL;
    for (ll const &n : range(10LL)) {
      ll s = (M - (((pow10i[i] * n) % M) - r)) % M;
      (sum += f(S, DpKey{i - 1, s % M}, pow10i, dp));
      sum %= MOD;
    }
    return dp[key] = sum;
  }
  ll n = (c - '0');
  ll s = (M - (((pow10i[i] * n) % M) - r)) % M;
  return dp[key] = f(S, DpKey{i - 1, s % M}, pow10i, dp);
}
vector<ll> init(ll mod, ll N) {
  auto ret = vec(N, 1LL);
  partial_sum(ret.begin(), ret.end(), ret.begin(),
              [mod](auto prev, auto n) { return (prev * 10) % mod; });
  return ret;
}
int main() {
  string S;
  input(S);
  ll N = S.size();
  auto dp = u_map<DpKey, ll>{};
  print(f(S, DpKey{N - 1LL, 5LL}, init(13, 100001), dp));
}

