const int MOD = 1000000007;

int main(){
  string S;
  cin >> S;

  int strLen = S.length();

  int a[6];
  int sSum = 0;
  int qNum = 0;

  int restL[6][10];
  for(int i = 0; i < 6; i++){
    for(int j = 0; j < 10; j++){
      int t = pow(10, i) * j;
      restL[i][j] = t % 13;
    }
  }

  vector<int> ab;
  for(int i= 0; i < 6; i++) a[i] = 0;
  for(int i = 0; i < strLen; i++){
    if(S[i] == '?'){
      int pos = (strLen - i - 1) % 6;
      ab.push_back(pos);
      a[pos] += 1;
      qNum += 1;
    } else {
      int c = S[i] - '0';
      int pos = (strLen - i - 1) % 6;
      ll cT = restL[pos][c];
      sSum += cT % 13;
    }
  }

  sSum %= 13;

  vector<vector<ll>> dp(100050, vector<ll>(13,0));
  dp[0][0] = 1;



  for(int i = 1; i < qNum+1; i++){
    int cp = ab[i-1];
    for(int j = 0; j < 10; j++){
      int plus = restL[cp][j];
      for(int k = 0; k < 13; k++){
        int l = k - plus;
        if(l < 0) l+= 13;
        dp[i][k] += dp[i-1][l];
        dp[i][k] %= MOD;
      }
    }
  }

  int u = 5 -sSum;
  if(u < 0) u+= 13;
  ll ans = dp[qNum][u];
  ans %= MOD;
  cout << ans << endl;

  return 0;
}

