	scanf("%s", s);

	static LL dp[10010][13];
	memset(dp, 0, sizeof(dp));
	dp[0][0] = 1;

	LL len = strlen(s);

	LL mod_keta = 1;

	for (LL i = 1; i <= len; i++) {

		for (LL num = 0; num <= 9; num++) {
			if (s[len - i] != '?' && num != (s[len - i] - '0')) {
				continue;
			}

			LL mod13_keta = (mod_keta * num) % 13;

			for (LL num_prev = 0; num_prev <= 12; num_prev++) {

				LL mod13_result = (num_prev + mod13_keta) % 13;

				dp[i][mod13_result] += dp[i - 1][num_prev];
				dp[i][mod13_result] %= MOD;
			}
		}

		mod_keta = (mod_keta * 10) % 13;
	}

	printf("%lld\n", dp[len][5]);

	return 0;
}

