int tens_mod(int numdig) {
  switch (numdig % 6) {
  case 0:
    return 1;
  case 1:
    return 10;
  case 2:
    return 9;
  case 3:
    return 12;
  case 4:
    return 3;
  case 5:
    return 4;
  }
  return 0;
}

