  vector<vector<int>> dp(s.length(), vector<int>(13, 0));

  if (s[0] == '?') {
    for (int i = 0; i < 10; i++) {
      dp[0][i] = 1;
    }
  } else {
    dp[0][s[0]-'0'] = 1;
  }

  for (int i = 1; i < s.length(); i++) {
    if (s[i] == '?') {
      for (int j = 0; j < 10; j++) {
        for (int k = 0; k < 13; k++) {
          int mod = ((tens_mod(i)*j) % 13 + k) % 13;
          dp[i][mod] = (dp[i][mod] % MOD) + (dp[i-1][k] % MOD);
        }
      }
    } else {
      for (int k = 0; k < 13; k++) {
        int mod = ((tens_mod(i)*(s[i]-'0')) % 13 + k) % 13;
        dp[i][mod] = (dp[i][mod] % MOD) + (dp[i-1][k] % MOD);
      }
    }
  }
  cout << dp[s.length()-1][5] % MOD << endl;
  return 0;
}

