            }
        }
    }
}

class UnionFind
{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}
ll dp[100010][13] = {0};
void solve(std::string S)
{
    for (int i = 0; i < S.size(); i++)
    {
        if (i != 0)
        {
            if (S[i] == '?')
            {
                for (int k = 0; k < 10; k++)
                {
                    for (int j = 0; j < 13; j++)
                    {
                        dp[i][(j * 10 + k) % 13] += dp[i - 1][j] % MOD;
                        dp[i][(j * 10 + k) % 13] %= MOD;
                    }
                }
            }
            else
            {
                int number = S[i] - '0';
                for (int j = 0; j < 13; j++)
                {
                    dp[i][(j * 10 + number) % 13] += dp[i - 1][j];
                    dp[i][(j * 10 + number) % 13] %= MOD;
                }
            }
        }
        else
        {
            if (S[i] == '?')
            {
                for (int j = 0; j < 10; j++)
                {
                    dp[i][j] = 1;
                }
            }
            else
            {
                dp[i][S[i] - '0'] = 1;
            }
        }
    }

    cout << dp[S.size() - 1][5] << endl;
}

