//============================================================================
// 解法
// 漸化式：
// dp[i][j] = 先頭i文字目として考えられるもののうち、13で割った余りがjのもの
// 
// iの昇順にdpを見ると、i-1文字目までを13で割ったあまり(dp[i-1][j]のj)と
// s[i]としてあり得る数字をすべて試すことでdp[i][0] ~ dp[i][12]の値がわかる
// 13で割った余りが5となるものを出力すればよい。(dp[n][5]が答え)
//============================================================================

int main() {
	int i, j, k;
	string s;
	ull dp[100005][13];
	ull ans;

	cin >> s; // 一旦文字列として受け取り
	int n = s.length();
	dp[0][0] = 1;

	roop(i, n) {
		if (s[i] == '?') {
			roop(j, 10) { // 変数jで？に0-9を入れて試す
				roop(k, 13) { // 変数kで13で割った余りを10の13乗分試す
					dp[i + 1][(k * 10 + j) % 13] += dp[i][k];
					dp[i + 1][(k * 10 + j) % 13] %= MOD;
				}
			}
		} else {
			int r = s[i] - '0';
			roop(j, 13) {
				dp[i + 1][(j * 10 + k) % 13] += dp[i][j];
				dp[i + 1][(j * 10 + k) % 13] %= MOD;
			}
		}
	}
	ans = dp[n][5]%MOD;

	cout << ans << endl;
	return 0;
}

