                    dp[i + 1][(j + num) % 13] += dp[i][j];
                }
            } else {
                ll num = s[i] - '0';
                num *= cur;
                dp[i + 1][(j + num) % 13] += dp[i][j];
            }
        }
        cur = (10 * cur) % 13;
    }
    cout << dp[n][5].x << endl;
}

