    if (i == n) return dp[mod][i] = mod == 5 ? 1 : 0;
    if (s[i] != '?') {
        int d = s[i]-'0';
        int m = (1LL*d*modexp(10,i)) % 13;
        return dp[mod][i] = f((mod+m)%13,i+1);
    }
    else {
        dp[mod][i] = 0;
        for (int d = 0; d < 10; d++) {
            int m = (1LL*d*modexp(10,i)) % 13;
            dp[mod][i] = (dp[mod][i] + f((mod+m)%13,i+1)) % M;        
        }
        //cout << mod << ' ' << i << ": " << dp[mod][i] << '\n';
        return dp[mod][i];
    }
}

