const long long MOD = 1000000007;

long long modpow(long long a, long long n, long long mod) {
    if (n == 0) return 1;

    if (n == 1) return a % mod;

    if (n % 2 == 0) {
        long long half = modpow(a, n / 2, mod) % mod;
        return half * half % mod;
    }
    else return modpow(a, 1, mod) * modpow(a, n - 1, mod);
}

