string Stringify(int x){
	string s;
	if(x == 0)
		s = "000";
	else if(x < 10) 
		s = "00" + to_string(x);
	else if(x < 100) 
		s = "0" + to_string(x);
	else if(x < 1000) 
		s = to_string(x);
	return s;
}

bool isMatch(string w, int x){
	string s = Stringify(x);
	for (int i = 0; i < s.length(); ++i)
		if(s[i] != w[i] && w[i] != '?')
			return false;
	return true;
}

vector<SM> getWildcards(int x){
	string s = Stringify(x);
	vector<SM> v;
	int mod = x%13;
	v.push_back(createSM(string() + "?" + s[1] + s[2],mod));
	v.push_back(createSM(string() + s[0] + "?" + s[2],mod));
	v.push_back(createSM(string() + s[0] + s[1] + "?",mod));
	v.push_back(createSM(string() + "??" + s[2],mod));
	v.push_back(createSM(string() + "?" + s[1] + "?",mod));
	v.push_back(createSM(string() + s[0] + "??",mod));
	v.push_back(createSM(string() + "???",mod));

	return v;
}

map<SM,int> initMap(vector <string> v){
	map<SM,int> m;
	for (int i = 0; i < v.size(); ++i)
	{
		for (int j = 0; j < 13; ++j)
		{
			SM temp;
			temp.wild = v[i].c_str();
			temp.reminder = j;
			m.insert(std::pair<SM,int>(temp,0));
		}
	}
	return m;
}

int getModulo(int x){
	if(x < 0) x +=13;
	else x %=13;
	return x;
}


long long doCalc(int l, int r, int m){
	if(r - l > 3){
		long long res = 0;
		for (int i = 0; i < 13; ++i)
		{
			res +=(doCalc(l,r-3,i)%BIGMODE)*(doCalc(r-3,r,getModulo(m+i))%BIGMODE);
			res = res%BIGMODE;
		}
		return res;
	}
	SM mySM;
	mySM.wild = tar.substr(l,r-l);
	mySM.reminder = m;
	return dicMap[mySM];
}


