        return out;
    }
    static ostream& write_repr(ostream& out, const tuple<TS...>& t) {
        out << "(";
        tuple_enumerate(t, [&out](i64 i, const auto& e) {
            if(i != 0) out << ",";
            WRITE_REPR(out, e);
        });
        out << ")";
        return out;
    }
};

