int main() {
  string s;
  cin >> s;

  int N = 13;
  string t = s;
  reverse(t.begin(), t.end());

  vector<ll> dp(N, 0);
  dp[0] = 1;

  ll base = 1;
  for (int i = 0; i < t.size(); i++) {
    vector<ll> next(N, 0);
