        ll d = ((t[i] - '0') * base);
        next[(d + j) % N] += dp[j];
        next[(d + j) % N] %= MOD;        
      }
    }
    dp = next;
    base *= 10;
    base %= 13;
  }
  cout << dp[5] << endl;
  return 0;
}

