int main(){

  string S = is();
  ll digits = S.size();

  // dp[d][m] 上からd桁目（1-indexed）までを見たとき、m mod 13 となる数の数
  // d : 0 ~ digits 0は番兵
  vector<vector<ll> > dp(digits+1, vector<ll>(13, 0));

  // mpow[i] := 10^i % 13
  vector<ll> mpow(digits, 1);
  REP(i, 1, digits) mpow[i] = mpow[i-1] * 10 % 13;

  // 全ての?について0を選んだときのmodを求める
  ll initial_mod = 0;
  REP(d, 1, digits+1){
    char c = S[d-1];
    if (c=='?') continue;
    initial_mod = (initial_mod + (c - '0') * mpow[digits-d]) % 13;
  }
  dp[0][initial_mod] = 1;


  // 桁DPだが、?なら何でも選べるし、0~9なら固定なので、exact, smallerの区別はない
  REP(d, 1, digits+1){
    // d : 1 ~ digits
    char c = S[d-1];

    if (c == '?'){
      // 0~9を全て選べる
      rep(j, 10){
        ll jmod = j * mpow[digits-d] % 13;
        rep(i, 13){
          dp[d][(i+jmod)%13] += dp[d-1][i];
          dp[d][(i+jmod)%13] %= MOD;
        }
      }
    }
    else{
      // もう考慮してあるので、そのまま移すだけ
      rep(i, 13){
        dp[d][i] = dp[d-1][i];
      }
    }
  }

  cout << dp[digits][5] << endl;


}

