ll modInverse(ll a, ll m) 
{ 
    ll m0 = m; 
    ll y = 0, x = 1; 

    if (m == 1) 
      return 0; 

    while (a > 1) 
    { 
        // q is quotient 
        ll q = a / m; 
        ll t = m; 

        // m is remainder now, process same as 
        // Euclid's algo 
        m = a % m, a = t; 
        t = y; 

        // Update y and x 
        y = x - q * y; 
        x = t; 
    } 

    // Make x positive 
    if (x < 0) 
       x += m0; 

    return x; 
} 
pair<pair<ll,ll>,ll> maxSubArraySum(vector<ll>a, int size) 
{ 
    ll max_so_far = LLONG_MIN, max_ending_here = 0, 
       start =0, end = 0, s=0; 
    ll p=0;
    for (ll i=0; i< size; i++ ) 
    { 
        max_ending_here += a[i]; 

        if (max_so_far < max_ending_here) 
        { 
            max_so_far = max_ending_here; 
            start = s; 
            end = i; 
        } 

        if (max_ending_here < 0) 
        { 
            max_ending_here = 0; 
            s = i + 1; 
        } 
    } 

    return {{max_so_far,end},(end - start + 1)}; 
} 
