int amari[13];

void calc(int a, int b, int c) {
   memset(amari, 0, sizeof(amari));
   int d, e, f;
   for (int i = 0; i <= 9; i++) {
      if (a == -1) d = i;
      else d = a;
      for (int j = 0; j <= 9; j++) {
         if (b == -1) e = j;
         else e = b;
         for (int k = 0; k <= 9; k++) {
            if (c == -1) f = k;
            else f = c;
            int tmp = 100 * d + 10 * e + f;
            amari[tmp % 13]++;
            if (c != -1) break;
         }
         if (b != -1) break;
      }
      if (a != -1) break;
   }
}
int ctoi(const char c){
  switch(c){
    case '0': return 0;
    case '1': return 1;
    case '2': return 2;
    case '3': return 3;
    case '4': return 4;
    case '5': return 5;
    case '6': return 6;
    case '7': return 7;
    case '8': return 8;
    case '9': return 9;
    default : return -1;
  }
}
int main() {
   string S;
   cin >> S;
   int N = (int)S.size();
   int M = N / 3 + N % 3;
   ll dp[13][M + 1];
   memset(dp, 0, sizeof(dp));
   for (int m = 1; m <= M; m++) {
      int a, b, c;
      int id;
      id = N - 1 - (m - 1) * 3;
      // cout << id << endl;
      if (S[id] == '?') a = -1;
      else a = ctoi(S[id]);
      id--;
      if (S[id] == '?') b = -1;
      else b = ctoi(S[id]);
      id--;
      if (S[id] == '?') c = -1;
      else c = ctoi(S[id]);
      // cout << c << " " << b << " " << a << endl; 
      calc(c, b, a);
      if (m == 1) {
         for (int i = 0; i < 13; i++) {
            dp[i][m] = amari[i];
         }
      } else {
         if (m % 2 == 0) {
            for (int i = 0; i < 13; i++) {
               for (int j = 0; j < 13; j++) {
                  int k = (i + 13 - j) % 13;
                  dp[i][m] += dp[j][m - 1] * amari[(13 - k) % 13];
                  dp[i][m] %= MOD;
               }
            }
         } else {
            for (int i = 0; i < 13; i++) {
               for (int j = 0; j < 13; j++) {
                  int k = (i + 13 - j) % 13;
                  dp[i][m] += dp[j][m - 1] * amari[k];
                  dp[i][m] %= MOD;
               }
            }
         }
      }
      // for (int i = 0; i < 13; i++) cout << amari[i] << " ";
      // cout << endl;
      // for (int i = 0; i < 13; i++) cout << dp[i][m] << " ";
      // cout << endl;
   }
   ll ans = dp[5][M];
   if (ans < 0) ans += MOD;
   cout << ans << endl; 
   return 0;
}

