string s;
long long d[100000][13];

int main(){
    cin >> s;
    int l = s.size();
    reverse(s.begin(),s.end());
    if(s[0] == '?'){
        for(int i=0;i<13;i++) d[0][i] = 1;
    }else{
        for(int i=0;i<13;i++) d[0][i] = 0;
        d[0][(int)s[0]-'0']++;
    }
    long long p = 10;
    for(int i=1;i<l;i++){
        if(s[i]=='?'){
            for(int j=0;j<13;j++) d[i][j] = 0;
            for(int j=0;j<10;j++){
                long long q = p * j;
                q %= 13;
                for(int k=0;k<13;k++){
                    d[i][(k+q)%13] += d[i-1][k];
                    d[i][(k+q)%13] %= MOD;
                }
            }
        }else{
            long long q = p * ((int)s[i] - '0');
            q %= 13;
            for(int j=0;j<13;j++){
                d[i][(j+q)%13] = d[i-1][j];
            }
        }
        p *= 10;
        p %= 13;
    }
    cout << d[l-1][5] << endl;
    return 0;
}

