template<typename T=mnt, T P=MOD> class Zp {
  private:
    T n;
    template<typename U> inline constexpr void set(const U& m) noexcept { n = cast(m); }
  public:
    static constexpr T mod = P;
    template<typename U> static inline constexpr T cast(const U& m) noexcept {
      T v = (T)m;
      v %= mod;
      if(v < 0) v += mod;
      return v;
    }
    static inline constexpr T cast(const Zp& m) noexcept { return m.get(); }
    template<typename U> static inline constexpr Zp inv(const U& m) noexcept {
      T x, y, d = [&x, &y](T a, T b) {
        x = 1; y = 0;
        while (b) {
          T t = a / b;
          a -= t * b; swap(a, b);
          x -= t * y; swap(x, y);
        }
        return a;
      }((T)m, mod);
      assert( d == 1 );
      return Zp(x);
    }
    inline constexpr Zp() noexcept : n(0) {}
    template<typename U> inline constexpr Zp(const U& m) noexcept { set(m); }
    inline constexpr T get() const noexcept { return n; }
    template<typename U> inline constexpr Zp& operator=(const U& m) noexcept { set(m); return *this; }
    template<typename U> inline constexpr Zp& operator+=(const U& m) noexcept { set( n + cast(m) ); return *this; }
    template<typename U> inline constexpr Zp& operator-=(const U& m) noexcept { set( n - cast(m) ); return *this; }
    template<typename U> inline constexpr Zp& operator*=(const U& m) noexcept { set( n * cast(m) ); return *this; }
    template<typename U> inline constexpr Zp& operator/=(const U& m) noexcept { set( n * inv(cast(m)) ); return *this; }
    template<typename U> inline constexpr Zp pow(U e) const noexcept {
      if(e==0) return Zp(1);
      else if(e < 0) return inv(pow(-e));
      else {
        Zp a = *this, r = 1;
        while (e > 0) {
          if (e & 1) r *= a;
          a *= a;
          e >>= 1;
        }
        return r;
      }
    }
    template<typename U> explicit inline constexpr operator U() const noexcept { return (U)n; }
    inline constexpr Zp operator+() const noexcept { return *this; }
    inline constexpr Zp operator-() const noexcept { return Zp(-n); }
    template<typename U, typename V> friend inline constexpr Zp operator+(const U& n, const V& m) noexcept { return Zp(n) += m; }
    template<typename U, typename V> friend inline constexpr Zp operator-(const U& n, const V& m) noexcept { return Zp(n) -= m; }
    template<typename U, typename V> friend inline constexpr Zp operator*(const U& n, const V& m) noexcept { return Zp(n) *= m; }
    template<typename U, typename V> friend inline constexpr Zp operator/(const U& n, const V& m) noexcept { return Zp(n) /= m; }
    friend constexpr istream& operator>>(istream& is, Zp& n) noexcept { T m; is >> m; n = m; return is; }
    friend constexpr ostream& operator<<(ostream& os, const Zp& n) noexcept { os << n.get(); return os; }
    template<typename U, typename V> friend inline constexpr bool operator==(const U& n, const V& m) noexcept { return Zp(m).get() == Zp(n).get(); }
    template<typename U, typename V> friend inline constexpr bool operator!=(const U& n, const V& m) noexcept { return !(n == m); }
};
