  int i,j,k;
  int n  = num.length();

  int dp[n+1][13];
  for(i=0;i<=n;i++)
    for(j=0;j<13;j++)
      dp[i][j]=0;
  dp[0][0]=1;

  for(i=0;i<n;i++){
    for(j=0;j<10;j++){

      int next = num[i]-'0';
      if(num[i]=='?')
