      for(k=0;k<13;k++){
        int rem = (10*k + next)%13; 
        dp[i+1][rem] += dp[i][k];
        dp[i+1][rem]%=mod;
      }

      if(num[i]!='?') break;

    }

  }

  cout<<dp[n][5];


  return 0;
}

