int s2i(char c) {
  return ((c-'0')==15 ? -1 : c-'0');
}

int mod13_pad(int i) {
  return mod13[i%6];
}

void solve(int N, int remain) {
  int cnt=0;
  /* rep(i, 10) { */
  /*   dp[0][i] = 1; */
  /* } */
  rep(i, N) {
    if(!q[i]) continue;
    if(cnt==0) {
      rep(j, 10) {
        dp[0][(mod13_pad(N-i-1)*j)%13] += 1;
      }
    } else {
      rep(j, 10) {
        rep(k, 13) {
          dp[cnt][(k+(mod13_pad(N-i-1)*j))%13] += dp[cnt-1][k];
        }
      }
    }
    cnt++;
  }
  cout << dp[cnt-1][remain].x << endl;
}

