  rep(i, N) {
    int x=s2i(S[i]);
    if(x==-1) q[i]=true;
    else sum+=x*mod13_pad(N-i-1);
  }
  sum = sum%13;
  int remain=(18-sum)%13;
  solve(N, remain);
  return 0;
}

