template <class T>
long long modpow2(int m, T n) {
  int r = 1;
  while (n > 0) {
    if (n & 1) {
      r *= m;
      r %= 13;
    }
    m *= m;
    m %= 13;
    n /= 2;
  }
  return r;
}

void solve(string S) {
