  dp[0][0] = 1;

  xrep(i, N) {
    rep(j, 13) {
      if (S[i-1] == '?') {
        rep(k, 10) {
          pre = (j - k) * inv_10;
          pre %= 13;
          if (pre < 0) pre += 13;
          dp[i][j] += dp[i - 1][pre];
        }
      } else {
        cur = S[i-1] - '0';
        pre = (j - cur) * inv_10;
        pre %= 13;
        if (pre < 0) pre += 13;
        dp[i][j] = dp[i - 1][pre];
      }
      dp[i][j] %= MOD;
    }
  }

