using namespace std;

class pow10calculater{
    public:
    long long product[100020];

    pow10calculater(){
        product[0] = 1;
        for( int i = 1; i < 100020; i++ ){
            product[i] = (10 * product[i-1]) % 13;
        }
    }

    long long get(int i){
        return product[i];
    }
};

int main(){
    // 10のi乗を13で割ったあまりを計算するクラス　.get(i)で呼び出す
    pow10calculater pow10;
    //　入力　→　vector<int>に入れなおす作業（'?'は１５になる）
    string s; cin >> s;
    int N = s.size();
    vector<int> S(N);
    for( int i = 0; i < N; i++ ){
        int k = s[N-i-1] - 48;
        S[i] = k;
    }

    int question = '?' - 48;//'?' - 48 == 15
    long long MOD = 1000000007LL;
    //動的計画法　dp[ここまでに見つかった解][１３で割ったあまり]　答えはdp[N-1][5]
    vector<vector<long long>> dp(N,vector<long long>(13,0LL));
    for( int i = 0; i < N; i++ ){

        if( i == 0 ){
            if( S[i] != question ){
                dp[0][S[i]] = 1LL;
            } else {
                for( int j = 0; j < 10; j++ ){
                    dp[0][j] = 1LL;
                }
            }
        } else {
            if( S[i] != question ){
                for( int j = 0; j < 13; j++ ){
                    dp[i][(j+S[i]*pow10.get(i)) % 13] = dp[i-1][j];
                }
            } else {
                for( int j = 0; j < 13; j++ ){
                    for( int k = 0; k < 10; k++ ){
                        dp[i][(j + k*pow10.get(i)) % 13] += dp[i-1][j];
                        dp[i][(j + k*pow10.get(i)) % 13] %= MOD;
                    }
                }
            }
        }

    }


    cout << dp[N-1][5] << endl;   
}

