const int mod = 1e9 + 7;

int getMod(int n) {
    if(n % 6 == 0) return 1;
    if(n % 6 == 1) return 10;
    if(n % 6 == 2) return 9;
    if(n % 6 == 3) return 12;
    if(n % 6 == 4) return 3;
    return 4;
}

int main() {
    string S; cin >> S;
    int N = S.length();
    vector<vector<int>> dp(N+1, vector<int>(13,0));
    dp[0][0] = 1;

    for(int i=N-1;i>=0;i--) {
        int dig = i;
        int j = N-dig-1;
        if(S[dig] == '?') {
            for(int num=0;num<=9;num++) {
                for(int m=0;m<13;m++) {
                    int r = ((getMod(j) * num )%13 + m)%13;
                    dp[j+1][r] += dp[j][m] % mod;
                    dp[j+1][r] %= mod;
                }
            }
        } else {
            int num = S[dig] - '0';
            for(int m=0;m<13;m++) {
                int r = ((getMod(j) * num )%13 + m)%13;
                dp[j+1][r] += dp[j][m] % mod;
                dp[j+1][r] %= mod;
            }
        }
    }
    cout << dp[N][5] % mod << endl;
    return 0;
}

