    15*10+3≡2*10+3(mod13)
    15%13から153%13を計算することができる。


    */
    string s;
    cin >> s;
    dp[0][0] = 1;
    for(int i=0; i < s.length(); i++){
        if(s[i] == '?'){
            for(int j=0; j < 13; j++){
                for(int k=0; k < 10; k++){
                dp[i + 1][(j*10+k)%13] += dp[i][j];
                }
            }
        }else{
            for(int j=0; j < 13; j++){
                dp[i + 1][(j*10 + (s[i] - '0')) % 13] += dp[i][j];
            }
        }
    }

    out(dp[s.size()][5]);
}

