int main() {
    cin >> S;
    int l = S.size();
    if (l % 3 == 1) {
        S = "00" + S;
        l += 2;
    }
    if (l % 3 == 2) {
        S = "0" + S;
        l++;
    }

    vvi DP(l / 3 + 1, vi(13, 0));
    DP[0][0] = 1;
    for (int i = 1; i <= l / 3; i++) {
        char c1 = S[i * 3 - 3];
        char c2 = S[i * 3 - 2];
        char c3 = S[i * 3 - 1];

        vi dp(13, 0);
        for (int n = 0; n < 1000; n++) {
            int cc = n / 100;
            if (c1 != '?' && c1 != cc + '0') continue;
            cc = (n % 100) / 10;
            if (c2 != '?' && c2 != cc + '0') continue;
            cc = n % 10;
            if (c3 != '?' && c3 != cc + '0') continue;
            dp[n % 13]++;
        }

        for (int j = 0; j < 13; j++) {
            for (int k = 0; k < 13; k++) {
                DP[i][(j + k * 1000) % 13] += DP[i - 1][j] * dp[k];
                DP[i][(j + k * 1000) % 13] %= MOD;
            }
        }
    }

    cout << DP[l / 3][5] << endl;
    return 0;
}

