	auto s = load<string>();
	auto dyn = vector<array<M, 13>>((int)s.size()+1);
	dyn[0][0] = 1;
	auto mult = C(1);
	for (auto e=0; e<(int)s.size(); ++e, mult *= 10) {
		auto chr = s[(int)s.size()-1-e];
		if (chr == '?') {
			for (auto d=0; d<10; ++d) {
				auto digit = C(d);
				for (auto r=0; r<13; ++r) {
					auto r2 = r + digit * mult;
					dyn[e+1][r2.val] += dyn[e][r];
				}
			}
		} else {
			auto digit = C(chr - '0');
			for (auto r=0; r<13; ++r) {
				auto r2 = r + digit * mult;
				dyn[e+1][r2.val] += dyn[e][r];
			}
		}
	}
	cout << dyn[(int)s.size()][5] << '\n';
}

