    deque<ll> list;
    for(ll i=0;i<N;i++){
        if(S[i]!='?'){
            ll c=S[i]-'0';
            def+=modpow(10,N-i-1,13)*c;
            def%=13;
        }
        else {
            list.emplace_back(modpow(10,N-i-1,13));
        }
    ;}
    ll siz=list.size();
    vector<vector<ll>> dp(siz+1, vector<ll>(13, 0));
