                dp[i][(k+(j*list[i-1]))%13]+=dp[i-1][k];
                dp[i][(k+(j*list[i-1]))%13]%=MOD;
            }
        ;}
    ;}
    cout<<dp[siz][5]<<endl;
return 0;
}

