llong modpow(llong base, llong ex, llong m) {
    llong res = 1;
    llong temp = base%m;
    while(ex) {
        if (ex&1) res *= temp;
        temp *= temp;
        temp %= m; res %= m;
        ex /= 2;
    }
    return res;
}

