static void countMods(
    string substr, 
    vector<SDWORD> &veclMods)
{
    for (SDWORD lIdx = 0; lIdx < 13; lIdx++) {
        veclMods[lIdx] = 0;
    }
    reverse(substr.begin(), substr.end());

    for (SDWORD lNum = 0; lNum < 1000; lNum ++) {
        char acRefStr[4];
        sprintf(acRefStr, "%03d", lNum);
        if (matchDigit3(substr, acRefStr)) {
            veclMods[lNum % 13] ++;
        }
    }
}


