const long long MOD = 1000000007;


ll dp[100010][13];
void solve(std::string S){
  dp[0][0]=1;
  ll n = S.size();
  for(ll i=0; i<n; i++) {
    char x = S[i];
    ll s = (x=='?' ? 0 : x-'0');
    ll g = (x=='?' ? 9 : x-'0');
    for(ll j=s; j<=g; j++) {
      for(ll k=0; k<13; k++) {
	dp[i+1][(k*10+j) % 13] += dp[i][k];
	dp[i+1][(k*10+j) % 13] %= MOD;
      }
    }
  }
  std::cout << dp[n][5] << std::endl;
}

int main(){
  std::string S;
  std::cin >> S;
  solve(S);
  return 0;
}

