    else
    {
        ll powx=power(10LL,n-idx-1,13LL);
        powx=(powx*(s[idx]-'0'))%13;
        powx%=13;
        res=add(res,F(idx+1,(rem+powx)%13),mod);
    }
    return dp[idx][rem]=res;
}

