const long mod = 1000000007;

int ctoi(char c) {
  return c - '0';
}

void update_counts(
    int n,
    const std::array<long, 13>& prev_counts,
    std::array<long, 13>& counts)
{
  for (int prev_rem = 0; prev_rem < 13; ++prev_rem) {
    const auto index = (prev_rem * 10 + n) % 13;
    counts[index] += prev_counts[prev_rem];
    counts[index] %= mod;
  }
}

long solve(const std::string& s)
{
  const auto len = static_cast<int>(s.size());
  std::array<std::array<long, 13>, 2> counts_array = {};

  if (s[0] == '?') {
    std::fill(counts_array[0].begin(), counts_array[0].begin() + 10, 1);
  } else {
    counts_array[0][ctoi(s[0])] = 1;
  }

  for (int i = 1; i < len; ++i) {
    const auto& prev_counts = counts_array[(i - 1) % 2];
    auto& counts = counts_array[i % 2];
    std::fill(counts.begin(), counts.end(), 0);
    if (s[i] == '?') {
      for (int j = 0; j <= 9; ++j) {
        update_counts(j, prev_counts, counts);
      }
    } else {
      update_counts(ctoi(s[i]), prev_counts, counts);
    }
  }

  return counts_array[(len - 1) % 2][5];
}

int main()
{
  std::string s;
  std::cin >> s;

  std::cout << solve(s) << std::endl;
}

