ll power(ll x, ll n, ll mod) {
  ll res = 1;
  x %= mod;
  while (n) {
    if (n & 1)
      res = (res * x) % mod;
    x = (x * x) % mod;
    n >>= 1;
  }
  return res;
}

char arr[N];
ll n;
ll pow10[N];
ll dp[N][20];

ll recur(ll pos, ll rem) {
  if (pos == n + 1)
    return rem == 5;
  ll &ans = dp[pos][rem];
  if (ans != -1)
    return ans;

  ans = 0;
  if (arr[pos] == '?') {
    for (ll i = 0; i <= 9; i++) {
      ans += recur(pos + 1, (rem + pow10[n - pos] * i) % 13);
    }
  } else
    ans += recur(pos + 1, (rem + pow10[n - pos] * (arr[pos] - '0')) % 13);

  if (ans >= mod)
    ans %= mod;
  return ans;
}

