vector<int64_t> f(int a, vector<int64_t> y) {
	vector<int64_t> ans(13, 0);
	rep(i, 13) {
		if (i - a < 0) ans.at(i) = y.at(i + 13 - a);
		else ans.at(i) = y.at(i - a);
	}
	return ans;
}

vector<int64_t> plas(vector<int64_t> y, vector<int64_t> u) {
	vector<int64_t> ans(13, 0);
	rep(i, 13) ans.at(i) = y.at(i) + u.at(i);
	return ans;
}

