ll MOD = 1000000000 + 7;
ll c[100050][13];
int initCount(){
    for(ll yi = 0; yi < 100050; yi++){
        for(ll xi = 0; xi < 13; xi++){
            c[yi][xi] = -1;
        }
    }
}

ll solve(ll y, ll x,string& s){
    if(c[y][x] != -1){
        return c[y][x];
    }
    if(s[y] != '?'){
        //全部の値を更新
        int tmp = s[y] - '0';
        for(ll xi = 0; xi < 13; xi++){
            c[y][(xi * 10 + tmp) % 13] = solve(y-1,xi,s) % MOD;
        }
        return c[y][x];
    }
    //はてなの時の処理
    for(int tmp = 0; tmp < 10; tmp++){
        for(ll xi = 0; xi < 13; xi++){
            if(tmp == 0){
                c[y][(xi * 10 + tmp) % 13] = solve(y - 1,xi,s) % MOD;
            }else{
                c[y][(xi * 10 + tmp) % 13] += solve(y - 1,xi,s) % MOD;
            }
        }
    }
    return c[y][x];
}

