using namespace std;

typedef long long	ll;
const int N = int(1e5 + 10), M = 13;
ll dp[N][M];
const ll mod = int(1e9) + 7;
string s;
int n;

ll solve(int i, int mod){
	if(i < 0){
		return mod == 5;
	}

	if(dp[i][mod] != -1LL){
		return dp[i][mod];
	}

	if(s[i] != '?'){
		return dp[i][mod] = solve(i - 1, (mod * 10 + s[i] - '0') % M);
	}else{
		dp[i][mod] = 0LL;

		for(int j = 0 ; j < 10 ; j++){
			dp[i][mod] += solve(i - 1, (mod * 10 + j) % M);
			dp[i][mod] %= mod;
		}
	}

	return dp[i][mod];
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(NULL);

	cin >> s;

	n = s.length();

	dp[n][0] = 1LL;

	for(int i = n - 1 ; i >= 0 ; i--){
		for(int k = 0 ; k < M ; k++){
			if(s[i] == '?'){
				for(int j = 0 ; j < 10 ; j++){
					dp[i][(k * 10 + j) % 13] += dp[i + 1][k];

					if(dp[i][(k * 10 + j) % 13] >= mod){
						dp[i][(k * 10 + j) % 13] -= mod;
					}
				}
			}else{

				dp[i][(k * 10 + s[i] - '0') % 13] += dp[i + 1][k];

				if(dp[i][(k * 10 + s[i] - '0') % 13] >= mod){
					dp[i][(k * 10 + s[i] - '0') % 13] -= mod;
				}
			}
		}
	}

	memset(dp, -1LL, sizeof dp);

	printf("%lld\n", solve(n - 1, 0));
	// printf("%lld\n", dp[0][5]);

	return 0;
}

