ll score(ll* a,ll* c,ll p,ll n){
  int i;
  if(n==0){
    if(p==0)return 1;
    else return 0;
  }
  ll ret=0;
  for(i=0;i<min(*c+1,(ll)13);i++){
    ll np=(p-*a*i)%13;
    if(np<0)np+=13;
    ret+=((*c-i)/13+1)*score(a+1,c+1,np,n-1);
    if(ret>=MOD)ret%=MOD;
  }
  if(ret<0)return 1;
  return ret;
}

