void place(int i, int msb) {
  for (int k = 0; k < DIVS; ++k) {
    int pos = (msb + k * BASE) % DIVS;
    dp[i][pos] = (1LL * dp[i-1][k] + dp[i][pos]) % MOD;
  }
}

int solve() {
  for (int i = 0; i <= S; ++i) {
