int main() {



    string s;
    cin >> s;
    vector<vector<long long>> dp(s.size(), vector<long long>(13));
    long long mod = 1e9 + 7;

    int cp = 10;
    for (int i = s.size() - 1; i >= 0; --i)
    {
        if (s[i] != '?')
        {
            int num = s[i] - '0';
            if (i == s.size() - 1)
            {
                dp[i][num] = 1;
                continue;
            }
            for (int j = 0; j < 13; ++j)
            {
                int next = (j + num * cp) % 13;
                dp[i][next] += dp[i + 1][j];
                dp[i][next] %= mod;
            }
        }
        else
        {
            if (i == s.size() - 1)
            {
                for (int j = 0; j < 10; ++j)
                {
                    dp[i][j] = 1;
                }
                continue;
            }
            for (int j = 0; j < 10; ++j)
            {
                for (int k = 0; k < 13; ++k)
                {
                    int next = (k + j * cp) % 13;
                    dp[i][next] += dp[i + 1][k];
                    dp[i][next] %= mod;
                }
            }
        }
        cp *= 10;
        cp %= 13;
    }

    cout << dp[0][5] << endl;

    return 0;
}

