ll _pow(ll a, ll b)
{
  ll r = 1;
  for (int i = 0; i < 64; i++)
  {
    if ((b & (1l << i)) != 0)
    {
      r = (r * a) % MOD;
    }
    a = (a * a) % MOD;
  }
  return r;
}

int main()
