        for (ll k = 0; k < 10; k++)
        {
          int r = (k * _pow(10, i - 1)) % 13;
          dp[i][j] = (dp[i][j] + dp[i - 1][(j - r + 13) % 13]) % MOD;
        }
      }
    }
  }

  cout << dp[n][5] << endl;

  return 0;
}

