const int INF = 1e18;
const int MOD = 1e9 + 7;
const int N = 1e5 + 5;

string s;
int dp[N][13];

int f(int pos, int rem) {
	if (pos + 1 == s.size()) {
		return rem == 5;
	}

	if (dp[pos][rem] != -1) {
		return dp[pos][rem];
	}

	int res = 0;
	if (s[pos + 1] == '?') {
		for (int dig = 0; dig < 10; dig++) {
			int nrem = (rem * 10 + dig) % 13;
			res = (res + f(pos + 1, nrem)) % MOD;
		}
	} else {
		int nrem = (rem * 10 + (s[pos + 1] - '0')) % 13;
		res = (res + f(pos + 1, nrem)) % MOD;
	}

	return dp[pos][rem] = res;
}

int32_t main() {
