	cin >> s;

	int cnt = 0, r = 0;
	for (int i = 0; i < s.size(); i++) {
		r = (r * 10 + (s[i] - '0')) % 13;
		if (s[i] == '?') {
			cnt++;
		}
	}

	if (cnt == 0) {
		cout << (r == 5) << "\n";
		return 0;
	}

	for (int i = 0; i <= s.size(); i++) {
		for (int rem = 0; rem < 13; rem++) {
			dp[i][rem] = -1;
		}
	}

	int ans = 0, rem = 0;
	for (int i = 0; i < s.size(); i++) {
		if (s[i] == '?') {
			for (int dig = 0; dig < 10; dig++) {
