const int p = 13;

// 場合の数を格納
// i桁目までで剰余がj(0-12)であるときの場合の数
// 各桁において'?'の場合は0-9で走査して調べる
int dp[100005][15];

// i桁目の数をm(i)とする
// S = 10^(n-1)*m(1) + 10^(m-2)*m(2) + ... + 10^1*m(n-2) + 10^0*m(n-1)
// S%p = {(10^(n-1) % p)*(n(1) % p) + ... + (10^0 % p) * (m(n-1) % p)} % p
// 各桁の剰余が求まれば、その和を取れば全体の剰余は求まるので、桁ごとに分けてdp
int main(){
    string S;
    cin >> S;
    int n = S.length();

    int mul = 1;
    vector<int> m(n);       // (10のべき乗) % 13
    for(int i = n-1; i >= 0; --i){
        m[i] = mul;
        mul = (mul * 10) % p;
    }

    // dpテーブルの初期化
    dp[0][0] = 1;

    for(int i = 0; i < n; ++i){
        if(S[i] != '?'){        // 数が確定しているとき
            int temp = S[i] - '0';  // 今見ている桁の数字
            for(int j = 0; j < p; ++j){
                dp[i + 1][(j + m[i] * temp) % p] += dp[i][j];          // 剰余が(j + m[i]*temp) % 13になる
            }
        }
        else{               // 数が確定していないとき
            for(int N = 0; N <= 9; ++N){        // '?'に(0-9)を代入して剰余を計算
                for(int j = 0; j < p; ++j){
                    int id = (j + m[i] * N) % p;       // 更新するindex
                    dp[i + 1][id] = (dp[i + 1][id] + dp[i][j]) % mod;
                }
            }
        }
    }

    cout << dp[n][5] << endl;
}

