    for(ll i = 0; i < 10; i++) {
      ways = (ways + go(idx + 1, (rem + i * bigmod(10ll, idx)) % 13ll)) % mod;
    }
  } else {
    ways = (ways + go(idx + 1, (rem + (x[idx] - '0') * bigmod(10ll, idx)) % 13ll)) % mod;
  }
  return dp[idx][rem] = ways;
}

