    dp[0] = 1;
    LL base = 1;
    for (LL i = 0; i < T.size(); i++) {
        vector<LL> next(13, 0);
        if (T[i] != '?') {
            LL k = T[i] - '0';
            LL d = (k * base) % 13;
            for (LL j = 0; j < 13; j++) {
                next[(j + d) % 13] += dp[j];
                next[(j + d) % 13] %= mod;
            }
        } else {
            for (LL k = 0; k <= 9; k++) {
                for (LL j = 0; j < 13; j++) {
                    LL d = (k * base) % 13;
                    next[(j + d) % 13] += dp[j];
                    next[(j + d) % 13] %= mod;
                }
            }
        }
        dp = next;
        base *= 10;
        base %= 13;
    }

    cout << dp[5] % mod << endl;

    return 0;
}

