#include<bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MAX = 1e5 + 2;
const ll MOD = 1e9 + 7;

int main()
{
    string str;
    cin >> str;
    //cout << str << endl;

    // dp[i][j] ...i桁目まで決めた時に13で割った余りがjの数のパターン
    //              をMODで割ったもの(i = 0, 1, .... , str.size()-1 )
    int N = str.size();
    ll dp[N][13];
    for(int i = 0; i < N; ++i) {
        for(int j = 0; j < 13; ++j) dp[i][j] = 0;
    }

    ll digit = 1;
    // i = 0のとき、遷移の最初の状態を求める。
    if(str[N-1] != '?') {
        ll num = (ll)(str[N-1] - '0');
        dp[0][(num*digit)%13] = 1;
    }
    else {
        for(ll j = 0; j <= 9; ++j) 
            dp[0][(j*digit)%13] = 1;
    }

    for(int i = 1; i < N; ++i) {
        digit *= 10;
        digit %= 13;
        int i2 = N - i - 1;
        if(str[i2] != '?') {
            ll num = (ll)(str[i2] - '0');
            for(ll j = 0; j <= 12; ++j) {
                ll neo = (j + num*digit)%13;
                dp[i][neo] +=  dp[i-1][j];
                dp[i][neo] %= MOD;
            }
        }
        else {
            for(ll j = 0; j <= 9; ++j) {
                for(ll k = 0; k <= 12; ++k) {
                    ll neo = (k + j*digit)%13;
                    dp[i][neo] += dp[i-1][k];
                    dp[i][neo] %= MOD;
                }
            }
        }
    }

    cout << dp[N-1][5] << endl;
    return 0;
}

