        else{
            int k = (int)(S[i] - '0');
            for (int j = 0; j < N; j++){
                nextDP[(k * mul + j) % N] += dp[j];
                nextDP[(k * mul + j) % N] %= mod;                
            }
        }

        mul *= 10;
        mul %= N;
        dp = nextDP;
    }

    cout << dp[5] << endl;
    return 0;
}

