  cin.tie(0);
  ios::sync_with_stdio(false);

  string s;
  cin >> s;
  int n = s.size();
  ll r,d=1;
  vector<vector<int>> dp(n+1,vector<int>(13,0));
  reverse(s.begin(),s.end());
  dp[0][0] = 1;
  for(int i=0; i<n; i++){
    if(s[i]=='?'){
      for(int j=0; j<=9; j++){
        r = (d * j) % 13;
        for(int k=0; k<13; k++){
          dp[i+1][(k+r)%13] += dp[i][k];
          dp[i+1][(k+r)%13] %= MOD;
        }
      }
    }else{
      r = (d * (s[i]-'0')) % 13;
      for(int j=0; j<13; j++){
        dp[i+1][(j+r)%13] = dp[i][j];
        dp[i+1][(j+r)%13] %= MOD;
      }
    }
    d *= 10;
    d %= 13;
  }
  cout << dp[n][5];
  return 0;
}

