template<class T, class U> ostream &operator<<(ostream &os, pair<T, U> p) {
    os << p.fi << " " << p.se;
    return os;
}
ostream &operator<<(ostream &os, T p) {
    os << p.f << " " << p.s << " " << p.t;
    return os;
}
ostream &operator<<(ostream &os, F p) {
    os << p.a << " " << p.b << " " << p.c << " " << p.d;
    return os;
}
template<typename T> ostream &operator<<(ostream &os, vector<T> &vec_) {
    for (ll i = 0; i < vec_.size(); ++i)os << vec_[i] << (i + 1 == vec_.size() ? "" : " ");
    return os;
}

template<typename T> ostream &operator<<(ostream &os, vector<vector<T>> &vec_) {
    for (ll i = 0; i < vec_.size(); ++i) {
        for (ll j = 0; j < vec_[i].size(); ++j) { os << vec_[i][j] << " "; }
        os << endl;
    }
    return os;
}
