/*

274 % 13
4 % 13 = 4
70 % 13 = 5
200 % 13 = 5
*/

int main() {

	string s;
	cin >> s;

	const int N = 13;

	/*
		後ろから解くアルゴリズム
		1?2?3 -> 0 -> 3 -> ?3 -> 2?3 -> ?2?3 -> 1?2?3

	*/

	vector<ll> dp(N);

	int mul = 1;//桁を保持
	ll const mod = 1'000'000'007;
	dp[0] = 1;

	for (int i = s.length() - 1; i >= 0; i--) {
		char c = s[i];

		vector<ll> nextDP(N);

		if (c == '?') {
			for (int k = 0; k < 10; k++) {//1~9を試す
				for (int j = 0; j < N; j++) {
					nextDP[(k * mul + j) % N] += dp[j];
					nextDP[(k * mul + j) % N] %= mod;
				}
			}

		}
		else {
			int k = (int)(s[i] - '0');//文字を数字に変換
			for (int j = 0; j < N; j++) {
				nextDP[(k * mul + j) % N] += dp[j];
				nextDP[(k * mul + j) % N] %= mod;
			}
		}

		mul *= 10;//次の桁を調べる
		mul %= N;

		dp = nextDP;//更新

	}

	cout << dp[5] << endl;

	return 0;

}

