const long M = 1000000007;
int main(){
  string S;
  cin >> S;
  int N = S.size();
  long a = 0;
  long dm = 1;
  for(int i=0; i<N; i++){
    char &si = S[N-1-i];
    if(si!='?'){
      a = (a+(dm*(si-'0')))%13;
    }
    dm = (dm*10)%13;
  }
  vector<long> dp(13);
  dp[a]=1;
  dm = 1;
  for(int i=0; i<N; i++){
    auto &si = S[N-1-i];
    if(si=='?'){
      vector<long> ndp(13);
      for(int j=0; j<13; j++){
        for(int k=0; k<10; k++){
          int l = (j+(dm*k))%13;
          ndp[l] = (ndp[l]+dp[j]) % M;
        }
      }
      dp = move(ndp);
    }
    dm = (dm*10)%13;
  }
  cout << dp[5] << endl;
  return 0;
}

