#define mod 1000000007

string s;
int dp[100009][13];

int solve(int idx, int sum) {
	// cout<<idx<<" "<<sum<<endl;
	if(idx == s.length())
		return sum == 5;

	if(dp[idx][sum] != -1) 
		return dp[idx][sum];


	int sm = sum;
	int ans = 0;

	sum *= 10;
	if(s[idx] != '?') {
		sum += (s[idx] - '0');
		sum %= 13;
		ans += solve(idx + 1, sum);
		ans %= mod;
	} else {
		for(int i = 0; i <= 9; i++){
			int ssum = sum;
			ssum += i;
			ssum %= 13;
			ans += solve(idx + 1, ssum);
			ans %= mod;
		}
	}

	return dp[idx][sm] = ans%mod;
}


