  string S = "";
  cin >> S;

  int dp[13] = {};
  dp[0] = 1;
  int mod = 1000000007;
  int d = 1;
  for (int i = S.length() - 1; i >= 0; i--)
  {
    int dp2[13] = {};
    char c = S[i];
    if (c == '?')
    {
      for (int n = 0; n <= 9; n++)
      {
        for (int m = 0; m <= 12; m++)
        {
          dp2[(n * d + m) % 13] += dp[m];
          dp2[(n * d + m) % 13] %= mod;
        }
      }
    }
    else
    {
      int k = c - '0';
      for (int m = 0; m <= 12; m++)
      {
        dp2[(k * d + m) % 13] += dp[m];
        dp2[(k * d + m) % 13] %= mod;
      }
    }
    for (int l = 0; l < 13; l++)
    {
      dp[l] = dp2[l];
    }
    d *= 10;
    d %= 13;
  }

  cout << dp[5] << endl;
  return 0;
}

