    int n = (int) s.size();
    vector<vector<long long>> count_mod(n+1, vector<long long>(13, 0));
    count_mod[n][0] = 1;
    int multiplier = 1;
    for (int i = n-1; i >= 0; --i) {
        vector<int> digits;
        if (s[i] == '?') {
            for (int k = 0; k < 10; ++k) {
                digits.push_back((multiplier * k) % 13);
            }
        } else {
            digits.push_back(((s[i] - '0') * multiplier) % 13);
        }
        for (int k = 0; k < 13; ++k) {
            for (int digit : digits) {
                count_mod[i][k] = (count_mod[i][k] + count_mod[i+1][(k + 13 - digit) % 13]) % prime;
            }
        }
        multiplier = (multiplier * 10) % 13;
    }
    cout << count_mod[0][5] << endl;
    return 0;
}

