    const int N = 13;

    //dp[k] -> 13で割った余りがkのパターン
    std::vector<long>  dp(N);
    dp[0] = 1;


    //後ろから解くアルゴリズム
    // 1?2?3    0 -> 3 -> ?3 -> 2?3 -> ...
    long mod = 1000000007;

    int mul =1;
    for (int i = 0; i < S.size(); ++i ){

        std::vector<long>  nextDP(N);

        char c = S[i];
        if (c == '?'){
            for(int k =0; k< 10; k++){
                for(int j=0; j < N; j++){
                    nextDP[(k * mul + j) % N] += dp[j];
                    nextDP[(k * mul + j) % N] %= mod;
                }
            }
        }
        else{
            int k = (int)(S[i] - '0');
            for (int j = 0; j < N; j++){
                nextDP[(k * mul + j) % N] += dp[j];
                nextDP[(k * mul + j) % N] %= mod;                
            }
        }

        mul *= 10;
        mul %= N;
        dp = nextDP;
    }

    cout << dp[5] << endl;
    return 0;
}

