string s;

int dp[maxn][13];

int solve(int idx, int rem)
{
	if(idx == -1)
		return rem % 13 == 5;

	if(dp[idx][rem] != -1)
		return dp[idx][rem];

	int res = 0;
	if(s[idx] != '?')
	{
		res += solve(idx-1, ( rem*10 % mod + (s[idx] - '0')) % 13 );
		res %= mod;
	}
	else
	{
		for(int i=0; i<=9; i++)
		{
			res += solve(idx-1, (rem*10 % mod + i) % 13);
			res %= mod;
		}
	}
	dp[idx][rem] = res;
	return res;
}

signed main()
{
