using namespace std;
typedef long long ll;
int main() {
  string S;

  cin >> S;

  ll N = S.length();

  ll dp[N][13];

  if (S[N - 1] == '?') {
    REP(i, 13) {
      if (i <= 10) {
        dp[N - 1][i] = 1;
      } else {
        dp[N - 1][i] = 0;
      }
    }
  } else {
    REP(i, 13) {
      if ((char)(i) == S[N - 1]) {
        dp[N - 1][i] = 1;
      } else {
        dp[N - 1][i] = 0;
      }
    }
  }

  ll digit = 1;

  FORR(i, 1, N - 1) {
    if (S[i] != '?') {
      ll num = (ll)(S[i]) * digit;
      REP(j, 13) { dp[i - 1][(j + num) % 13] = dp[i][j]; }
    } else {
      REP(j, 13) {
        REP(num, 10) {
          num *= digit;
          dp[i - 1][j + (num) % 13] = dp[i][j];
        }
      }
    }
    digit *= 10;
  }
  ll ans = 0;
  REP(i, N - 1) { ans += dp[i][5] % (ll)(1e9 + 7); }
  cout << ans;
  return 0;
}

