using namespace std;

static long mod = 1e9 + 7;
static long n = 13;

// S: 数字(0～9)か'?'からなる文字列
string S;
void solve();
void sub(int k, vector<long>& dp, vector<long>& next_dp, int& mul);

int main() {
  cin >> S;
  solve();
}

// Sの?を数字に置き換えてできる整数のうち13で割って5あまる数を求める
void solve() {
  // ある数の mod 13
  // 数え上げなので、初期値は0
  vector<long> dp(n);

  // Sが０のとき, mod13は0になるため dp[0]を１つ増やす
  dp[0]++;

  int mul = 1;
  // 一番右の桁から数えていく
  for (int i = S.size() - 1; i >= 0; i--) {
    vector<long> next_dp(n);
    char c = S[i];
    if (c == '?') {
      // kがとりうる値 0から9まですべての場合を追加する
      for (int k = 0; k < 10; k++) {
        sub(k, dp, next_dp, mul);
      }
    } else {
      int k = int(S[i]);
      sub(k, dp, next_dp, mul);
    }
    dp = next_dp;

    mul *= 10;
    mul %= n;
  }
  cout << dp[5] << endl;
}

void sub(int k, vector<long>& dp, vector<long>& next_dp, int& mul) {
  // あまりが 0 から 12のそれぞれの場合を更新していく
  for (int j = 0; j < n; j++) {
    next_dp[(k * mul + j) % n] += dp[j];
    next_dp[(k * mul + j) % n] %= mod;
  }
};

