typedef long long ll;
const ll mod = 1e9+7;

ll mpow(ll x,ll n){
    ll res = 1;
    while(n != 0){
        if(n&1) res = res*x % 13;
        x = x*x % 13;
        n = n >> 1; 
    }
    return res;
}

ll solve(string &s,int k = 0,ll status = 0){
    // status : equal to limit? 1 : 0
    static ll dp[100001][13];
    if(!k) memset(dp,-1,sizeof(dp));

    if(k==s.size()){
        if(status==5) return 1;
        else          return 0;
    }

    ll &res = dp[k][status];
    if(res!=-1) return res;
    else res = 0;

    if(s[k]!='?') res = (res+solve(s,k+1,(status+(ll)(s[k]-'0')*mpow(10,s.size()-1-k))%13))%mod;
    else for(int i = 0;i <= 9;i ++){
        ll cnt;
        cnt = solve(s,k+1,(status+i*mpow(10,s.size()-1-k))%13)%mod;
        res = (res+cnt)%mod;
    }
    return res;
}

int main(){
    string s;
    cin >> s;
    cout << solve(s) << endl;
    return 0;
}

