int dp[100005][15];

ll gcd(ll a, ll b){
    if(b == 0)      return a;
    if(a < b)       swap(a, b);

    return gcd(b, a % b);
}

int main(){
    string S;
    cin >> S;
    int n = S.length();

    int mul = 1;
    vector<int> m(n);       // (10のべき乗)%13
    for(int i = n-1; i >= 0; --i){
        m[i] = mul;
        mul = (mul * 10) % 13;
    }

    // dpテーブルの初期化
    for(int i = 0; i <= n; ++i){
        for(int j = 0; j <= 12; ++j){
            dp[i][j] = INF;
        }
    }
    dp[0][0] = 1;

    for(int i = 0; i < n; ++i){
        if(S[i] != '?'){        // 数が確定しているとき
            int temp = S[i] - '0';  // 今見ている桁の数字
            for(int j = 0; j <= 12; ++j){
                if(dp[i][j] == INF)     continue;       // ありえないときはcontinue

                dp[i + 1][(j + m[i] * temp) % 13] = dp[i][j];          // 剰余が(j + m[i]*temp) % 13になる
            }
        }
        else{               // 数が確定していないとき
            for(int N = 0; N <= 9; ++N){        // 0-9を代入して剰余を計算
                for(int j = 0; j <= 12; ++j){
                    if(dp[i][j] == INF)     continue;

                    int id = (j + m[i] * N) % 13;       // 更新するindex
                    if(dp[i + 1][id] == INF){
                        dp[i + 1][id] = dp[i][j];
                    }
                    else{
                        dp[i + 1][id] = (dp[i + 1][id] + dp[i][j]) % mod;
                    }
                }
            }
        }
    }

