		surplusV[i] = i;
	}
	// 初期化
	{
		if (s[s.size() - 1] == '?') {
			for (int num = 0; num < 10; ++num) {
				int surplus = num % 13;
				dp[0][surplus] = 1;
			}
		}
		else {
			int num = s[s.size() - 1] - '0';
			int surplus = num % 13;
			dp[0][surplus] = 1;
		}
	}

	int count = 1;
	for (int i = static_cast<int>(s.size()) - 2; 0 <= i; --i) {
		{
			int temp = surplusV[1];
