ll memo[20];
void make_memo(ll base, ll mo){
    memo[0] = 1;
    memo[1] = base % mo;
    FOR(i, 2, 20){
        memo[i] = (memo[i-1]*memo[i-1])%mo;
    }
}

// 2進数にする
vector<ll> to_binary(ll a){
    vector<ll> A;
    if(a==0){
        A.push_back(0);
        return A;
    }
    while(a){
        ll r = a%2;
        a/=2;
        A.push_back(r);
    }
    return A;
}

ll my_pow(ll a, ll n, ll mo){ // ll_powと引数を似せておく
    auto binary = to_binary(n);
    ll L = binary.size();
    ll mul = 1;
    FOR(i, 0, L){
        if(binary[i]){
            mul *= memo[i+1];
            mul %= mo;
        }
    }
    return mul;
}

