ll solve(string S){
    ll sum = 0;
    int tm[6] = {1,10,9,12,3,4};
    vector<int> mis;

    rep(i,sz(S)){
        if(S[i] == '?') mis.pb(tm[(sz(S)-i-1)%6]);
        else sum += (S[i]-'0')*tm[(sz(S)-i-1)%6], sum %= 13;
    }

