        DP[i][j] = DP[i-1][j];
        rep1(k,9){
            DP[i][j] += DP[i-1][((j-k*mis[i-1])%13+13)%13] %MOD;
        }
        DP[i][j] %= MOD;
    }

    return DP[sz(mis)][(5+13-sum)%13]%MOD;
}


