inline ll add(ll a,ll b){
  return (a % mod + b % mod) % mod;
}

inline ll sub(ll a,ll b){
  return (a % mod - b % mod + mod) % mod;
}

inline ll mul(ll a,ll b){
  return(a % mod * b % mod) % mod;
}

inline ll modexpo(ll a,ll b){
  ll res = 1;
  while(b > 0){
    if(b & 1)
      res = (res % mod * a % mod) % mod;
    a = (a % mod * a % mod) % mod;
    b >>= 1;
  }return res;
}

inline ll modinv_Fermat(ll a){
  return modexpo(a,mod - 2);
}

inline ll divide(ll a,ll b){
  return(a%mod * modexpo(b,mod - 2)%mod)%mod;
}

const ll N = 1e5 + 5;

ll dp[N][13];

ll solve(ll idx, ll mod_sum, string s, ll n){
  if(idx == n){
    return (mod_sum == 5);
  }
  ll &ans = dp[idx][mod_sum];

  if(~ans)
    return ans;
  ans = 0;
  if(s[idx] == '?'){
    for(ll i = 0; i < 10; i++){
      ans = add(ans, solve(idx + 1, (10 * mod_sum + i) % 13, s, n));
    }
  }else{
    ans = solve(idx + 1, (10 * mod_sum + (s[idx] - '0')) % 13, s, n);
  }
  return ans;
}

