ll RepeatSquaring(ll N, ull P, ull mod){
	if(P == 0 || N == 1) return 1;
	if(N == -1) return P & 1 ? -1 : 1;
	if(!(P & 1)){
		ll t = RepeatSquaring(N, P >> 1, mod);
		return t*t %mod;
	}
	return N*RepeatSquaring(N, P - 1, mod) % mod;
}

