    string S;
    cin >> S;
    int len = S.size();
    reverse(ALL(S));

    REP(i, 13) { dp[0][i] = 0; }

    if (S[0] == '?') {
        REP(i, 10) { dp[0][i] = 1; }
    } else {
        int index = S[0] - '0';
        dp[0][index] = 1;
    }

    int num = 1;
    FOR(i, 1, len) {
        // cout << i << ":" << S[i] << endl;

        num *= 10;
        num %= 13;

        if (S[i] == '?') {
            REP(j, 10) {
                REP(k, 13) {
                    int index = (k + j * num) % 13;
                    dp[i][index] += dp[i - 1][k];
                    dp[i][index] %= MOD;
                }
            }
        } else {
            REP(k, 13) {
                int index = (k + (S[i] - '0') * num) % 13;
                dp[i][index] += dp[i - 1][k];
                dp[i][index] %= MOD;
            }
        }
    }

    cout << dp[len - 1][5] << endl;

    return 0;
}

