const long long ILF = 1e18;
const long long MOD = 1e9 + 7;
using namespace std;
typedef long long ll;
int main() {
  string S;

  cin >> S;

  ll L = S.length();

  ll N = 13;

  ll dp[L][N];

  REP(i, L) {
    REP(j, N) { dp[i][j] = 0; }
  }
  if (S[L - 1] == '?') {
    REP(i, 10) { dp[L - 1][i] = 1; }
  } else {
    ll num = (ll)(S[L - 1] - '0');
    dp[L - 1][num] = 1;
  }

  ll digit = 10;

  FORR(i, L - 1, 1) {
    if (S[i - 1] == '?') {
      REP(j, N) {
        REP(k, 10) {
          dp[i - 1][(j + (k * digit) % N) % N] += dp[i][j];
          dp[i - 1][(j + (k * digit) % N) % N] %= MOD;
        }
      }
    } else {
      ll k = (ll)(S[i - 1] - '0');
      REP(j, N) {
        dp[i - 1][(j + (k * digit) % N) % N] += dp[i][j];
        dp[i - 1][(j + (k * digit) % N) % N] %= MOD;
      }
    }

    digit *= 10;
    digit %= N;
  }
  cout << dp[0][5];
  return 0;
}

