    auto ch = [](const char c) { return c - '0'; };
    ll sz = SIZE(s);
    vc<vc<mint>> dp(2, vc<mint>(13, 0)); // dp[i][j] := 下から i 桁目まで見て 13 で割ったあまりが j: [0, 12] になる組み合わせ数
    dp[0][0] = 1;
    ll coefmod13 = 1;
    REPM(i, 1, sz)
    {
        fill(ALL(dp[i % 2]), 0);
        if (s[sz - i] == hatena)
        {
            // ? に 0〜9 を入れたそれぞれの場合を考える
            REPM(j, 0, 12)
            {
                REPM(digit, 0, 9)
                {
                    // dump(i, (digit * coefmod13 + j), j, digit);
                    dp[i % 2][(digit * coefmod13 + j) % 13] += dp[(i - 1) % 2][j];
                }
                // dump(j, dp[i % 2]);
            }
        }
        else
        {
            ll digit = ch(s[sz - i]);
            REPM(j, 0, 12)
            {
                dp[i % 2][(digit * coefmod13 + j) % 13] = dp[(i - 1) % 2][j];
            }
        }
        coefmod13 *= 10;
        coefmod13 %= 13;
    }
    // dump(dp);
