const int MOD = 1000000007;
long long int POW(int n,int k,int m){
	long long int r;
	if(k==0)return 1;
	r=POW(n,k/2,m)%m;
	r=(r*r)%m;
	if(k%2)r=(n*r)%m;
	return r;
}
int main(){
	int N,ans[100000][13]={0},n,sur,pre;
	string S;
	cin>>S;
	N=S.length();
	for(int i=0;i<N;i++){
		sur=POW(10,N-i-1,13);
		if(S[i]=='?'){
			if(i>=1){
				for(int j=0;j<13;j++){
					for(int k=0;k<10;k++){
						pre=(sur*k)%13;
						ans[i][(j+pre)%13]+=ans[i-1][j];
						ans[i][(j+pre)%13]%=MOD;
					}
				}
			}else{
				for(int k=0;k<10;k++)ans[i][(sur*k)%13]+=1;
			}
		}else{
			n=S[i]-'0';
			sur=(sur*n)%13;
			if(i>=1){
				for(int j=0;j<13;j++)ans[i][(j+sur)%13]=ans[i-1][j];
			}else{
				ans[i][sur]=1;
			}
		}
	}
	cout<<ans[N-1][5];
	return 0;
}

