const int MOD = 1e9 + 7;
int dp[110000][13];// 桁数,余り

int main(){
  string S;
  cin >> S;
  int len = S.size();//桁数
  reverse(All(S));//1桁目から見る
  if(S[0] == '?') {
    for(int i=0;i<10;i++){
      dp[0][i] = 1;//余りの値のパターンは0-9まである
    }
  }else{//1桁目が決まっている
    int index = S[0] - '0';//文字をint型に変換
    dp[0][index] = 1;
  }
  int num = 1;//桁数
  for(int i=1;i<len;i++){
    num*=10;
    num%=13;//毎回13で割った余りにしておく
    if(S[i] == '?'){
      for(int j=0;j<10;j++){
        for(int k=0;k<13;k++){
          int index = (k+j*num) % 13;//余り
          dp[i][index] += dp[i-1][k];//更新式
          dp[i][index] %= MOD;//剰余に変換
        }
      }
    }else{
      //数が決まっている
      for(int k=0;k<13;k++){
        int j=(S[i] - '0');
        int index = (k+j * num) % 13;
        dp[i][index] += dp[i-1][k];
        dp[i][index] %= MOD;
      }
    }
  }
  cout << dp[len-1][5] << endl;
  return 0;
}

