void keinazo(int n,int p){
    int i,j;

    for(i=0;i<10;i++){
        for(j=0;j<13;j++){
            dp[(j+p*i)%13][n]+=dp[j][n-1];
        }
    }
    for(i=0;i<13;i++){
        dp[i][n]%=1000000007;
    }

    return;
}

void keikazu(int n,int p,int base){
    int i;
    for(i=0;i<13;i++){
        dp[(i+p*base)%13][n]+=dp[i][n-1];
    }
    return;
}

