int modpow(int n, int m){
	if(m == 0) return 1;
	int res = 1, tmp = n;
	while(m){
		if(m & 1) res = res * tmp % 13;
		tmp = tmp * tmp % 13;
		m >>= 1;
	}
	return res;
}

