// 実行メイン
int
fMain(
)
{
	int i, j, k;

	// 文字列 - 取得
	fgets(sc1Str, sizeof(sc1Str), szpFpI);

	// パターン数 - 初期値
	si2PCnt[0][0] = 1;

	// 桁数でループ
	for (i = 0; ; i++) {

		// 対象文字
		int liNum;
		if ('0' <= sc1Str[i] && sc1Str[i] <= '9') {
			liNum = sc1Str[i] - '0';
		}
		else if (sc1Str[i] == '?') {
			liNum = -1;
		}
		else {
			break;
		}

		// 数字の種類でループ
		for (j = 0; j < 10; j++) {

			// 対象文字
			if (liNum >= 0 && liNum != j) {
				continue;
			}

			// 余りの種類でループ
			for (k = 0; k < D_DIV; k++) {

				// 次の余り - 取得
				int liNext;
				switch (k) {
					case 0:		liNext = 0;		break;
					case 1:		liNext = 10;	break;
					case 2:		liNext = 7;		break;
					case 3:		liNext = 4;		break;
					case 4:		liNext = 1;		break;
					case 5:		liNext = 11;	break;
					case 6:		liNext = 8;		break;
					case 7:		liNext = 5;		break;
					case 8:		liNext = 2;		break;
					case 9:		liNext = 12;	break;
					case 10:	liNext = 9;		break;
					case 11:	liNext = 6;		break;
					case 12:	liNext = 3;		break;
				}
				liNext = (liNext + j) % D_DIV;

				// パターン数 - 加算
				si2PCnt[i + 1][liNext] = (si2PCnt[i + 1][liNext] + si2PCnt[i][k]) % D_MOD;
			}
		}
	}

	return si2PCnt[i][5];
}

