#define ALLOC(size,type) ((type*)calloc((size),sizeof(type)))

void run (void) {
  char *s = ALLOC (100000 + 1, char);
  scanf ("%s", s);
  const i32 p = 13;
  i64 *dp = ALLOC (p, i64);
  i64 *next = ALLOC (p, i64);
  dp[0] = 1;
  const i32 mod = 1000000007;
  for (i32 i = 0; s[i] != '\0'; ++i) {
    memset (next, 0, sizeof (i64) * p);
    if (s[i] != '?') {
      i32 d = s[i] - '0';
