        next[(10 * j + d) % p] += dp[j];
      }
    } else {
      for (i32 d = 0; d < 10; ++d) {
        for (i32 j = 0; j < p; ++j) {
          next[(10 * j + d) % p] += dp[j];
        }
      }
    }
    for (i32 j = 0; j < p; ++j) {
      dp[j] = next[j] % mod;
    }
  }
  printf ("%" PRIi64 "\n", dp[5]);
}

