int memo[114514][13];

int murakawarie(int idx, int amari) {
	int subete_no_nswer = 0; /* ∀NSWER */
	if (S[idx] == '\0') return amari == 5;
	if (memo[idx][amari]) return ~memo[idx][amari];
	if (S[idx] == '?') {
		int i;
		for (i = 0; i <= 9; i++) {
			subete_no_nswer = add(subete_no_nswer, murakawarie(idx + 1, (amari * 10 + i) % 13));
