import java.util.*

fun calc(left: String, right: String): List<String> {
    val idx = right.indexOf('?')
    if (idx == -1) {
        return listOf(left + right)
    }
    val str = right.substring(0, idx)
    val newRight = right.substring(idx + 1)
    val list = LinkedList<String>()
    repeat(10) {
        list.addAll(calc(left + str, it.toString() + newRight))
    }
    return list
}

fun main(vararg args: String) {
    val scanner = Scanner(System.`in`)
    val s = scanner.next()
    val list = calc("", s)
    list.filter {
        it.toInt() % 13 == 5
    }.let {
        println(it.size)
    }
}

