const val MOD = 1000000007
fun solve(S: String) {
    val n = S.length
    // dp[mod][i] = 左からi桁まで見て、あまりがmodであるものの数
    val dp = Array(13) { LongArray(n + 1) }
    dp[0][0] = 1L
    for (i in 1..n) {
        for (mod in 0..12) {
            val digits = when (S[i - 1]) {
                '?' -> (0..9).asSequence()
                else -> sequenceOf(S[i - 1] - '0')
            }
            for (digit in digits) {
                val nextMod = Math.floorMod(mod * 10 + digit, 13).toInt()
                dp[nextMod][i] += dp[mod][i - 1]
                dp[nextMod][i] = dp[nextMod][i] % MOD
            }
        }
    }
    // println(dp.contentDeepToString())
    println(dp[5][n])
    return
}

