                for (k in 0 until 13) {
                    dp[i][(k + r) % 13] += dp[i - 1][k]
                    dp[i][(k + r) % 13] %= 1000000007L
                }
            }
        } else {
            val r = ((c.toLong() * mul) % 13L).toInt()

            for (k in 0 until 13) {
                dp[i][(k + r) % 13] = dp[i - 1][k]
            }
        }

        mul *= 10L
        mul %= 13
    }

    println(dp[s.length][5])
}

