val M = 1000000007L

fun co(n: Long): Co {
    return Co((n % M + M) % M)
}

fun main(args: Array<String>) {
    val s = readLine()!!
    val dp = Array(s.length + 1) {Array(13){co(0)}}
    dp[0][0] = co(1)
    for (i in 0 until s.length) {
        if (s[i] == '?') {
            for (j in 0 until 13) {
                for (d in 0 until 10) {
                    dp[i+1][(j * 10 + d) % 13] += dp[i][j]
                }
            }
        } else {
            val c = Character.getNumericValue(s[i])
            for (j in 0 until 13) {
                dp[i+1][(j * 10 + c) % 13] += dp[i][j]
            }
        }
    }
    println(dp[s.length][5].n)
}

data class Co(val n: Long) {
    inline operator fun plus(other: Co): Co {
        return co(n + other.n)
    }
    operator fun minus(other: Co): Co {
        return co(n - other.n)
    }
    operator fun times(other: Co): Co {
        return co(n * other.n)
    }
    operator fun div(other: Co): Co {
        return this * other.pow(M - 2)
    }
    fun pow(k_: Long): Co {
        var k = k_
        var a = this
        var res = co(1)
        while (k > 0) {
            if (k.and(1) == 1L) {
                res *= a
            }
            a *= a
            k = k.shr(1)
        }
        return res
    }
}

