				for(int mod_prev=0;mod_prev<13;mod_prev++)
				{
					int mod_pos=(mod_prev*10+num)%13;
					dp[i+1][mod_pos]+=dp[i][mod_prev];
					dp[i+1][mod_pos]%=1000000007;

				}
			}
		}
		System.out.println(dp[n][5]);


	}
}

