	private long rec(int N, char[] A, int k, int sum, boolean tight) {

		if (dpbool[k][sum]) {
			//System.out.println("k:" + k + " ,sum:" + sum);
			return dp[k][sum];
		}
		if (k == N) {
			//System.out.println(sum);
			if (sum % 13 == 5) {
				//System.out.println(sum);
				return 1;
			} else {
				return 0;
			}
		}

		long res = 0;

		int x;
		if (A[k] == '?') {
			x = 9;
		} else {
			x = A[k] - '0';
		}

		if (A[k] == '?') {
			for (int i = 0; i <= 9; i++) {
				StringBuilder buff = new StringBuilder();
				buff.append(sum);
				buff.append(i);
				int sum13 = Integer.valueOf(buff.toString()) % 13;
				if (tight && i == x) {
					res += rec(N, A, k + 1, sum13, true);
				} else {
					res += rec(N, A, k + 1, sum13, false);
				}
				res %= MOD;
				dp[k][sum] = res;
				dpbool[k][sum] = true;
			}
		} else {
			StringBuilder buff = new StringBuilder();
			buff.append(sum);
			buff.append(x);
			int sum13 = Integer.valueOf(buff.toString()) % 13;
			res += rec(N, A, k + 1, sum13, true);
			res %= MOD;
			dp[k][sum] = res;
			dpbool[k][sum] = true;
		}

		return res;
	}

