import java.io.*;
import java.util.*;

public class Main {
  private static final long M = 1_000_000_007;

  private static long solve(char[] cs) {
    long[] mods = new long[13];
    Arrays.fill(mods, 0);
    mods[0] = 1;

    for (char c : cs) {
      long[] nextMods = new long[13];
      for (int i = 0; i < 13; i++) {
        if (c == '?') {
          for (int j = 0; j < 10; j++) {
            int nextI = (10 * i + j) % 13;
            nextMods[nextI] += mods[i];
            nextMods[nextI] %= M;
          }
        } else {
          int nextI = (10 * i + (c - '0')) % 13;
          nextMods[nextI] += mods[i];
          nextMods[nextI] %= M;
        }
      }
      mods = nextMods;
    }
    return mods[5];
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    char[] cs = reader.next().toCharArray();
    out.println(solve(cs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

