	private long rec(int N, char[] A, int k, int sum, boolean tight) {

		int t = tight ? 0 : 1;
		if (dpbool[k][t][sum]) {
			return dp[k][t][sum];
		}
		if (k == N) {
			//System.out.println(sum);
			if (sum % 13 == 5) {
				//System.out.println(sum);
				return 1;
			} else {
				return 0;
			}
		}

		long res = 0;

		int x;
		if (A[k] == '?') {
			x = 9;
		} else {
			x = A[k] - '0';
		}

		if (A[k] == '?') {
			for (int i = 0; i <= 9; i++) {
				String sums = String.valueOf(sum) + String.valueOf(i);
				int sum13 = Integer.valueOf(sums) % 13;
				if (tight && i == x) {
					res += rec(N, A, k + 1, sum13, true);
				} else {
					res += rec(N, A, k + 1, sum13, false);
				}
				res %= MOD;
				dp[k][t][sum] = res;
				dpbool[k][t][sum] = true;
			}
		} else {
			String sums = String.valueOf(sum) + String.valueOf(x);
			int sum13 = Integer.valueOf(sums) % 13;
			res += rec(N, A, k + 1, sum13, true);
			res %= MOD;
			dp[k][t][sum] = res;
			dpbool[k][t][sum] = true;
		}

		return res;
	}

