                    if (s.charAt(i) == '?') {
                        for (int k = 0; k < 10; k++) {
                            int dest = (10 * j + k) % 13;
                            dp[dest][i + 1] += dp[j][i];
                            dp[dest][i + 1] %= MOD;
                        }
                    } else {
                        int dig = s.charAt(i) - '0';
                        dp[(10 * j + dig) % 13][i + 1] = dp[j][i];
                    }
                }
            }

            out.ans(dp[5][n]).ln();
