	private long rec(String S, int N, int k, int sum, boolean tight) {

		if (dpbool[k][sum]) {
			//System.out.println("k:" + k + " ,sum:" + sum);
			return dp[k][sum];
		}
		if (k == N) {
			//System.out.println(sum);
			if (sum % 13 == 5) {
				//System.out.println(sum);
				return 1;
			} else {
				return 0;
			}
