		long res = 0;

		int x;
		if (S.charAt(k) == '?') {
			x = 9;
		} else {
			x = S.charAt(k) - '0';
		}

		if (S.charAt(k) == '?') {
			for (int i = 0; i <= 9; i++) {

				if (tight && i == x) {
					res += rec(S, N, k + 1, (sum * 10 + i) % 13, true);
				} else {
					res += rec(S, N, k + 1, (sum * 10 + i) % 13, false);
				}
				res %= MOD;
				dp[k][sum] = res;
				dpbool[k][sum] = true;
			}
		} else {
			res += rec(S, N, k + 1, (sum * 10 + x) % 13, true);
			res %= MOD;
			dp[k][sum] = res;
			dpbool[k][sum] = true;
		}

		return res;
	}

