/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author caoash
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DDigitsParade solver = new DDigitsParade();
        solver.solve(1, in, out);
        out.close();
    }

    static class DDigitsParade {
        public void solve(int testNumber, FastScanner br, PrintWriter pw) {
            long MOD = (long) 1e9 + 7;
            char[] in = br.nextString().toCharArray();
            long[][] cnt = new long[in.length][13];
            int place = 0;
            for (int i = in.length - 1; i >= 0; i--) {
                if (place == 0) {
                    if (in[i] == '?') {
                        for (int dig = 0; dig <= 9; dig++) {
                            cnt[place][(((int) (Algorithms.powM(10, place, 13)) * dig)) % 13]++;
                        }
                    } else {
                        cnt[place][((int) (Algorithms.powM(10, place, 13) * (in[i] - '0'))) % 13]++;
                    }
                } else {
                    if (in[i] == '?') {
                        for (int j = 0; j < 13; j++) {
                            for (int dig = 0; dig <= 9; dig++) {
                                cnt[place][(j + ((int) (Algorithms.powM(10, place, 13)) * dig)) % 13] += cnt[place - 1][j];
                                cnt[place][(j + ((int) (Algorithms.powM(10, place, 13)) * dig)) % 13] %= MOD;
                            }
                        }
                    } else {
                        for (int j = 0; j < 13; j++) {
                            cnt[place][(j + ((int) (Algorithms.powM(10, place, 13)) * (in[i] - '0'))) % 13] += cnt[place - 1][j];
                            cnt[place][(j + ((int) (Algorithms.powM(10, place, 13)) * (in[i] - '0'))) % 13] %= MOD;
                        }
                    }
                }
                ++place;
            }

            pw.println(cnt[in.length - 1][5] % MOD);
            pw.close();
        }

    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastScanner.SpaceCharFilter filter;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class Algorithms {
        public static long mod(long n, long m) {
            while (n >= m) {
                n -= m;
            }
            return n;
        }

        public static long powM(int a, int b, int m) {
            a %= m;
            long res = 1;
            while (b > 0) {
                if ((b & 1) > 0)
                    res = mod(res * a, m);
                a = a * a % m;
                b >>= 1;
            }
            return res;
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;

public class Main {
	public static void main(String[] args) {
		FS reader = new FS();
		// write reader
		String s = reader.next();
		solver(s);
	}

	public static void solver(String str) {
		// write logic
        int len = str.length();
        long mod = (int)Math.pow(10,9)+7;
        long[][] dp = new long[(int)(Math.pow(10, 5))+1][13];
        for(int i=0; i<13; i++) {
            dp[0][i] = 0;
        }
        dp[0][0] = 1;
        int cnt = 0;

        for(int i=0; i<len; i++) {
            char s = str.charAt(i);
            if(s == '?') {
                long total = 1;
                for(int t=0; t<cnt; t++) {
                    total = (total * 10) % mod;
                }
                for(int j=0; j<13; j++) {
                    dp[i+1][j] = (total+mod*10-dp[i][4-(int)((j+2)/3)]-dp[i][8-(int)((j+1)/3)]-dp[i][12-(int)(j/3)])%mod;
                }
                cnt++;
            } else {
                for(int j=0; j<13; j++) {
                    dp[i+1][j] = 0;
                }
                for(int j=0; j<13; j++) {
                    dp[i+1][(j*10+Character.getNumericValue(s))%13] += dp[i][j];
                }
            }
        }
        System.out.println(dp[len][5]%mod);
    }

	// Read Class
	static class FS {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;
		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() { return hasNextByte() ? buffer[ptr++] : -1;}
		private boolean isPrintableChar(int c) {return 33 <= c && c <= 126;}
		private void skipUnprintable() {while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}

		public boolean hasNext() { skipUnprintable(); return hasNextByte();}
		public String next() {
			if (!hasNext()) throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while(isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}
		public int nextInt() {
			return (int)nextLong();
		}
		public long nextLong() {
			if (!hasNext()) throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while(true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if(b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}
	}
}

