		int base = 1;
		for(int i = c.length-1; i >= 0; i--)
		{
			if(c[i] == '?')
			{
				at = Arrays.copyOf(a, 13);
				Arrays.fill(a, 0);
				for(int j = 0; j < 10; j++)
				{
					int tmp = (j*base)%13;
					for(int k = 0; k < 13; k++)
					{
						a[(k+tmp)%13] += at[k];
						a[(k+tmp)%13] = a[(k+tmp)%13] % 1000000007;
					}
				}
			}
			else
			{
				int v = (int)(c[i] - '0');
				int tmp = (v*base)%13;
				at = Arrays.copyOf(a, 13);
				for(int k = 0; k < 13; k++)
				{
					a[(k+tmp)%13] = at[k];
				}
			}
			base = (base*10)%13;
		}
