		return (int) ((x+mod)%13);
	}
	static int MOD=(int)1e9+7;
	static char[]s;
	static int dp(int idx,int mod,int pow) {
		if(idx==s.length)
			return mod==5?1:0;
		if(memo[mod][idx]!=-1)
			return memo[mod][idx];
		long ans=0;
		if(s[idx]!='?')
			ans=dp(idx+1,getMod(mod, s[idx]-'0',pow),pow-1);
		else
			for(int add=0;add<10;add++) {
				ans+=dp(idx+1,getMod(mod, add,pow),pow-1);
				ans%=MOD;
			}
		return memo[mod][idx]=(int)ans;
	}
