	        for (int j = 0; j < 13; j++) {
	            for (int k = 0; k < 10; k++) {
	                if (arr[i] == '?' || arr[i] - '0' == k) {
	                    dp[(j * 10 + k) % 13][i] += dp[j][i - 1];
	                    dp[(j * 10 + k) % 13][i] %= MOD;
	                }
	            }
	        }
	    }
		System.out.println(dp[5][length - 1]);
	}
}

