import java.io.*;
import java.util.*;

public class Main implements Runnable {
    static ContestScanner in;
    static Writer out;
    public static void main(String[] args) {
        new Thread(null, new Main(), "", 16 * 1024 * 1024).start();
    }

    public void run() {
        Main main = new Main();
        try {
            in = new ContestScanner();
            out = new Writer();
            main.solve();
            out.close();
            in.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    void solve() throws IOException {
        char[] s = in.nextToken().toCharArray();
        long[][] dp = new long[s.length + 1][13];
        dp[0][0] = 1;
        final long modL = 1000000007;
        for (int i = 0; i < s.length; i++) {
            if (s[i] == '?') {
                for (int j = 0; j < 10; j++) {
                    for (int k = 0; k < 13; k++) {
                        final int mod = (k * 10 + j) % 13;
                        dp[i + 1][mod] = (dp[i + 1][mod] + dp[i][k]) % modL;
                    }
                }
            } else {
                for (int j = 0; j < 13; j++) {
                    final int mod = (j * 10 + (s[i] - '0')) % 13;
                    dp[i + 1][mod] = (dp[i + 1][mod] + dp[i][j]) % modL;
                }
            }
        }
        System.out.println(dp[s.length][5]);
    }
}

