import java.math.BigInteger;

public class Main implements Runnable {

	static int mod = 1000000007;

    public static void main(String[] args) {
    	new Thread(null, new Main(), "", 1024 * 1024 * 1024).start();
    }

    public void run() {
        PrintWriter out = new PrintWriter(System.out);
        FastScanner sc = new FastScanner();

        char[] c = sc.next().toCharArray();

        int n = c.length;

        int[] s = new int[n];

        for(int i=0;i<n;i++){
        	switch(c[i]){
        	case '?': s[i] = -1;break;
        	case '1': s[i] = 1;break;
        	case '2': s[i] = 2;break;
        	case '3': s[i] = 3;break;
        	case '4': s[i] = 4;break;
        	case '5': s[i] = 5;break;
        	case '6': s[i] = 6;break;
        	case '7': s[i] = 7;break;
        	case '8': s[i] = 8;break;
        	case '9': s[i] = 9;break;
        	}
        }

        long[][] dp = new long[13][n];

        if(s[0]==-1){
        	for(int i=0;i<=9;i++){
        		dp[i][0] = 1;
        	}
        }
        else{
        	dp[s[0]][0] = 1;
        }

        for(int i=1;i<n;i+=1){
            if(s[i]==-1){
            	for(int k=0;k<=9;k++){
        			int mul = k*iterationPowMod(10,i)%13;
            		for(int l=0;l<13;l++){
            			dp[l][i] += dp[(l+mul)%13][i-1];
            			dp[l][i] %= mod;
            		}
            	}
            }
            else{
        		for(int l=0;l<13;l++){
        			int mul = s[i]*iterationPowMod(10,i)%13;
        			dp[l][i] += dp[(l+mul)%13][i-1];
        			dp[l][i] %= mod;
        		}
            }
        }

        out.println(dp[5][n-1]);

        out.flush();
    }

