    	   int MOD = 1000000007;
    	   long[][] dp = new long[S.length() + 1][N];	// 余りが　０　～　１２　のパターン数を設定する
    	   dp[0][0] = 1;								// 初期値　０　を１３で割った余りは　０　が１パターン
    	   int mul = 1;									// 桁数の調整用
