    			   // ？　を　０　～　９　の間、繰り返す
    			   for (int j = 0; j < 10; j++) {
    				   //　下の桁の余りの分、繰り返す
    				   for (int k = 0; k < N; k++) {
    					   // j * mul が対象の桁の数字、それと k　前の桁の余りを足して、余りを計算する
    					   // 計算結果の余りの位置に　下の桁までのパターンを足していく
    					   dp[line + 1][(j * mul + k) % N] += dp[line][k];
    					   dp[line + 1][(j * mul + k) % N] %= MOD;
    				   }
    			   }
    		   } else {
    			   // この桁の値は決まっている
    			   int j = (int)(c - '0');
				   //　下の桁の余りの分、繰り返す
				   for (int k = 0; k < N; k++) {
					   // j * mul が対象の桁の数字、それと k　前の桁の余りを足して、余りを計算する
					   // 計算結果の余りの位置に　下の桁までのパターンを足していく
					   dp[line + 1][(j * mul + k) % N] += dp[line][k];
					   dp[line + 1][(j * mul + k) % N] %= MOD;
