                    int y = d * r % div;
                    int z = (x + div - y) % div;
                    dp[x] += prev[z];
                    dp[x] %= MOD;
                }
            }
            r = r * 10 % div;
            int[] tmp = dp;
            dp = prev;
            prev = tmp;
        }
        out.println(prev[q]);
    }

    private long gcd(long a, long b) {
        while (true) {
            if (b == 0) return a;
            long tmp = a;
            a = b;
            b = tmp % b;
        }
    }

