        long[][] dp = new long[n+1][13];
        dp[0][0] = 1;
        for(int i = 0; i < n; i++){
            if(s[i]!='?'){
                int num = s[i]-'0';
                long val = (pow(10,n-i-1,13) * num)%13;
                val %= 13;
                for(int j = 0; j < 13; j++){
                    dp[i+1][(j+(int)val)%13] += dp[i][j];
                    dp[i+1][(j+(int)val)%13] %= mod;
                }
            }
            else{
                for(int k = 0; k <= 9; k++){
                    long val = (pow(10,n-i-1,13) * k)%13;
                    val %= 13;
                    for(int j = 0; j < 13; j++){
                        dp[i+1][(j+(int)val)%13] += dp[i][j];
                        dp[i+1][(j+(int)val)%13] %= mod;
                    }                 
                }
            }
            // for(int j = 0; j < 13; j++){
            //     out.print(dp[i+1][j]+" ");
            // }
            // out.println();
        }
        out.println(dp[n][5]);
