	}
	private static void next(final long[] T, final long[] R, int n) {
		for(int i=0;i<13;i++) {
			int index =(i*10+n)%13;
			T[index] = T[index]+R[i];
		}
	}
	public static void exec(final Scanner sc, final PrintStream out) throws Exception{
		final String S = sc.nextLine();
		final int L = S.length();
		final long[] R = new long[13];
		final long[] T = new long[13];
		final long mod = 1000000000+7;
		for(int i=0;i<13;i++) {
			R[i] = 0L;
			T[i] = 0L;
		}

		char c = S.charAt(0);
		if(c=='?') {
			for(int r=0;r<10;r++) {
				R[r] = 1;
			}
		}else {
			R[(int)(c-'0')] = 1;
		}


		for(int i=1;i<L;i++) {
			for(int t=0;t<13;t++) {
				T[t] = 0;
			}
			c = S.charAt(i);
			if(c=='?') {
				for(int r=0;r<10;r++) {
					next(T, R, r);
				}
			}else {
				next(T, R, (int)(c-'0'));
			}
			for(int j=0;j<13;j++) {
				R[j]=T[j]%mod;
			}

		}
		out.println(R[5]);
	}
}

import java.util.Scanner;

public class Main {

	int mod = 1000000007;

	public static void main(String[] args) {
		Main mainObj = new Main();
		mainObj.solve();
	}

	public void solve() {
		Scanner sc = new Scanner(System.in);
		String pattern = sc.nextLine();
		sc.close();

		int[][] dp = new int[pattern.length()][13];

		char firstChar = pattern.charAt(0);
		if(firstChar == '?') {
			for(int j = 0; j < 10; j++) {
				dp[0][j] = 1;
			}
		}else {
			dp[0][Integer.parseInt(String.valueOf(firstChar))] = 1;
		}

		for(int i = 1; i < pattern.length(); i++) {
			char nowChar = pattern.charAt(i);
			if(nowChar == '?') {
				for(int k = 0; k < 13; k++) {
					int numOfSameMod = dp[i - 1][k];
					for(int j = 0; j < 10; j++) {
						int modValue = (k * 10 + j) % 13;
						dp[i][modValue] = calcMod(dp[i][modValue] + numOfSameMod);
					}
				}
			}else {
				int nowDigit = Integer.parseInt(String.valueOf(nowChar));
				for(int k = 0; k < 13; k++) {
					int numOfSameMod = dp[i - 1][k];
					int modValue = (k * 10 + nowDigit)%13;
					dp[i][modValue] = calcMod(dp[i][modValue]+ numOfSameMod);
				}
			}
		}

		System.out.println(dp[pattern.length() - 1][5]);
	}

	int calcMod(int value) {
		return value%mod;
	}
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        String pattern = scanner.next();


        int[][] memo = new int[pattern.length()][13];

        run(pattern, 0, BigInteger.TEN.pow(pattern.length() - 1), 5, memo);
    }

    private static int modValue = (int) (Math.pow(10, 9) + 7);

    private static int run(String pattern, int i, BigInteger multiplier, int rem, int[][] memo) {
        if (i == pattern.length()) {
            return rem == 0 ? 1 : 0;
        }

        if (memo[i][rem] != 0) {
            return Math.max(0, memo[i][rem]);
        }

        int d = Character.getNumericValue(pattern.charAt(i));
        int sum = 0;
        if (d == -1) { // '?' case
            for (int j = 0; j <= 9; j++) {
                BigInteger b = multiplier.multiply(BigInteger.valueOf(j));
                int actualRem = b.mod(BigInteger.valueOf(13)).intValue();
                int newRem = rem - actualRem;
                if (newRem < 0) newRem += 13;
                sum += run(pattern, i + 1, multiplier.divide(BigInteger.TEN), newRem, memo);
                sum = sum % modValue;
            }
        } else {
            BigInteger b = multiplier.multiply(BigInteger.valueOf(d));
            int actualRem = b.mod(BigInteger.valueOf(13)).intValue();
            int newRem = rem - actualRem;
            if (newRem < 0) newRem += 13;
            sum += run(pattern, i + 1, multiplier.divide(BigInteger.TEN), newRem, memo);
            sum = sum % modValue;
        }

        if (sum == 0) {
            memo[i][rem] = -1;
        } else {
            memo[i][rem] = sum;
        }

        return sum;
    }
}

