	private static void listUpPossibleNum(String base) {
		int targIdx = base.indexOf('?');
		if ( targIdx == -1 ) {
			if ( getRemainderOfBigDivision(base, 13) == 5 ) {
				ans++;
				if ( ans > mod ) ans %= mod;
			}
			return;
		}

		char[] c = base.toCharArray();
		for ( int i = 0; i < 10; i++ ) {
			c[targIdx] = (char) ('0' + i);
			listUpPossibleNum(String.valueOf(c));
		}
