        int[][] dp = new int[s.length() + 1][13];
        dp[0][0] = 1;
        for(int i = 0; i < s.length(); i++) {
          char c = s.charAt(i);
          for(int j = 0; j < 13; j++) {
            if (c == '?') {
              for(int k = 0; k < 10; k++) {
                int next = (j * 10 + k) % 13;
                dp[i+1][next] = (dp[i+1][next] + dp[i][j]) % mod;
              }
            } else {
              int num = c - '0';
              int next = (j * 10 + num) % 13;
              dp[i+1][next] = (dp[i+1][next] + dp[i][j]) % mod;
            }
          }
        }
        System.out.println(dp[s.length()][5]);
