                        dp[i + 1][(j + f * d) % 13] += dp[i][j];
                        dp[i + 1][(j + f * d) % 13] %= (int) 1e9 + 7;
                    }
                }
            } else {
                int d = c - '0';
                for (int j = 0; j < 13; j++) {
                    dp[i + 1][(j + f * d) % 13] += dp[i][j];
                    dp[i + 1][(j + f * d) % 13] %= (int) 1e9 + 7;
                }
            }
            f *= 10;
            f %= 13;
        }
        System.out.println(dp[n][5]);
    }
}

