                if (s.charAt(i) == '?') {
                    for (int k = 0; k < 10; k++) {
                        int nj = (j + k * ten[i]) % 13;
                        dp[i + 1][nj] = ADD(dp[i + 1][nj], dp[i][j]);
                    }
                } else {
                    int nj = (j + (s.charAt(i) - '0') * ten[i]) % 13;
                    dp[i + 1][nj] = ADD(dp[i + 1][nj], dp[i][j]);
                }
            }
        }
        System.out.println(dp[n][5]);
