            for (int i = in.length - 1; i >= 0; i--) {
                if (place == 0) {
                    if (in[i] == '?') {
                        for (int dig = 0; dig <= 9; dig++) {
                            cnt[place][(((int) (powM(10, place, 13)) * dig)) % 13]++;
                        }
                    } else {
                        cnt[place][((int) (powM(10, place, 13) * (in[i] - '0'))) % 13]++;
                    }
                } else {
                    if (in[i] == '?') {
                        for (int j = 0; j < 13; j++) {
                            for (int dig = 0; dig <= 9; dig++) {
                                cnt[place][(j + ((int) (powM(10, place, 13)) * dig)) % 13] += cnt[place - 1][j];
                                cnt[place][(j + ((int) (powM(10, place, 13)) * dig)) % 13] = mod(cnt[place][(j + ((int) (powM(10, place, 13)) * dig)) % 13], MOD);
                            }
                        }
                    } else {
                        for (int j = 0; j < 13; j++) {
                            cnt[place][(j + ((int) (powM(10, place, 13)) * (in[i] - '0'))) % 13] += cnt[place - 1][j];
                            cnt[place][(j + ((int) (powM(10, place, 13)) * (in[i] - '0'))) % 13] = mod(cnt[place][(j + ((int) (powM(10, place, 13)) * (in[i] - '0'))) % 13], MOD);
                        }
                    }
                }
                ++place;
            }

            pw.println(mod(cnt[in.length - 1][5], MOD));
            pw.close();
        }

        public static long powM(int a, int b, int m) {
            a %= m;
            long res = 1;
            while (b > 0) {
                if ((b & 1) > 0)
                    res = (res * a) % m;
                a = a * a % m;
                b >>= 1;
            }
            return res;
        }

        public static long mod(long n, long m) {
            while (n >= m) {
                n -= m;
            }
            return n;
        }

    }

