    using Match = System.Int32;

    class Program
    {
        static readonly long DIVIDE_BASE = 1000000007;
        static readonly int REMAINDER_BASE = 13;
        static void Main(string[] args)
        {
            // スペース区切りの整数の入力
            char[] inputs = Console.ReadLine().ToCharArray();
            int n = inputs.Count();
            // 剰余の結果がいくつになる可能性があるかを保存する
            long[] remainderPossibilities = new long[REMAINDER_BASE];
            remainderPossibilities[0] = 1;
            for (int i = 0; i < n; i++)
            {
                long[] newList = new long[REMAINDER_BASE];
                if (inputs[i] == '?')
                {
                    for(int j = 0; j < 10; j++)
                    {
                        long[] tmpList = getNewPossibilitiesByShift(remainderPossibilities, j);
                        newList = VectorSum(newList, tmpList);
                    }
                }
                else
                {
                    int digit = int.Parse(inputs[i].ToString());
                    newList = getNewPossibilitiesByShift(remainderPossibilities, digit);
                }
                remainderPossibilities = newList;
                // Console.WriteLine(string.Join(" ", remainderPossibilities));
            }
            Console.WriteLine(remainderPossibilities[5].ToString());
        }

        static long[] getNewPossibilitiesByShift(long[] oldList, int shiftValue)
        {
            long[] newList = new long[REMAINDER_BASE];
            for (int i = 0; i < REMAINDER_BASE; i++)
            {
                newList[Destination(i, shiftValue)] = (newList[Destination(i, shiftValue)] + oldList[i]) % DIVIDE_BASE;
            }
            return newList;
        }

        static int Destination(int tmp, int shift)
        {
            return (tmp * 10 + shift) % REMAINDER_BASE;
        }

        static long[] VectorSum(long[] vector1, long[] vector2)
        {
            long[] result = new long[REMAINDER_BASE];
            for (int i = 0; i < REMAINDER_BASE; i++)
            {
                result[i] = (vector1[i] + vector2[i]) % DIVIDE_BASE;
            }
            return result;
        }
    }
}

