class Power
{
    public long digit;
    public long residualPower;
    public Power(long digit, long residualPower)
    {
        this.digit = digit;
        this.residualPower = residualPower;
    }
}

static class Template
{
    public static long LineToInt()
    {
        return long.Parse(Console.ReadLine());
    }

    public static string[] LineToStrings()
    {
        return Console.ReadLine().Split();
    }

    public static long[] LineToInts()
    {
        return LineToStrings()
            .Select(s => long.Parse(s))
            .ToArray();
    }


    public static long[,] LinesToIntTable(long lineCount, long columnCount)
    {
        var value = new long[lineCount, columnCount];
        foreach (var y in Enumerable.Range(0, (int)lineCount))
        {
            var longs = LineToInts();
            foreach (var x in Enumerable.Range(0, (int)columnCount))
            {
                value[y, x] = longs[x];
            }
        }
        return value;
    }

    public static IEnumerable<WithIndex<T>> WithIndex<T>(this IEnumerable<T> sequence)
    {
        long index = 0;
        foreach (var item in sequence)
        {
            yield return new WithIndex<T>(item, index);
            index++;
        }
    }

    static long at(string s, long digit)
    {
        return s[(int)digit - 1];
    }
    static Dictionary<long, long> memo = new Dictionary<long, long>();
    static long fact(long n)
    {
        if (n == 0)
        {
            if (!memo.ContainsKey(0)) memo.Add(0, 1);
            return 1;
        }
        if (memo.ContainsKey(n)) return memo[n];
        var f = n * fact(n - 1) % 1000000007;
        memo.Add(n, f);
        return f;
    }
    static long combi(long n, long r)
    {
        return fact(n) / (fact(n - r) * fact(r));
    }
    static long residualAtPower(long digit)
    {
        switch (digit % 6)
        {
            case 0: return 1;
            case 1: return 10;
            case 2: return 9;
            case 3: return 12;
            case 4: return 3;
            case 5: return 4;
            default: throw new Exception("aaaa");
        }
    }
    static void Main(string[] args)
    {
        var input = Console.ReadLine();
        var withDigit = input.WithIndex()
            .Select(item => new WithIndex<char>(item.Value, item.Index + 1))
            .ToArray();
        var clearResidual = withDigit
            .Where(item => item.Value != '?')
            .Select(item => (item.Value - '0') * residualAtPower(item.Index))
            .Sum() % 13;
        var shouldResidual = 5 - clearResidual;
        while (shouldResidual < 0) shouldResidual += 13;
        var unknown = withDigit
            .Where(item => item.Value == '?')
            .Select(item => new Power(item.Index, residualAtPower(item.Index)))
            .ToArray();
        //6個いかのグループにまとまっている
        var unknownGroup = unknown
            .GroupBy(u => u.residualPower)
            .ToArray();
        var groupCounts = unknownGroup
            .Select(g => g.Count())
            .ToArray();
        var index = 0;
        var max = Math.Pow(10, unknownGroup.Length);
        long patternCount = 0;
        var multiplers = new long[unknownGroup.Length];
        while (index < max)
        {
            var tempIndex = index;
            var residualSum = 0L;
            for (long i = 0; i < unknownGroup.Length; i++)
            {
                multiplers[i] = tempIndex % 10;
                tempIndex /= 10;

                residualSum += unknownGroup[i].Key * multiplers[i];
            }
            residualSum %= 13;
            //
            if (residualSum == shouldResidual)
            {
                long[] tempPatterns = new long[unknownGroup.Length];
                for (long i = 0; i < unknownGroup.Length; i++)
                {
                    //合計値がこの数
                    var takeCountSum = multiplers[i];
                    //何桁ある
                    var digits = groupCounts[i];
                    //
                    long tempPattern = combi(takeCountSum + digits - 1, digits - 1);
                    tempPatterns[i] = tempPattern;
                    //patternCount += tempPattern;
                    while (patternCount > 1000000007)
                    {
                        patternCount -= 1000000007;
                    }
                }
                long p = 1;
                foreach (var t in tempPatterns)
                {
                    p *= t;
                    while (p > 1000000007)
                    {
                        p -= 1000000007;
                    }
                }
                patternCount += p;
                while (patternCount > 1000000007)
                {
                    patternCount -= 1000000007;
                }
            }
            //
            index++;
        }
        Console.WriteLine(patternCount);
    }
}

