using System;
using System.Collections.Generic;
using System.Linq;

namespace CSharpSample01
{


    class Program
    {

        const int MOD = 1000000007;

        static long Solve(string S)
        {
            int n = S.Length;

            S = string.Join("", S.Reverse());

            long[,] dp = new long[n + 1, 13];

            dp[0, 0] = 1;

            for(int j = 1; j < 13; j++)
            {
                dp[0, j] = 0;
            }

            int ten = 0;

            for(int i = 0; i < n; i++)
            {
                if (i == 0) ten = 1;
                else ten = (ten * 10) % 13;


                int c;
                if (S[i] == '?') c = -1;
                else c = S[i] - '0';

                for (int j = 0; j < 13; j++)
                {
                    for(int k = 0; k <= 9; k++)
                    {
                        if(c != -1)
                        {
                            dp[i + 1, (c * ten + j) % 13] += dp[i, j];
                            break;
                        }
                        dp[i + 1, (k * ten + j) % 13] += dp[i, j];
                    }       

                }  

                for(int j = 0; j < 13; j++)
                {
                    dp[i + 1, j] %= MOD;
                }

            }


            return dp[n, 5];
        }


        static void Main(string[] args)
        {
            string S = Console.ReadLine();


            Console.WriteLine(Solve(S));
        }
    }
}

using System;
using System.Text;
using System.Collections.Generic;
using System.Linq;

namespace DigitsParades
{
    class Program
    {
        static void Main(string[] args)
        {
            var S = Console.ReadLine();
            var mod = 1000000007;
            //一桁目から扱えるようにするため、反転させる
            var charS = S.ToCharArray();
            Array.Reverse(charS);

            var figsum = 0L;
            for (int i = 0; i < S.Length; i++)
            {

                if(charS[i] != '?')
                {
                    var num = int.Parse(charS[i].ToString());
                    //繰り返し二乗法により10のi乗を13で割った数値を保存する
                    var mnum = RepeatSquaring(10, i,13);
                    figsum += mnum*num;
                }
            }
            //初期に数字が入ってる数の13で割った余り
            figsum %= 13;
            //目的値(？の部分を足していってこの数字に合わせるようにする)
            long aim = 13 + 5;
            aim -= figsum;
            aim %= 13;
           // Console.WriteLine(aim);

            //それぞれのmodの組み合わせパターン
            var comb = new long[13];

            //var ans = 0L;
            var once = true;
            for (int i = 0; i < charS.Length; i++)
            {
                if (charS[i] == '?')
                {
                    //繰り返し二乗法により10のi乗を13で割った数値を保存する
                    var mnum = RepeatSquaring(10, i, 13);
                    var tmp = new long[13];
                    //?が0から9まで動くことを考慮する
                    for (int j = 1; j <= 9; j++)
                    {
                        //jとの和がaimと13で合同な数を探す。
                        //var comp = (13 + aim - figmod) % 13;
                        var figmod = (mnum * j) % 13;
                        if (once)
                        {
                            tmp[figmod]++;
                        }
                        for (int k = 0; k < 13; k++)
                        {
                            var tai = (figmod + k) % 13;
                            tmp[tai] += comb[k];
                            tmp[tai] %= mod;
                        }
                    }
                    if (once)
                    {
                        once = false;
                        comb[0]++;
                    }

                    //移す
                    for (int j = 0; j < 13; j++)
                    {
                        comb[j] += tmp[j];
                        comb[j] %= mod; 
                    }
                }
            }

            Console.WriteLine(comb[aim]);
        }

        //繰り返し2乗法
        static long RepeatSquaring(long N, long M = 1000000005, long mod = 1000000007)
        {
            if (M == 0)
            {
                return 1;
            }
            else if (M % 2 == 0)
            {
                long t = RepeatSquaring(N, (M / 2), mod) % mod;
                return (t * t) % mod;
            }
            else
            {
                return ((N % mod) * RepeatSquaring(N, M - 1, mod)) % mod;
            }
        }
    }
}

