        var DP = new ulong[13];
        if (S[0] != '?')
            DP[S[0] - '0'] = 1ul;
        else {
            for (var a = 0; a <= 9; a++)
                DP[a] = 1ul;
        }

// System.Console.WriteLine(new { i=0, DP=DP.Join() });

        for (var i = 1; i < S.Length; i++) {
            var NDP = new ulong[13];

            for (var j = 0; j < 13; j++) {

                for (var a = 0; a <= 9; a++) {
                    if (S[i] == '?' || S[i] == a + '0') {

                        var x = (j * 10 + a) % 13;
                        NDP[x] += DP[j];
                        NDP[x] %= MOD;

                    }
                }
            }

            DP = NDP;
// System.Console.WriteLine(new { i, DP=DP.Join() });
        }

        System.Console.WriteLine(DP[5]);
