namespace CSharpSample01
{


    class Program
    {

        const long MOD = 1000000007;

        static long Solve(string S)
        {
            S = string.Join("", S.Reverse());
            int N = S.Length;
            //dp[i, j] := i文字目までの値であまりがjとなるの通り
            long[,] dp = new long[N + 1, 13];
            //0文字目の時は値はないので余り0として1通りとする
            dp[0, 0] = 1;
            int ten = 1;

            //i文字目までの余りは dp[i - 1]
            //追加されるのは値S[i - 1] * 10^(i-1)
            //追加される余りはS[i - 1] * 10^(i-1) % 13 = add
            //i文字目までの全体の余りは add + dp[i - 1, j] (j = 0 ～ 12)
            for (int i = 1; i <= N; i++)
            {
                if (i == 1) ten = 1;
                else ten = (ten * 10) % 13;

                int val = -1;
                if (S[i - 1] != '?') val = S[i - 1] - '0';

                if(val != -1)
                {
                    for(int j = 0; j <= 12; j++)
                    {
                        dp[i, (((val * ten) % 13) + j) % 13] += dp[i - 1, j];
                    }                    
                }
                else
                {
                    //? = val = 0 ～ 9 において更新
                    for(val = 0; val <= 9; val++)
                    {
                        for (int j = 0; j <= 12; j++)
                        {
                            dp[i, ((val * ten) % 13 + j) % 13] += dp[i - 1, j];
                        }
                    }
                }

                for (int j = 0; j <= 12; j++) dp[i, j] %= MOD;

            }


            return dp[N, 5];
        }


        static void Main(string[] args)
        {
            //入力1(S)
            string S = Console.ReadLine();

            Console.WriteLine(Solve(S));

        }
    }

}

