                }

                a = a * a % mod;
                n >>= 1;
            }

            return res;
        }

        static long Solve(char[] s, int index, int m, long?[,] memo)
        {
            if (index >= s.Length)
            {
                return m == 5 ? 1 : 0;
            }

            if (memo[index, m].HasValue)
            {
                return memo[index, m].GetValueOrDefault();
            }

            long ans = 0;
            if (s[index] == '?')
            {
                for (int digit = 0; digit < 10; digit++)
                {
                    ans = (ans + Solve(s, index + 1, (m + Pow10[index] * digit) % 13, memo)) % Mod;
                }
            }
            else
            {
                ans = Solve(s, index + 1, (int)(m + Pow10[index] * (s[index] - '0')) % 13, memo);
            }

            return (memo[index, m] = ans).GetValueOrDefault();
        }

