class abc147{
    public static void Main(){
        int[] res_13s = {1,10,9,12,3,4};
        Func<int,int> res_13 = x => res_13s[x % 6];
        Func<int,int> mod13 = x => {
            if(x>=0)
                return x%13;
            else
                return (13 - (-x % 13)) % 13;
        };
        string S = Console.ReadLine();
        int[] dp = new int[13];
        dp[0] = 1;
        for(int pow = 0; pow < S.Length ; pow++){
            char digit = S[S.Length - 1 - pow];
            int[] dp_new = new int[13];
            switch(digit){
                case '?':
                for(int j = 0; j < 13; j++){
                    for(int a = 0 ; a < 10 ; a++){
                        int mod_new = mod13(res_13(pow) * a);
                        dp_new[j] = (dp_new[j] + dp[mod13((13 - mod_new) + j)]) % 1000000007;
                    }
                }
                break;
                default:
                for(int j = 0; j < 13;j++){
                    int mod_new = mod13(res_13(pow) * (digit - '0'));
                    dp_new[j] = dp[mod13((13 - mod_new) + j)];
                }
                break;
            }
            dp = dp_new;
        }
        Console.WriteLine(dp[5]);
    }
