        int[,] dp = new int[n+1, 13];
        //dp[k,i]=あまりがiである、問いの文字列の後ろからk文字分切り取って得る文字列に準拠した数字の数
        for (int i = 0; i < 13; i++)
        {
            if (s[n - 1] == '?' || s[n - 1] - 48 == i)
            {
