        {
            m = modl[k % 6];
            if (s[n - k - 1] != '?') {
                m = (m * (s[n - k - 1] - 48)) % 13;
                for(int i = 0; i < 13; i++)
                {
                    dp[k + 1, i] = dp[k, (i + m) % 13];
                }
            }
            else
            {
                for (int q = 0; q < 10; q++)
                {
                    for (int i = 0; i < 13; i++)
                    {
                        dp[k + 1, i] = ((dp[k + 1, i] + dp[k, (i + m * q) % 13]) % 1000000007);
                    }
                }
            }
