        public void Solve(ConsoleInput cin)
        {

            var S = cin.ReadLine.ToCharArray();
            var N = S.Length;

            // (S=) ??2??5%13
            //    = (?*10^5 + ?*10^4 +2*10^3 +?*10^2 +?*10^1 + 5*10^0)% 13
            //    = ?*10^5 % 13 + ?*10^4 % 13 + 2*10^3 % 13 + ?*10^2 % 13 + ?*10^1 % 13 + 5*10^0 % 13
            var dp = new long[100001, 13];
            // 先頭i文字として考えられるもののうち、13で割ったあまりがjであるものの数

            dp[0, 0] = 1;
            for (int i = 0; i < N; i++)
            {
