                if (S[i] == '?')
                {
                    tmp = -1;
                }
                else
                {
                    tmp = (int)S[i] - (int)'0';
                }

                for (int j = 0; j < 10; j++)
                {
                    if (tmp != -1 && tmp != j)
                    {
                        continue;
                    }
                    for (int k = 0; k < 13; k++)
                    {
                        dp[i + 1, (k * 10 + j) % 13] += dp[i, k];
                    }
                }
                for (int j = 0; j < 13; j++)
                {
                    dp[i + 1, j] %= 1000000007;
                }
            }

