        T[] res = new T[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            if (i==0)
            {
                res[i] = array[i];
            }
            else
            {
                res[i] = (dynamic)res[i - 1] + (dynamic)array[i];
            }
        }
