    {
        T[] res = new T[array.Length];
        for (int i = array.Length-1; i >= 0; i--)
        {
            if (i == array.Length-1)
            {
                res[i] = array[i];
            }
            else
            {
                res[i] = (dynamic)res[i + 1] + (dynamic)array[i];
            }
        }
        return res;
    }

    static int Nibutan(long[] array, long k)
    {
        int low = 0 ;
        int high = array.Length-1;
        int mid = high;

        while (low < high)
        {
            mid = (low + high) / 2;
            if(array[mid] >= k) // k以上の最小index.ココを変えるだけ
            {
                high = mid;
            }
            else
            {
                low = mid + 1;
            }
            mid = (low + high) / 2;
        }
        return mid;
    }   

