using System;
class Program
{
  static void Main()
  {
    string S = Console.ReadLine();
    const long mod = 1000000007;
    int dig = S.Length;
    long [,] dp = new long[dig + 1, 13];

    // 初期化
    for (int i = 0; i < 13; i++)
    {
      string s = S.Substring(0, 1);
      if ((s == "?") && (i <= 9))
        dp[1, i] = 1;
      else if (s != "?" && int.Parse(s) == i)
        dp[1, i] = 1;
      else
        dp[1, i] = 0;
    }

    // dp
    for (int i = 2; i <= dig; i++)
    {
      // S の上から i 桁目の文字
      string s = S.Substring(i - 1, 1);

      for (int j = 0; j < 13; j++)
      {
        // 上 i 桁の %13 が j　になる場合の数 =: dp[i, j]

        long sum = 0;
        for (int k = 0; k < 13; k++)
        {
          long c = 0;
          if (s == "?")
          {
            int newmod = (1300 + j - k * 10) % 13;
            if (newmod >= 0 && newmod <= 9)
              c = 1;
          }
          else
          {
            int sint = int.Parse(s);
            if ((k * 10 + sint) % 13 == j)
              c = 1;
          }
          sum += dp[i-1, k] * c;
          sum %= mod;
        }
        dp[i, j] = sum;
      }
    }

    // 結果
    Console.WriteLine(dp[dig, 5]);

  }

}

