        public void Solve(TextReader textReader, IConsoleWriter consoleWriter)
        {
            var cin = new ConsoleInput(textReader, ' ');

            string S = cin.Read;

            int Len = S.Length;

            int N = 13;

            long[][] dp = new long[Len + 1][];

            for (int i = 0; i < Len + 1; i++)
            {
                dp[i] = new long[N];
            }

            dp[0][0] = 1;

            int mul = 1;

            for (int i = 0; i < Len; i++)
            {
                int index = Len - i - 1;

                char c = S[index];

                if (c == '?')
                {
                    for (int k = 0; k < 10; k++)
                    {
                        for (int j = 0; j < N; j++)
                        {
                            dp[i + 1][(mul * k + j) % N] += dp[i][j];
                            dp[i + 1][(mul * k + j) % N] %= ModLarge;
                        }
                    }
                }
                else
                {
                    int num = c - '0';

                    for (int j = 0; j < N; j++)
                    {
                        dp[i + 1][(mul * num + j) % N] += dp[i][j];
                        dp[i + 1][(mul * num + j) % N] %= ModLarge;
                    }
                }


                for (int j = 0; j < N; j++)
                {
                    dp[i + 1][j] %= ModLarge;
                }

                mul *= 10;
                mul %= N;
            }

            consoleWriter.WriteLine(dp[Len][5].ToString());
        }
    }

