namespace AtCorder
{
	public class Program
	{
		const int MOD = 1000000007;
		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			string s = cin.Next();
			List<int[]> d = new List<int[]>();
			for (int i = 0; i < 10; i++) {
				int[] dd = new int[6];
				dd[0] = (i * 1) % 13;
				dd[1] = (i * 10) % 13;
				dd[2] = (i * 100) % 13;
				dd[3] = (i * 1000) % 13;
				dd[4] = (i * 10000) % 13;
				dd[5] = (i * 100000) % 13;
				d.Add(dd);
			}

			long ans = 0;
			var ss = s.Reverse().ToArray();
			int l = s.Length;

			int b = 0;
			List<int> hatenas = new List<int>();
			for (int i = 0; i < l; i++) {
				if (ss[i] == '?') {
					hatenas.Add(i);
				} else {
					int j = ss[i] - '0';
					b = (b + d[j][i % 6]) % 13;
				}
			}

			int[,] count = new int[hatenas.Count, 13];
			for (int i = 0; i < hatenas.Count; i++) {
				int c = i % 6;
				for(int j = 0; j < 10; j++) {
					if (i == 0) {
						count[i, d[j][c]] = 1;
					} else {
						int dd = d[j][c];
						for (int k = 0; k < 10; k++) {
							int jj = (k + dd) % 13;
							count[i, jj] = (count[i, jj] + count[i - 1, k]) % MOD;
						}
					}
				}
			}

			int target = 5 - b;
			if (target < 0) {
				target += 13;
			}

			ans = count[hatenas.Count - 1, target];

			Console.WriteLine(ans);
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private string[] buf_;
		private int index_;

		public Scanner()
		{
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = Console.ReadLine();
			while (st == "") {
				st = Console.ReadLine();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

