        static public void Solve()
        {
            var S = NS;

            var dp = new Mod[13];
            dp[0] = 1;
            var shift = 1L;
            for (var i = S.Length - 1; i >= 0; i--)
            {
                var ndp = new Mod[13];
                var ch = S[i];
                if (ch == '?')
                {
                    for (var l = 0; l < 10; l++)
                    {
                        for (var k = 0; k < 13; k++)
                        {
                            ndp[(l * shift + k) % 13] += dp[k];
                        }
                    }
                }
                else
                {
                    var num = ch - '0';
                    for (var k = 0; k < 13; k++)
                    {
                        ndp[(num * shift + k) % 13] += dp[k];
                    }
                }
                shift *= 10;
                shift %= 13;
                dp = ndp;
            }

            Console.WriteLine(dp[5]);

        }

