class AtCoder
{
    const int MOD = 1000000007;
    public void Slove()
    {
        int[] dp = new int[13];
        int[] mod = Enumerable.Range(0, 140).Select(x => x % 13).ToArray();
        dp[0] = 1;
        foreach(char c in Console.ReadLine())
        {
            int[] temp = new int[13];
            if(c == '?')
            {
                for(int j = 0; j < 10; j++)
                {
                    for (int i = 0, v = j; i < 13; i++, v += 10)
                    {
                        temp[mod[v]] += dp[i];
                        temp[mod[v]] %= MOD;
                    }
                }
            }
            else
            {
                for(int i = 0, v = int.Parse(c.ToString());i < 13; i++, v+=10)
                {
                    temp[mod[v]] += dp[i];
                    temp[mod[v]] %= MOD;
                }
            }
            dp = temp;
            //Console.WriteLine(string.Join(" ", dp));
        }
        Console.WriteLine(dp[5]);
    }
    static void Main()
    {
        var ac = new AtCoder();
        ac.Slove();
    }
}

