	public class Program
	{
		const int MOD = 1000000007;
		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			string s = cin.Next();
			int n = s.Length;
			int[,] dp = new int[100005, 13];
			dp[0,0] = 1;
			for (int i = 0; i < n; i++) {
				if (s[i] == '?') {
					for (int j = 0; j < 10; j++) {
						for (int k = 0; k < 13; k++) {
							dp[i + 1, (k * 10 + j) % 13] += dp[i, k];
							dp[i + 1, (k * 10 + j) % 13] %= MOD;
						}
					}
				} else {
					int j = s[i] - '0';
					for (int k = 0; k < 13; k++) {
						dp[i + 1, (k * 10 + j) % 13] += dp[i, k];
						dp[i + 1, (k * 10 + j) % 13] %= MOD;
					}
				}
			}

			long ans = dp[n, 5];
			Console.WriteLine(ans);
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private string[] buf_;
		private int index_;

		public Scanner()
		{
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = Console.ReadLine();
			while (st == "") {
				st = Console.ReadLine();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int()
		{
			return int.Parse(Next());
		}
		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long Long()
		{
			return long.Parse(Next());
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double Double()
		{
			return double.Parse(Next());
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}
	}
}

