class WithIndex<T>
{
    public T Value;
    public int Index;
    public WithIndex(T value, int index)
    {
        this.Value = value;
        this.Index = index;
    }
}

class Power
{
    public int digit;
    public int residualPower;
    public Power(int digit, int residualPower)
    {
        this.digit = digit;
        this.residualPower = residualPower;
    }
}

static class Template
{
    public static int LineToInt()
    {
        return int.Parse(Console.ReadLine());
    }

    public static string[] LineToStrings()
    {
        return Console.ReadLine().Split();
    }

    public static int[] LineToInts()
    {
        return LineToStrings()
            .Select(s => int.Parse(s))
            .ToArray();
    }


    public static int[,] LinesToIntTable(int lineCount, int columnCount)
    {
        var value = new int[lineCount, columnCount];
        foreach (var y in Enumerable.Range(0, lineCount))
        {
            var ints = LineToInts();
            foreach (var x in Enumerable.Range(0, columnCount))
            {
                value[y, x] = ints[x];
            }
        }
        return value;
    }

    public static IEnumerable<WithIndex<T>> WithIndex<T>(this IEnumerable<T> sequence)
    {
        int index = 0;
        foreach (var item in sequence)
        {
            yield return new WithIndex<T>(item, index);
            index++;
        }
    }

    static int at(string s, int digit)
    {
        return s[digit - 1];
    }
    static Dictionary<long, long> memo = new Dictionary<long, long>();
    static long fact(long n)
    {
        if (n == 0)
        {
            if (!memo.ContainsKey(0)) memo.Add(0, 1);
            return 1;
        }
        if (memo.ContainsKey(n)) return memo[n];
        var f = n * fact(n - 1);
        memo.Add(n, f);
        return f;
    }
    static long combi(int n, int r)
    {
        return fact(n) / (fact(n - r) * fact(r));
    }
    static int residualAtPower(int digit)
    {
        switch (digit % 6)
        {
            case 0: return 1;
            case 1: return 10;
            case 2: return 9;
            case 3: return 12;
            case 4: return 3;
            case 5: return 4;
            default: throw new Exception("aaaa");
        }
    }
    static void Main(string[] args)
    {
        var input = Console.ReadLine();
        var withDigit = input.WithIndex()
            .Select(item => new WithIndex<char>(item.Value, item.Index + 1))
            .ToArray();
        var clearResidual = withDigit
            .Where(item => item.Value != '?')
            .Select(item => (item.Value - '0') * residualAtPower(item.Index))
            .Sum() % 13;
        var shouldResidual = 5 - clearResidual;
        while (shouldResidual < 0) shouldResidual += 13;
        var unknown = withDigit
            .Where(item => item.Value == '?')
            .Select(item => new Power(item.Index, residualAtPower(item.Index)))
            .ToArray();
        //6個いかのグループにまとまっている
        var unknownGroup = unknown
            .GroupBy(u => u.residualPower)
            .ToArray();
        var groupCounts = unknownGroup
            .Select(g => g.Count())
            .ToArray();
        var index = 0;
        var max = Math.Pow(10, unknownGroup.Length);
        long patternCount = 0;
        var multiplers = new int[unknownGroup.Length];
        while (index < max)
        {
            var tempIndex = index;
            var residualSum = 0;
            for (int i = 0; i < unknownGroup.Length; i++)
            {
                multiplers[i] = tempIndex % 10;
                tempIndex /= 10;

                residualSum += unknownGroup[i].Key * multiplers[i];
            }
            residualSum %= 13;
            //
            if (residualSum == shouldResidual)
            {
                long[] tempPatterns = new long[unknownGroup.Length];
                for (int i = 0; i < unknownGroup.Length; i++)
                {
                    //合計値がこの数
                    var takeCountSum = multiplers[i];
                    //何桁ある
                    var digits = groupCounts[i];
                    //
                    long tempPattern = combi(takeCountSum + digits - 1, digits - 1);
                    tempPatterns[i] = tempPattern;
                    //patternCount += tempPattern;
                    while (patternCount > 1000000007)
                    {
                        patternCount -= 1000000007;
                    }
                }
                long p = 1;
                foreach (var t in tempPatterns)
                {
                    p *= t;
                    while (p > 1000000007)
                    {
                        p -= 1000000007;
                    }
                }
                patternCount += p;
                while (patternCount > 1000000007)
                {
                    patternCount -= 1000000007;
                }
            }
            //
            index++;
        }
        Console.WriteLine(patternCount);
    }
}

using System;
using System.Linq;

class D
{
	static void Main()
	{
		var r = Enumerable.Range(0, 13);
		var d = Enumerable.Range(0, 10).Select(i =>
		{
			var m = new int[13, 13];
			foreach (var j in r) m[(10 * j + i) % 13, j] = 1;
			return new { i, m };
		})
		.ToDictionary(_ => _.i.ToString()[0], _ => _.m);

		var m_ = new int[13, 13];
		foreach (var p in r.SelectMany(i => r.Select(j => new { i, j }))) m_[p.i, p.j] = d.Values.Sum(m => m[p.i, p.j]);
		d['?'] = m_;

		var x = new long[13];
		x[0] = 1;
		x = Console.ReadLine().Aggregate(x, (v, c) => r.Select(i => r.Sum(j => d[c][i, j] * v[j]) % 1000000007).ToArray());
		Console.WriteLine(x[5]);
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

public class Hello
{
    private const int MOD_N = 1000000000 + 7;

    public static void Main()
    {
        var s = Console.ReadLine();

        var dp = new int[s.Length + 1][];
        for (int i = 0; i < dp.Length; ++i)
            dp[i] = new int[13];

        dp[0][0] = 1;

        for (int i = 0; i < s.Length; ++i)
        {
            var prev = dp[i];
            var now = dp[i + 1];

            if (s[i] == '?')
            {
                for (int j = 0; j < 10; ++j)
                {
                    for (int k = 0; k < prev.Length; ++k)
                    {
                        var t = (10 * k + j) % 13;
                        now[t] += prev[k];
                        now[t] %= MOD_N;
                    }
                }
            }
            else
            {
                var c = s[i] - '0';
                for (int j = 0; j < prev.Length; ++j)
                {
                    now[(10 * j + c) % 13] = prev[j];
                }
            }
        }

        Console.WriteLine(dp[dp.Length - 1][5]);
    }

    private static int GCD(int a, int b) => a > b ? GCD_impl(a, b) : GCD_impl(b, a);
    private static int GCD_impl(int a, int b) => b == 0 ? a : GCD_impl(b, a % b);
    private static long LCM(int a, int b) => (long)a * b / GCD(a, b);

    private static int Comb(int m, int n)
    {
        var t = m - n;
        if (n > t)
            n = t;

        long numerator = 1;
        for (int i = 0; i < n; ++i)
        {
            numerator *= m - i;
            numerator %= MOD_N;
        }
        long denominator = 1;
        for (; n != 0; --n)
        {
            denominator *= n;
            denominator %= MOD_N;
        }

        var inv_denominator = ModInv((int)denominator, MOD_N);
        var ret = (int)(numerator * inv_denominator % MOD_N);

        return ret >= 0 ? ret : ret + MOD_N;
    }

    private static int ModInv(int a, int m)
    {
        int b = m, x = 1, y = 0;
        while (b != 0)
        {
            var t = a / b;
            a -= t * b;
            Swap(ref a, ref b);
            x -= t * y;
            Swap(ref x, ref y);
        }
        x %= m;
        return x >= 0 ? x : x + m;
    }

    private static void Swap<T>(ref T a, ref T b)
    {
        var t = a;
        a = b;
        b = t;
    }
}

