static class CodeJam
{
    static long Solve(string S)
    {
        int N = S.Length;
        var dp1 = new long[13];
        dp1[0] = 1;
        int d = 1;
        foreach (char c in S.Reverse())
        {
            var dp2 = new long[13];
            if (c == '?')
            {
                for (int i = 0; i < 13; ++i)
                {
                    for (int j = 0; j < 10; ++j)
                    {
                        int n = (i + d * j) % 13;
                        dp2[n] += dp1[i];
                        dp2[n] %= 1000000007;
                    }
                }
            }
            else
            {
                int j = c - '0';
                for (int i = 0; i < 13; ++i)
                {
                    int n = (i + d * j) % 13;
                    dp2[n] += dp1[i];
                    dp2[n] %= 1000000007;
                }
            }
            d = (d * 10) % 13;
            dp1 = dp2;
        }
        return dp1[5];
    }

    static void Main(string[] args)
    {
        Console.WriteLine(Solve(Console.ReadLine()));
    }
}

using System;
