using System;
using System.Linq;
using System.Collections.Generic;
using static System.Console;
using System.Text;
using System.IO;
namespace AtCoder_Beginner_Contest_135
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
        }
        static void Solve()
        {
            var S = ReadLine();
            var Si = new long[S.Length];
            var xor10 = new long[S.Length];
            var mod = 13L;
            long Mod = 1000000000 + 7;
            //10^n%13
            xor10[0] = 1;
            for (var i = 1; i < S.Length; ++i)
            { xor10[i] = xor10[i - 1] * 10 % mod; }
            var numxor = 0L;//?が0のときのmod
            var cnt = 0L;
            for (var i = S.Length - 1; 0 <= i; --i) 
            {
                if ('?' != S[i])
                {
                    var n = long.Parse(S[i].ToString());
                    numxor += xor10[cnt] * n;
                    numxor %= mod;
                }
                ++cnt;
            }
            var dp = new long[S.Length + 1, mod];
            for (var i = 1; i <= S.Length; ++i)
            {
                if ('?' != S[i - 1])//?ではない場合そのまま遷移
                {
                    for (var k = 0; k < mod; ++k)
                    {
                        dp[i, k] = dp[i - 1, k];
                    }
                    continue;
                }
                var tmp = new long[mod];
                //i*10^n%modを計算。0は除く
                for (var j = 1; j < 10; ++j)
                {
                    var num = (xor10[S.Length - i] * j) % mod;
                    tmp[num]++;
                }
                //0じゃない場合遷移
                for (var j = 0; j < mod; ++j)
                {
                    //i=0の場合は前のをそのまま加える
                    dp[i, j] += dp[i - 1, j];
                    for (var k = 0; k < mod; ++k)
                    {
                        dp[i, (j + k) % mod] += dp[i - 1, j] * tmp[k];
                    }
                }
                //0から遷移する場合
                for (var j = 0; j < mod; ++j)
                {
                    dp[i, j] += tmp[j];
                    dp[i, j] %= Mod;
                }
            }
            dp[S.Length, 0]++;//全て0の場合;
            WriteLine(dp[S.Length, (5 - numxor + mod) % mod] % Mod);
        }
    }
}

using System;
