namespace ABC135D
{
    class Program
    {
        public static void Solve(Input input)
        {
            var s = input.Next();

            var ans = solvedp(s);

            Console.WriteLine(ans);
        }

        // 1?3は、100*1+?*10+3と見なす
        // これにより、細かくmodをとることができる
        static int solvedp(string s)
        {
            int N = 13;
            var dp = new int[N];

            dp[0] = 1;
            long m = 1;
            for (int i = s.Length - 1; i >= 0; i--)
            {
                var nextdp = new int[N];
                int begin = 0;
                int end = 10;

                if (s[i] != '?')
                {
                    begin = s[i] - '0';
                    end = begin + 1;
                }

                for (int j = begin; j < end; j++)
                {
                    var x = (int)((j * m) % MOD);
                    for (int k = 0; k < N; k++)
                    {
                        nextdp[(x + k) % N] += dp[k];
                        nextdp[(x + k) % N] %= MOD;
                    }
                }

                dp = nextdp;
                m = (m * 10) % N;
            }

            return dp[5];
        }

        #region Main
        public static void Main(string[] args)
        {
            // 出力が少ないときはこれをセットする方が時間かかるけれど
            // その場合は出力がボトルネックになっていないので、まあ良しとする
            var needsFlushOutput = true;
            if (needsFlushOutput)
            {
                // 細かく出力しないようにする
                var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
