using System;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var S = Console.ReadLine();
        Console.WriteLine(Calc(S));
    }

    static string Calc(string S)
    {
        long Q = (long)1e9 + 7;
        int N = S.Length;
        var k = Enumerable.Range(0, N)
            .Where(i => S[N - 1 - i] == '?');
        int x = Enumerable.Range(0, N)
            .Where(i => S[i] != '?')
            .Select(i => int.Parse(S[i].ToString()) * pow13(N - 1 - i))
            .Sum();
        if(!k.Any()) return x % 13 == 5 ? "1" : "0";
        var d = Enumerable.Range(0, 13)
            .Select(_ => (long)0)
            .ToArray();
        int j = k.First();
        foreach(int i in Enumerable.Range(0, 10))
        {
            d[(i * pow13(j)) % 13] = 1;
        }
        for (int i = 1; i < k.Count(); i++)
        {
            j = k.ElementAt(i);
            int pow = pow13(j);
            var newd = Enumerable.Range(0, 13)
                .Select(_ => (long)0)
                .ToArray();
            for (int key = 0; key < 13; key++)
            {
                for (int l = 0; l < 10; l++)
                {
                    int mod = (l * pow) % 13;
                    int idx = (key + mod) % 13;
                    newd[idx] = (newd[idx] + d[key]) % Q;
                }
            }
            d = newd;
        }
        int m = ((5 - x % 13) + 13) % 13;
        return (d[m] % Q).ToString();
    }

    static int pow13(int n)
    {
        if(n == 0) return 1;
        else if(n == 1) return 10;
        else
        {
            return Enumerable.Range(0, n)
                .Select(_ => 10)
                .Aggregate((x1, x2) => (x1 * x2) % 13);
        }
    }
}

using System;
