                {
                    for(int j = 0; j < 10; j++)
                    {
                        dic[j * mod % 13]++;
                    }
                }
                else
                {
                    var n = int.Parse(S[N - 1 - i].ToString());
                    dic[n * mod % 13]++;
                }
                for(int j = 0; j < 13; j++)
                {
                    for(int l = 0; l < 13; l++)
                    {
                        dp[i][(j + l) % 13] = (dp[i][(j + l) % 13] + dp[i - 1][j] * dic[l] % bmod) % bmod;
                    }
                }
            }

            Console.WriteLine(dp[N-1][5]);
        }

        static int ModPow(int a, int n, int mod)
        {
            int res = 1;
            while (n > 0)
            {
                if ((n & 1) == 1) { res = res * a % mod; }
                a = a * a % mod; ;
                n >>= 1;
            }
            return res;
        }
