class MainClass
{
    const long MOD = 1000000007;

    public static void Main(string[] args)
    {
        var s = Console.ReadLine();
        var d = new long[s.Length];
        for (int i = 0; i < s.Length; i++)
        {
            if (s[i] == '?')
            {
                d[i] = -1;
            }
            else
            {
                d[i] = s[i] - '0';
            }
        }

        var n = d.Length;
        var m = 13;

        var dp = new long[n + 1, m];
        dp[0, 0] = 1;

        for (int i = 0; i < n; i++)
        {
            if (0 <= d[i])
            {
                for (int k = 0; k < m; k++)
                {
                    dp[i + 1, (k * 10 + d[i]) % m] += dp[i, k];
                    dp[i + 1, (k * 10 + d[i]) % m] %= MOD;
                }
            }
            else
            {
                for (int j = 0; j < 10; j++)
                {
                    for (int k = 0; k < m; k++)
                    {
                        dp[i + 1, (k * 10 + j) % m] += dp[i, k];
                        dp[i + 1, (k * 10 + j) % m] %= MOD;
                    }
                }
            }
        }

        Console.WriteLine(dp[n, 5]);
    }
}

