    public static void Main()
    {
        var s = Console.ReadLine();
        // dp[i番目まで][余り]
        var dp = Enumerable.Range(0, s.Length).Select(_ => new ModInt[13]).ToArray();

        {
            if (s[0] == '?')
            {
                for (int j = 0; j < 10; j++)
                {
                    dp[0][j] = 1;
                }
            }
            else
            {
                dp[0][ToInt(s[0])] = 1;
            }
        }
        for (int i = 1; i < s.Length; i++)
        {
            if (s[i] == '?')
            {
                for (int j = 0; j < 10; j++)
                {
                    for (int k = 0; k < 13; k++)
                    {
                        var m = (k * 10 + j) % 13;
                        dp[i][m] += dp[i - 1][k];
                    }
                }
