    class D
    {
        private static readonly long mod = 1000000007;

        public static void Main()
        {
            var s = Console.ReadLine();
            var n = s.Length;
            var dp = new long[n, 13];

            if (s[n - 1] == '?')
            {
                for (int i = 0; i <= 9; i++)
                    dp[0, i] = 1;
            }
            else
                dp[0, s[n - 1] - '0'] = 1;

            var d = 10;
            for (int i = 1; i < s.Length; i++)
            {
                if (s[n - 1 - i] == '?')
                {
                    for (int j = 0; j < 13; j++)
                    {
                        for (int k = 0; k <= 9; k++)
                        {
                            var r = (j + k * d) % 13;
                            dp[i, r] = (dp[i, r] + dp[i - 1, j]) % mod;
                        }
                    }
                }
                else
                {
                    int num = s[n - 1 - i] - '0';
                    for (int j = 0; j < 13; j++)
                    {
                        var r = (j + num * d) % 13;
                        dp[i, r] = dp[i - 1, j];
                    }
                }
                d = d * 10 % 13;
            }
            Console.WriteLine(dp[n - 1, 5]);
        }
    }
