    public void Solve()
    {
        string s = rs;
        int n = s.Length;
        long[,] dp = new long[n+1, 13];
        //dp[k,i]=あまりがiである、問いの文字列の後ろからk文字分切り取って得る文字列に準拠した数字の数
        int m = 0;
        int[] modl = { 12, 3, 4, 1, 10, 9 };
        dp[0, 0] = 1;
        for (int k = 0; k < n; k++)
        {
            m = modl[k % 6];
            if (s[n - k - 1] != '?') {
                m = (m * (s[n - k - 1] - 48)) % 13;
                for(int i = 0; i < 13; i++)
                {
                    dp[k + 1, i] = dp[k, (i + m) % 13];
                }
            }
            else
            {
                for (int q = 0; q < 10; q++)
                {
                    for (int i = 0; i < 13; i++)
                    {
                        dp[k + 1, i] += dp[k, (i + m * q) % 13];
                    }
                }
                for (int i = 0; i < 13; i++) { dp[k + 1, i] %= 1000000007; }
            }
        }
        Write(dp[n, 5]);
