        public void Solve(TextReader textReader, IConsoleWriter consoleWriter)
        {
            var cin = new ConsoleInput(textReader, ' ');

            string S = cin.Read;
//            string S = new string('?', 100000);

            const int N = 13;

            // dp[k] => 13で割ったあまりがKのパターン数

            long[] dp = new long[N];
            dp[0] = 1;

            // 後ろからとくアルゴリズム
            // 1?2?3 0 -> 3 -> ?3 -> 2?3->> 


            const long Mod = 1000000007;
            int mul = 1;

            for (int i = S.Length - 1; i >= 0; i--)
            {
                long[] nextDp = new long[N];

                char c = S[i];
                if (c == '?')
                {
                    for (int k = 0; k < 10; k++)
                    {
                        for (int j = 0; j < N; j++)
                        {
                            nextDp[(k * mul + j) % N] += dp[j];
                            nextDp[(k * mul + j) % N] %= Mod;
                        }
                    }
                }
                else
                {
                    int k = (int)(S[i] - '0');

                    for (int j = 0; j < N; j++)
                    {
                        nextDp[(k * mul + j) % N] += dp[j];
                        nextDp[(k * mul + j) % N] %= Mod;
                    }
                }

                mul *= 10;
                mul %= N;
                dp = nextDp;
            }

            consoleWriter.WriteLine(dp[5].ToString());
        }
    }

    public class ConsoleInput
    {
        private readonly TextReader _stream;
        private char _separator = ' ';
        private Queue<string> inputStream;

        public ConsoleInput(TextReader stream, char separator = ' ')
        {
            this._separator = separator;
            this._stream = stream;
            inputStream = new Queue<string>();
        }

        public string Read
        {
            get
            {
                if (inputStream.Count != 0) return inputStream.Dequeue();
                string[] tmp = _stream.ReadLine().Split(_separator);
                for (int i = 0; i < tmp.Length; ++i)
                {
                    inputStream.Enqueue(tmp[i]);
                }

                return inputStream.Dequeue();
            }
        }

        public string ReadLine => _stream.ReadLine();
        public int ReadInt => int.Parse(Read);
        public long ReadLong => long.Parse(Read);
        public double ReadDouble => double.Parse(Read);

        public string[] ReadStrArray(long N)
        {
            var ret = new string[N];
            for (long i = 0; i < N; ++i) ret[i] = Read;
            return ret;
        }

        public int[] ReadIntArray(long N)
        {
            var ret = new int[N];
            for (long i = 0; i < N; ++i) ret[i] = ReadInt;
            return ret;
        }

        public long[] ReadLongArray(long N)
        {
            var ret = new long[N];
            for (long i = 0; i < N; ++i) ret[i] = ReadLong;
            return ret;
        }
    }

