class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var S = sc.ReadStr().Reverse().ToArray();
        var mul = 1L;
        var mod = (int)1e9 + 7;

        var dp = new long[S.Length + 1, 13];
        dp[0, 0] = 1;
        for (int i = 0; i < S.Length; i++)
        {
            if (S[i] == '?')
            {
                for (int x = 0; x <= 9; x++)
                {
                    var nowj = x * mul;
                    nowj %= 13;
                    for (int j = 0; j < 13; j++)
                    {
                        var nj = nowj + j;
                        nj %= 13;
                        dp[i + 1, nj] += dp[i, j];
                        dp[i + 1, nj] %= mod;
                    }
                }
            }
            else
            {
                var x = S[i] - '0';
                var nowj = x * mul;
                nowj %= 13;
                for (int j = 0; j < 13; j++)
                {
                    var nj = nowj + j;
                    nj %= 13;
                    dp[i + 1, nj] += dp[i, j];
                    dp[i + 1, nj] %= mod;
                }
            }
            mul *= 10;
            mul %= 13;
        }
        var ans = dp[S.Length, 5];
        Console.WriteLine(ans);
    }
    static Scanner sc = new Scanner();
}
