class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        S = sc.ReadStr().ToArray();
        Array.Reverse(S);
        N = S.Length;
        DP = new long[N + 1, 2, 13];
        Pow = new int[N];
        Pow[0] = 1;
        for (int i = 0; i < N - 1; i++)
        {
            Pow[i + 1] = Pow[i] * 10;
            Pow[i + 1] %= 13;
        }
        for (int i = 0; i < N + 1; i++)
        {
            for (int j = 0; j < 2; j++)
            {
                for (int k = 0; k < 13; k++)
                {
                    DP[i, j, k] = -1;
                }
            }
        }

        var ans = Rec(0, 1, 0);
        Console.WriteLine(ans);
    }
    static long[,,] DP;
    static int[] Pow;
    static long Rec(int i, int j, int k)
    {
        if (i == N)
        {
            if (k == 5) return 1;
            else return 0;
        }
        if (DP[i, j, k] >= 0) return DP[i, j, k];

        var res = 0L;

        var start = 0;
        var end = 9;
        if (S[i] != '?')
        {
            start = S[i] - '0';
            end = S[i] - '0';
        }
        for (int x = start; x <= end; x++)
        {
            var nj = j;
            if (x == end && j == 1) nj = 1;
            var nk = x * Pow[i] + k;
            nk %= 13;
            res += Rec(i + 1, nj, nk);
            res %= (int)1e9 + 7;
        }

        DP[i, j, k] = res;
        return res;
    }
    static char[] S;
    static int N;
    static Scanner sc = new Scanner();
}
