    class Program
    {
        static IO.StreamScanner _stream = new IO.StreamScanner(Console.OpenStandardInput());

        static void Main(string[] args)
        {
            var s = _stream.ScanLine();
            var dp = new long[s.Length, 13];
            var mod = 1000000007L;

            var mod13s = new int[] { };

            for (int i = s.Length - 1; i >= 0; i--)
            {
                if(i == s.Length - 1)
                {
                    mod13s = Enumerable.Range(0, 10).ToArray();
                    if (s[i] == '?')
                    {
                        for (int j = 0; j < 13; j++) dp[i, j] = 1;
                    }
                    else
                    {
                        dp[i, s[i] - '0'] = 1;
                    }
                }
                else
                {
                    mod13s = mod13s.Select(m => (m * 10) % 13).ToArray();
                    if (s[i] == '?')
                    {
                        for (int k = 0; k < 13; k++)
                        {
                            for (int x = 0; x <= 9; x++)
                            {
                                dp[i, k] += dp[i + 1, (k + mod13s[x]) % 13];
                                dp[i, k] %= mod;
                            }
                        }
                    }
                    else
                    {
                        for (int k = 0; k < 13; k++)
                        {
                            var x = s[i] - '0';
                            dp[i, k] += dp[i + 1, (k + mod13s[x]) % 13];
                            dp[i, k] %= mod;
                        }
                    }
                }
            }

            IO.Printer.Out.WriteLine(dp[0, 5]);
            IO.Printer.Out.Flush();
        }
    }

