    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }

    static Scanner cin;

  // ここに回答
    void calc()
    {
        string s = cin.next();
        int N = 13;
        int mod = 1000000007;

        long[] dp = new long[N];
        dp[0] = 1;

        for (int i = 0; i < s.Length; i++)
        {
            long[] nextDp = new long[N];
            char c = s[i];
            if (c == '?')
            {
                // ?が0～9まで値を取るためループ
                for (int j = 0; j < 10; j++)
                {
                    // 13のあまりは0～12まで取るためループ
                    for (int k = 0; k < N; k++)
                    {
                        // 合同式の性質から、ある値に1桁jを足すと、(1桁前の余りk*10)+jが新しいあまりになる
                        nextDp[((k * 10) + j) % N] += dp[k];
                        nextDp[((k * 10) + j) % N] %= mod;
                    }
                }
            }
            else
            {
                // charからintへの変換
                int j = (int)(s[i] - '0');
                // 13のあまりは0～12まで取るためループ
                for (int k = 0; k < N; k++)
                {
                    // 合同式の性質から、ある値に1桁jを足すと、(1桁前の余りk*10)+jが新しいあまりになる
                    nextDp[((k * 10) + j) % N] += dp[k];
                    nextDp[((k * 10) + j) % N] %= mod;
                }

            }
            dp = nextDp;
        }

        Console.WriteLine(dp[5]);
    }
}



