namespace AtCoder.Abc135
{
    class D_FPS
    {
        private static readonly long mod = 1000000007;

        public static void Main()
        {
            var s = Console.ReadLine();
            var n = s.Length;

            var d = 1;
            var r = 0;

            var fCount = new int[6];

            for (int i = 0; i < s.Length; i++)
            {
                if (s[n - 1 - i] == '?')
                    fCount[i % 6]++;
                else
                {
                    int num = s[n - 1 - i] - '0';
                    r = (r + num * d) % 13;
                }
                d = d * 10 % 13;
            }

            var g = new long[13];
            g[0] = 1;
            d = 1;
            for (int i = 0; i < 6; i++)
            {
                var f = new long[13];
                for (int j = 0; j <= 9; j++)
                    f[j * d % 13]++;
                d = d * 10 % 13;
                f = Power(f, fCount[i]);
                g = Mul(g, f);
            }
            Console.WriteLine(g[(5 + 13 - r) % 13]);
        }

        private static long[] Power(long[] f, int n)
        {
            var g = new long[f.Length];
            g[0] = 1;
            while (n > 0)
            {
                if (n % 2 == 1)
                    g = Mul(f, g);
                f = Mul(f, f);
                n /= 2;
            }
            return g;
        }

        private static long[] Mul(long[] f, long[] g)
        {
            var ret = new long[f.Length];
            for (int i = 0; i < f.Length; i++)
            {
                for (int j = 0; j < f.Length; j++)
                {
                    var k = (i + j) % f.Length;
                    ret[k] = (ret[k] + f[i] % mod * g[j]) % mod;
                }
            }
            return ret;
        }
    }
}

