        {
            string s = Console.ReadLine();
            int[,] dp = new int[s.Length, 13];//dp[n,m]=頭n+1桁目までを13で割ったあまりがmとなる通り数
            if (s[0] == '?')
            {
                dp[0, 0] = 1;
                dp[0, 1] = 1;
                dp[0, 2] = 1;
                dp[0, 3] = 1;
                dp[0, 4] = 1;
                dp[0, 5] = 1;
                dp[0, 6] = 1;
                dp[0, 7] = 1;
                dp[0, 8] = 1;
                dp[0, 9] = 1;
            }
            else
                dp[0, s[0] - '0'] = 1;
            for (int i = 1; i < s.Length; i++)
            {
                if (s[i] == '?')
                {
                    for (int m = 0; m < 13; m++)
                    {
                        for (int v = 0; v < 10; v++)
                        {
                            dp[i, (m * 10 + v) % 13] += dp[i - 1, m];
                            dp[i, (m * 10 + v) % 13] %= mod;
                        }
                    }
                }
                else
                {
                    for (int m = 0; m < 13; m++)
                    {
                        dp[i, (m * 10 + (s[i] - '0')) % 13] = dp[i - 1, m];
                        dp[i, (m * 10 + (s[i] - '0')) % 13] %= mod;
                    }
                }
            }
            Console.WriteLine(dp[s.Length - 1, 5]);
        }
