                        nextDP[((j * 10) + k) % N] %= mod;
                    }
                }
            }
            else
            {
                int k = (int)(S[i] - '0');
                for (int j = 0; j < N; j++)
                {
                    nextDP[((j * 10) + k) % N] += dp[j];
                    nextDP[((j * 10) + k) % N] %= mod;
                }
            }

            dp = nextDP;
        }

