using System;
using System.Collections.Generic;
using System.Linq;
using static System.Math;

namespace CSharp
{
    static class Program
    {
        const long Mod = (long)1e9 + 7;

        static void Main(string[] args)
        {
            string s = ReadString();
            long ans = Solve(s.Reverse().ToArray(), 0, 0, new long?[s.Length + 5, 15]);
            Console.WriteLine(ans);
        }

        static long ModPow(long a, int n, long mod)
        {
            long res = 1;

            while (n > 0)
            {
                if ((n & 1) != 0)
                {
                    res = res * a % mod;
                }

                a = a * a % mod;
                n >>= 1;
            }

            return res;
        }

        static long Solve(char[] s, int index, int m, long?[,] memo)
        {
            if (index >= s.Length)
            {
                return m == 5 ? 1 : 0;
            }

            if (memo[index, m].HasValue)
            {
                return memo[index, m].GetValueOrDefault();
            }

            long ans = 0;
            if (s[index] == '?')
            {
                for (int digit = 0; digit < 10; digit++)
                {
                    ans = (ans + Solve(s, index + 1, (int)(m + ModPow(10, index, 13) * digit) % 13, memo)) % Mod;
                }
            }
            else
            {
                ans = Solve(s, index + 1, (int)(m + ModPow(10, index, 13) * (s[index] - '0')) % 13, memo);
            }

            return (memo[index, m] = ans).GetValueOrDefault();
        }

        #region Helpers

        static int[] ReadIntArray() => Console.ReadLine().Split().Select(s => int.Parse(s)).ToArray();
        static long[] ReadLongArray() => Console.ReadLine().Split().Select(s => long.Parse(s)).ToArray();

        static int[] ReadLineIntArray(int count) => Enumerable.Repeat(0, count).Select(_ => int.Parse(Console.ReadLine())).ToArray();
