        public void Solve(ConsoleInput cin)
        {
            var S = cin.Read;
            var n = S.Length;
            var dp = new int[n, 13];
            var MOD = 1000000007;
            var chars = S.ToCharArray();
            for (int i = 0; i < 13; i++)
            {
                if (chars[0] == '?')
                {
                    dp[0, i] = i < 10 ? 1 : 0;
                }
                else
                {
                    dp[0, i] = int.Parse(chars[0].ToString()) % 13 == i ? 1 : 0;
                }
            }
            for (int i = 0; i < n - 1; i++)
            {
                var c = chars[i + 1];
                if (c == '?')
                {
                    for (int j = 0; j < 13; j++)
                    {
                        dp[i + 1, j] = 0;
                    }
                    for (int k = 0; k < 10; k++)
                    {
                        for (int j = 0; j < 13; j++)
                        {
                            dp[i + 1, (j * 10 + k) % 13] += dp[i, j];
                            dp[i + 1, (j * 10 + k) % 13] %= MOD;
                        }
                    }
                }
                else
                {
                    for (int j = 0; j < 13; j++)
                    {
                        dp[i + 1, (j * 10 + int.Parse(c.ToString())) % 13] = dp[i, j];
                    }
                }
            }
            Console.WriteLine(dp[n - 1, 5]);
