func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 500001), 500000)
	return scanner
}

func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	s := getNextString(scanner)
	n := len(s)
	dp := make([][2][13]int, n+1)

	dp[0][0][0] = 1

	mod := int(1e9 + 7)

	for i := 0; i < n; i++ {
		i10 := n - 1 - i
		for ii := 0; ii < 2; ii++ {
			for iii := 0; iii < 13; iii++ {
				if s[i] == '?' {
					for iiii := 0; iiii <= 9; iiii++ {
						m := inc(iiii, i10)
						dp[i+1][ii][(iii+m)%13] += dp[i][ii][iii]
						dp[i+1][ii][(iii+m)%13] %= mod
					}

					continue
				}
				m := inc(int(s[i]-'0'), i10)
				if ii == 0 {
					dp[i+1][0][(iii+m)%13] += dp[i][ii][iii]
					dp[i+1][0][(iii+m)%13] %= mod
				} else {
					dp[i+1][1][(iii+m)%13] += dp[i][ii][iii]
					dp[i+1][1][(iii+m)%13] %= mod
				}
			}
		}
	}
	fmt.Fprintln(writer, dp[n][0][5]+dp[n][1][5])
	writer.Flush()
}

func inc(num, i10 int) int {
	mm := [6]int{
		1, 10, 9, 12, 3, 4,
	}
	return num * (mm[i10%6])
}

