func countDigit(s string) int {
	cache := make([][]int, len(s)) // [pos][remainder]
	for i := 0; i < len(s); i++ {
		cache[i] = make([]int, 13)
	}
	mul := 1
	for i := len(s) - 1; i >= 0; i-- {
		v := s[i]
		digit := len(s) - 1 - i
		if v == '?' {
			for j := 0; j < 10; j++ {
				currentRemainder := j * mul % 13
				// 123:
				//   3 % 13 =  3
				//  23 % 13 = 10
				//  20 % 13 =  7
				// 123 % 13 =  6
				// 100 % 13 =  9
				if digit > 0 {
					for k := 0; k < 13; k++ {
						tmp := (currentRemainder + k) % 13
						cache[i][tmp] += cache[i+1][k]
						if cache[i][tmp] > 1000000007 {
							cache[i][tmp] %= 1000000007
						}
					}
				} else {
					cache[i][currentRemainder]++
					if cache[i][currentRemainder] > 1000000007 {
						cache[i][currentRemainder] %= 1000000007
					}
				}
			}
		} else {
			integer, _ := strconv.Atoi(string(v))
			currentRemainder := integer * mul % 13

			if digit > 0 {
				for k := 0; k < 13; k++ {
					tmp := (currentRemainder + k) % 13
					cache[i][tmp] += cache[i+1][k]
					if cache[i][tmp] > 1000000007 {
						cache[i][tmp] %= 1000000007
					}
				}
			} else {
				cache[i][currentRemainder]++
				if cache[i][currentRemainder] > 1000000007 {
					cache[i][currentRemainder] %= 1000000007
				}
			}
		}
		mul *= 10
		mul %= 13
	}
	return cache[0][5] % 1000000007
}

