func proc(r io.Reader, w io.Writer) {
	var s string
	fmt.Fscanf(r, "%s", &s)
	width := len(s)
	format := fmt.Sprintf("%%0%dd", width)
	limit, _ := strconv.Atoi(strings.Replace(s, "?", "9", -1))
	size := (limit-5+13-1)/13 + 1
	cnt := 0
	for i := 0; i < size; i++ {
		t := fmt.Sprintf(format, i*13+5)
		ok := true
		for j, c := range s {
			if c == '?' {
				continue
			}
			if c != rune(t[j]) {
				ok = false
				break
			}
		}
		if ok {
			cnt++
		}
	}
	//fmt.Printf("%#v", numbers)
	fmt.Fprintf(w, "%d", cnt%(1000000000+7))
}

