func proc(r io.Reader, w io.Writer) {
	const bignum = 1000000007
	var s string
	fmt.Fscanf(r, "%s", &s)
	width := len(s)
	format := fmt.Sprintf("%%0%dd", width)
	max, _ := strconv.Atoi(strings.Replace(s, "?", "9", -1))
	min, _ := strconv.Atoi(strings.Replace(s, "?", "0", -1))
	size := (max-5+13-1)/13 + 1
	cnt := 0
	for i := 0; i < size; i++ {
		number := i*13 + 5
		if min > number {
			continue
		}
		t := fmt.Sprintf(format, number)
		ok := true
		for j, c := range s {
			if c == '?' {
				continue
			}
			if c != rune(t[j]) {
				ok = false
				break
			}
		}
		if ok {
			cnt++
			if cnt > bignum {
				cnt -= bignum
			}
		}
	}
	//fmt.Printf("%#v", numbers)
	fmt.Fprintf(w, "%d", cnt)
}

func main() {
	proc(os.Stdin, os.Stdout)
}

