				dp[i][l] = (dp[i][l] + dp[i-1][j]) % INF
			}
			d = (d * 10) % 13
			continue
		}
		for k := 0; k < 10; k++ {
			m := k * d % 13
			for j := 0; j < 13; j++ {
				l := (j + m) % 13
				dp[i][l] = (dp[i][l] + dp[i-1][j]) % INF
			}
