func countDigit(s string) int {
	cache := make([][]int, len(s)) // [pos][remainder]
	for i := 0; i < len(s); i++ {
		cache[i] = make([]int, 13)
	}
	for i := len(s) - 1; i >= 0; i-- {
		v := s[i]
		digit := len(s) - 1 - i
		if v == '?' {
			for j := 0; j < 10; j++ {
				currentRemainder := j * pow10(digit) % 13
				// 123:
				//   3 % 13 =  3
				//  23 % 13 = 10
				//  20 % 13 =  7
				// 123 % 13 =  6
				// 100 % 13 =  9
				if digit > 0 {
					for k := 0; k < 13; k++ {
						tmp := (currentRemainder + k) % 13
						cache[i][tmp] += cache[i+1][k]
						if cache[i][tmp] > 1000000007 {
							cache[i][tmp] %= 1000000007
						}
					}
				} else {
					cache[i][currentRemainder]++
					if cache[i][currentRemainder] > 1000000007 {
						cache[i][currentRemainder] %= 1000000007
					}
				}
			}
		} else {
			integer, _ := strconv.Atoi(string(v))
			currentRemainder := integer * pow10(digit) % 13

			if digit > 0 {
				for k := 0; k < 13; k++ {
					tmp := (currentRemainder + k) % 13
					cache[i][tmp] += cache[i+1][k]
					if cache[i][tmp] > 1000000007 {
						cache[i][tmp] %= 1000000007
					}
				}
			} else {
				cache[i][currentRemainder]++
				if cache[i][currentRemainder] > 1000000007 {
					cache[i][currentRemainder] %= 1000000007
				}
			}
		}
	}
	return cache[0][5] % 1000000007
}

var powCache []int

func pow10(ex int) int {
	x := 10
	pow := 1
	if powCache[ex] != 0 {
		return powCache[ex]
	}
	for i := 0; i < ex; i++ {
		pow *= x
		pow %= 13
	}
	powCache[ex] = pow
	return pow
}

