// 下から n (1, .., len(chars)) 桁以上で見て 13 で割って k 余らせることができる個数
func rec(n, k int) int {
	if n == len(chars) {
		if chars[0] == '?' {
			if k <= 9 {
				return 1
			}

			return 0
		}

		num := int(chars[0] - '0')

		if num == k {
			return 1
		}

		return 0
	}

	// 1 の桁と 10 以上の桁の和が 13 で割って k 余るかどうか
	if memo[n][k] != -1 {
		return memo[n][k]
	}

	c := chars[len(chars)-n]

	res := 0

	if c == '?' {
		for i := 0; i < 10; i++ {
			rest := (4*k - i*4 + 13*3) % 13
			res += rec(n+1, rest)
		}
	} else {
		num := int(c - '0')
		rest := (4*k - num*4 + 13*3) % 13
		res = rec(n+1, rest)
	}

	res %= MOD

	memo[n][k] = res
	return res
}

