func main() {
	const MOD = 1000000007
	var s string
	fmt.Scan(&s)

	n := len(s)
	var new, old [13]int

	if s[n-1] == '?' {
		for i := 0; i < 13; i++ {
			if i < 10 {
				old[i] = 1
			} else {
				old[i] = 0
			}
		}
	} else {
		c := int(s[n-1] - '0')
		for i := 0; i < 13; i++ {
			if i == c {
				old[i] = 1
			} else {
				old[i] = 0
			}
		}
	}

	digit := 10
	for i := n - 2; i >= 0; i-- {
		for j := 0; j < 13; j++ {
			new[j] = 0
		}
		if s[i] == '?' {
			for m := 0; m < 10; m++ {
				for mod, cnt := range old {
					shifted := (mod + m*digit) % 13
					new[shifted] += cnt
				}
			}
		} else {
