			for mod, cnt := range old {
				shifted := (mod + m*digit) % 13
				new[shifted] += cnt
			}
		}

		for j := 0; j < 13; j++ {
			new[j] %= MOD
		}
		digit = (digit * 10) % 13
		new, old = old, new
	}

