		for iii := 0; iii < 13; iii++ {
			if s[i] == '?' {
				for iiii := 0; iiii <= 9; iiii++ {
					m := (md[di%6][iiii] + iii) % 13
					dp[i+1][m] = (dp[i+1][m] + dp[i][iii]) % mod
				}

				continue
			}
			m := (md[di%6][int(s[i]-'0')] + iii) % 13
			dp[i+1][m] = (dp[i+1][m] + dp[i][iii]) % mod
		}
		di--
	}
	fmt.Fprintln(writer, dp[n][5])
	writer.Flush()
}

