func proc(r io.Reader, w io.Writer) {
	const bignum = 1000000007
	var s string
	fmt.Fscanf(r, "%s", &s)
	width := len(s)
	format := fmt.Sprintf("%%0%dd", width)
	maxNumber, _ := strconv.Atoi(strings.Replace(s, "?", "9", -1))
	minNumber, _ := strconv.Atoi(strings.Replace(s, "?", "0", -1))

	max := (maxNumber - 5) / 13
	min := (minNumber + 13 - 5 - 1) / 13
	cnt := 0
	for i := min; i <= max; i++ {
		number := i*13 + 5
		t := fmt.Sprintf(format, number)
		ok := true
		for j, c := range s {
			if c == '?' {
				continue
			}
			if c != rune(t[j]) {
				ok = false
				break
			}
		}
		if ok {
			cnt++
			if cnt > bignum {
				cnt -= bignum
			}
		}
	}
	//fmt.Printf("%#v", numbers)
	fmt.Fprintf(w, "%d", cnt)
}

func main() {
	proc(os.Stdin, os.Stdout)
}

