	max, _ := strconv.Atoi(strings.Replace(s, "?", "9", -1))
	min, _ := strconv.Atoi(strings.Replace(s, "?", "0", -1))
	cnt := 0
	i := 0
	for {
		number := i*13 + 5
		i++
		if min > number {
			continue
		}
		if number > max {
			break
		}
		t := fmt.Sprintf(format, number)
		ok := true
		for j, c := range s {
			if c == '?' {
				continue
			}
			if c != rune(t[j]) {
				ok = false
				break
			}
		}
		if ok {
			cnt++
			if cnt > bignum {
				cnt -= bignum
			}
		}
	}
	//fmt.Printf("%#v", numbers)
	fmt.Fprintf(w, "%d", cnt)
}

