var chars []rune
var memo [][]int

func pairsToKey(n, k int) string {
	return fmt.Sprintf("%d_%d", n, k)
}

// 下から n (1, .., len(chars)) 桁以上で見て 13 で割って k 余らせることができる個数
func rec(n, k int) int {
	if n == len(chars) {
		if chars[0] == '?' {
			if k <= 9 {
				return 1
			}

			return 0
		}

		num := int(chars[0] - '0')

		if num == k {
			return 1
		}

		return 0
	}

	// 10a + b ≡ k ⇔ 40a + 4b ≡ a + 4b ≡ 4k
	// よって 1 の位と 10 の位以上に分けて、 a ≡ 4k - 4b となる個数を再帰で求めれば良い
	if memo[n][k] != -1 {
		return memo[n][k]
	}

	c := chars[len(chars)-n]

	res := 0

	if c == '?' {
		for i := 0; i < 10; i++ {
			rest := (4*k - i*4 + 13*3) % 13
			res += rec(n+1, rest)
		}
	} else {
		num := int(c - '0')
		rest := (4*k - num*4 + 13*3) % 13
		res = rec(n+1, rest)
	}

	res %= MOD

	memo[n][k] = res
	return res
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	S := io.Next()

	chars = []rune(S)
	memo = make([][]int, len(chars))

	for i := range memo {
		memo[i] = make([]int, 13)

		for j := 0; j < 13; j++ {
			memo[i][j] = -1
		}
	}

	res := rec(1, 5)
	io.Println(res)
}

// d: debug IO. it can print debug in test.
func solve2(io *Io, d *Io) {
	S := io.Next()

	chs := []rune(S)
	// dp[i][j] 先頭 i 文字目（1 <= i <= len(chs)）までで余りが j になる個数
	dp := make([][]int, len(chars)+1)

	for i := range dp {
		dp[i] = make([]int, 13)
	}

	// 一文字目を取った時の mod はその文字自体で決定されるため、 0 文字目相当のものの mod は 0 のものが 1 つあるとする必要がある
	dp[0][0] = 1

	for i := 0; i < len(chs); i++ {
		for j := 0; j < 10; j++ {
			if !(chs[i] == '?' || int(chs[i]-'0') == j) {
				continue
			}

			// i+1 桁目が j で i 桁目までの余りが k であれば i+1 桁目までの余りは 10k + j % 13
			for k := 0; k < 13; k++ {
				dp[i+1][(10*k+j)%13] += dp[i][k]
			}

			for k := 0; k < 13; k++ {
				dp[i+1][k] %= MOD
			}
		}
	}

	res := dp[len(chs)][5]
	io.Println(res)
}

