  foreach(i; 1..dp.length) {
    foreach(j; 0..13) {
      ulong m = 0;
      foreach(k; 0..10) {
        int mod = (tbl[items[i]] * k) % 13;
        int diff = ((13+j) - mod) % 13;
        m = (m + dp[i-1][diff]) % M;
