MOD = 1000000007  # type: int


def getarr(s):
    arr = [0] * 13
    def addmod(s):
        if s.find('?') != -1:
            for n in range(10):
                ind = s.find('?')
                scopy = s[:ind] + str(n) + s[ind+1:]
                addmod(scopy)
        else:
            suuji = int(s)
            arr[suuji % 13] += 1
    addmod(s)
    return arr


def solve(S: str):
    l = len(S)
    N = math.ceil(l / 3)
    dirction = 1

    tbl = [[0 for i in range(13)] for j in range(N)]

    for t in range(N):
        s = S[-3:]
        S = S[:-3]
        arr = getarr(s)
        if t == 0:
            tbl[t] = arr
        else:
            pasttable = tbl[t-1].copy()
            for i in range(13): # arr
                for j in range(13): # past
                    num = arr[i] * pasttable[j]
                    idx = ((j - i) * dirction) % 13
                    tbl[t][idx] += num

        dirction = dirction * -1

    print(tbl[N-1][5] % MOD)

    return

