def slv(S):
    M = Mod(10**9 + 7)
    t = [0] * 13
    t[0] = 1
    m = 1
    for i, c in enumerate(reversed(S)):
        if c != '?':
            n = (m * int(c)) % 13
            nt = [0] * 13
            for k in range(13):
                nt[(k+n) % 13] = t[k]
            t = nt
        else:
            nt = [0] * 13
            for j in range(10):
                n = (m * j) % 13
                for k in range(13):
                    nt[(k+n) % 13] = M.add(nt[(k+n) % 13], t[k])
            t = nt
        m *= 10
        m %= 13
    return t[5]


