def QuestionReplace(s, n):
    return s.replace("?", str(n), 1)


def bl(n):
    nstr = str(n)
    if len(nstr) % 3 == 2:
        nstr = "0" + nstr
    elif len(nstr) % 3 == 1:
        nstr = "00" + nstr
    nlist = [int(nstr[i: i + 3]) for i in range(0, len(nstr), 3)]
    diff = abs(sum(nlist[0::2]) - sum(nlist[1::2]))
    return diff % 13 == 5


