package main

import (
	"fmt"
	"math"
)

func main() {
	var S string
	fmt.Scan(&S)
	N, MOD := 13, int(math.Pow(10, 9))+7
	dp, k := make([]int, N), 1
 dp[0] = 1
	for i := len(S) - 1; i >= 0; i-- {
		dp2 := make([]int, N)
	 if S[i] == '?' {
			for d := 0; d <= 9; d++ {
				for n := 0; n < N; n++ {
					index := (k*d + n) % N
					dp2[index] += dp[n]
					dp2[index] %= MOD
				}
			}
		} else {
			d := int(S[i] - '0')
			for n := 0; n < N; n++ {
				index := (k*d + n) % N
				dp2[index] += dp[n]
				dp2[index] %= MOD
			}
		}
		dp = dp2
		k *= 10
		k %=  N
	}
	fmt.Println(dp[5])
}

