def solve():
    S = input()
    dp = [[0 for _ in range(13)] for _ in range(len(S))]

    if S[-1] == '?':
        dp[0] = [1 if i < 10 else 0 for i in range(13)]
    else:
        dp[0][int(S[-1])] = 1

    for i, s in enumerate(S[::-1][1:], 1):
        digit = pow(10, i, 13)
        if s == '?':
            for j in range(10):
                x = (j * digit) % 13
                for k in range(13):
                    # print(s, i, j, k, x)
                    dp[i][(x + k) % 13] += dp[i - 1][k] % (10 ** 9 + 7)
        else:
            x = (int(s) * digit) % 13
            for k in range(13):
                # print(s, i, 'X', k, x)
                dp[i][(x + k) % 13] += dp[i - 1][k] % (10 ** 9 + 7)
    print(dp[-1][5] % (10 ** 9 + 7))


