import sys

MOD = 1000000007  # type: int

def compWithQues(S, number):
    N = len(number)
    for i in range(N):
        if S[i] == '?':
            continue
        if S[i] != number[i]:
            return False
    return True

def solve(S: str):
    largest = int(S.replace('?', '9')) - 5
    smallest = int(S.replace('?', '0')) - 5
    hi = largest // 13
    lo = smallest // 13
    S = S[::-1]
    count = 0
    for multi in range(lo, hi + 1):
        myint = str(13 * multi + 5)[::-1]
        if compWithQues(S, myint):
            count += 1
    print(count % MOD)
    return

def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    solve(S)

