MOD = 1000000007  # type: int


def solve(S: str):
    dp = np.zeros((len(S) + 1, 13))
    dp[0, 0] = 1
    for i in range(len(S)):
        if S[i] == '?':
            for j in range(10):
                for k in range(13):
                    dp[i + 1, (k * 10 + j) % 13] += dp[i, k] % MOD
        else:
            j = int(S[i])
            for k in range(13):
                dp[i + 1, (k * 10 + j) % 13] += dp[i, k] % MOD
    print(int(dp[-1, 5]) % MOD)

    return


