def digits_parade(S: str)->int:
    MOD = 10**9 + 7
    DIV = 13
    # dp[i][j] = S の i 桁目までを利用してできる整数で 13 で割ったあまりが j になる組み合わせ
    dp = [[0] * DIV for _ in range(len(S)+1)]
    dp[0][0] = 1

    # digit: 10^n % 13 を計算するための変数
    digit = 1

    for i, c in enumerate(reversed(S)):
        if c == '?':
            for n in range(10):
                d = (n * digit) % DIV
                for j in range(DIV):
                    dp[i+1][(j+d) % DIV] += dp[i][j]
                    dp[i+1][(j+d) % DIV] %= MOD
        else:
            d = (int(c) * digit) % DIV
            for j in range(DIV):
                dp[i+1][(j+d) % DIV] += dp[i][j]
                dp[i+1][(j+d) % DIV] %= MOD

        digit = (digit * 10) % DIV

    return dp[len(S)][5]


