    for i in range(len(s)):
        if i == 0:
            if s[-i-1] == "?":
                for j in range(10):
                    dp[i][j % 13] += 1
            else:
                t = int(s[-i-1])
                dp[i][t % 13] += 1
        else:
            md = pow(10, i, 13)
            if s[-i-1] == "?":
                for j in range(10):
