import sys
from math import factorial


MOD = 1000000007  # type: int
def cmb(n, r):
    return (factorial(n) // (factorial(r) * factorial(n - r))%MOD)

def solve(S: str):
    S = S[::-1]
    dp = [[0] * 13 for _ in range(len(S))]
    s = S[0]
    if s == "?":
        for i in range(10):
            dp[0][i] = 1
    else:
        dp[0][int(s)] = 1
    # dp[LENGTH][MOD]
    for l in range(1, len(S)):
        s = S[l]
        if s == "?":
            for m in range(13):
                for i in range(10):
                    dp[l][(m + pow(10, l, 13) * i) % 13] += dp[l-1][m]% MOD
        else:
            i = int(s)
            for m in range(13):
                dp[l][(m + pow(10, l, 13) * i) % 13] += dp[l-1][m] % MOD

    # print(dp)
    print(dp[-1][5]% MOD)

    return


