def memoize(f):
	table = {}
	def func(*args):
		if not args in table:
			table[args] = f(*args)
		return table[args]
	return func

# 0~i桁目までの部分文字列において
# (mod 13)がbとなるパターン数を返す
@memoize
def search(i,rem):
	if i==len(S):
		return 1 if rem==5 else 0

	ch = int(S[i]) if S[i]!='?' else -1

	res = 0
	for d in range(10):
		if ch!=-1 and ch!=d:
			continue
		num = d*(10**i)%13
		res += search(i+1,(rem+num)%13)
	return res

