from functools import lru_cache

@lru_cache(maxsize=10000000)
def get_base(d):
    if d==0:
        return 1
    base = get_base(d-1)
    base *= 10
    base %= 13
    return base

@lru_cache(maxsize=1000)
def get_shift(d, num):
    shift = num
    shift *= get_base(d)
    shift %= 13
    return shift

