def solve():
    S = [-1 if i == '?' else int(i) for i in input()[::-1]]
    dp = [0] * 13
    mod = 10 ** 9 + 7

    if S[0] == -1:
        dp = [1 if i < 10 else 0 for i in range(13)]
    else:
        dp[int(S[0])] = 1
    for i, s in enumerate(S[1:], 1):
        digit = pow(10, i, 13)
        next_dp = [0] * 13
        if s == -1:
            next_dp = [sum([dp[(13 - (digit * j) + nn) % 13] for j in range(10)]) for nn in range(13)]
        else:
            x = (digit * s) % 13
            next_dp = [dp[(13 - x + nn) % 13] for nn in range(13)]
        dp = [ndp % mod for ndp in next_dp]
    print(dp[5])


