    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


class Mod:
    def __init__(self, m):
        self.m = m

    def add(self, a, b):
        return (a + b) % self.m

    def sub(self, a, b):
        return (a - b) % self.m

    def mul(self, a, b):
        return ((a % self.m) * (b % self.m)) % self.m

    def div(self, a, b):
        return self.mul(a, pow(b, self.m-2, self.m))

    def pow(self, a, b):
        return pow(a, b, self.m)

@mt
def slv(S):
    mod = 10**9 + 7
    t = [0] * 13
    t[0] = 1
    m = 1
    for c in reversed(S):
        nt = [0] * 13
        if c != '?':
            n = (m * int(c)) % 13
            for k in range(13):
                nt[(k+n) % 13] = t[k]
        else:
            for j in range(10):
                n = (m * j) % 13
                for k in range(13):
                    l = (k+n) % 13
                    nt[l] = (nt[l] + t[k]) % mod
        t = nt
        m *= 10
        m %= 13
    return t[5]


