cache = [[-1]*13 for _ in range(n+1)]

def solve(pos, now):
    if pos >= n:
        return 1 if now == 5 else 0
    res = cache[pos][now]
    if res >= 0:
        return res
    res = 0
    if s[pos] == '?':
        for i in range(10):
            m = (now + i * digits[pos]) % 13
            res += solve(pos + 1, m)
    else:
        d = ord(s[pos]) - ord('0')
        m = (now + d * digits[pos]) % 13
        res += solve(pos + 1, m)
    res %= mod
    cache[pos][now] = res

    return res

