        else:
            r = int(s)*(10**i) % 13
            ans_list = shift(r, ans_list)

    print(ans_list[5] % 1000000007)


def shift(r, ans_list):
    l = len(ans_list)
    return [ans_list[(i + l - r) % l] for i in range(l)]


def add(list1, list2):
    return list(map(sum, zip(list1, list2)))


def initial(n):
    return [(1 if i == n else 0) for i in range(13)]


