def solve(string):
    ans = 0
    for i in range(5, 10**(len(string)) + 1, 13):
        if is_equal(string, i):
            ans += 1
    return str(ans % (10**9 + 7))


def is_equal(s, n):
    nr = str(n)[::-1]
    sr = s[::-1]
    if len(sr) < len(nr):
        return False
    if len(sr) > len(nr) and sr[len(nr):] != "?" * (len(sr) - len(nr)):
        return False
    for _s, _n in zip(sr, nr):
        if _s not in [_n, "?"]:
            return False
    return True


