			int[] next_dp = new int[13];
			if (S.charAt(i) == '?') {
				for (int l=0;l<10;l++) {
					int k = l;
					for (int j=0;j<mod;j++) {
						next_dp[(mod_table[N-i-1][k] + j)%mod] += dp[j];
						next_dp[(mod_table[N-i-1][k] + j)%mod] %= mod_num;
