def conv(c):
    if c == "?":
        yield from [str(i) for i in range(0, 10)]
    else:
        yield from [c]


def calc(s, res):
    if not s:
        yield res
    else:
        c = s[0]
        for j in conv(c):
            yield from calc(s[1:], res + j)


