from functools import lru_cache

PRIME = 10 ** 9 + 7


@lru_cache(maxsize=None)
def digitmod13(n):
    return (10 ** n) % 13


def main():
    S = input()
    N = len(S)
    dp = [[0 for _ in range(13)] for _ in range(N)]
    S = S[::-1]
    # init
    first = S[0]
    if first == '?':
        for k in range(10):
            dp[0][k] = 1
    else:
        first = int(first)
        dp[0][first] = 1
    for i in range(1, N):
        c = S[i]
        if c == '?':
            for d in range(13):
                for k in range(10):
                    dp[i][(d + k * digitmod13(i)) % 13] += dp[i - 1][d]
        else:
            c = int(c)
            for d in range(13):
                dp[i][(d + c * digitmod13(i)) % 13] += dp[i - 1][d]
        for d in range(13):
            dp[i][d] %= PRIME

    print(dp[N - 1][5] % PRIME)


