def calc(S):
    N = len(S)
    k = []
    x = 0
    for i in range(N):
        if (S[N - 1 - i] == '?'):
            k += [i]
        else:
            x += int(S[N - 1 - i]) * 10 ** i
    if (not (k)):
        return 1 if x % 13 == 5 else 0
    j = k.pop(0)
    d = {}
    for l in range(10):
        d[(l * 10 ** j) % 13] = 1
    for j in k:
        newd = {i: 0 for i in range(13)}
        for key in d:
            for l in range(10):
                mod = (l * 10 ** j) % 13
                newd[(key + mod) % 13] += d[key]
        d = newd
    m = (5 - x % 13) % 13
    ans = d[m] if m in d else 0
    return ans % (10 ** 9 + 7)


