MOD = 10**9 + 7
def solve(s, p=13):
    s = s[::-1]
    n = len(s)
    cur = np.zeros(p, dtype=np.uint64)
    if s[0] == "?":
        cur[:10] = 1
    else:
        cur[int(s[0])] = 1
    D = {str(i): [i] for i in range(10)}
    D["?"] = list(range(10))
    q = [(10**i) % p for i in range(6)]
    for i in range(1,n):
        next = np.zeros(p, dtype=np.uint64)
        for x in D[s[i]]:
            for j in range(p):
                k = (j + x * q[i%6]) % p
                next[k] += cur[j]
        cur = next % MOD
    return cur[5]

