class mod:
    def __init__(self, v=0):
        self.v = v
        self.v %= MOD
    def __add__(self, v):
        self.v += int(v)
        self.v %= MOD
        return self
    def __sub__(self, v):
        self.v -= int(v)
        return self
    def __mul__(self, v):
        self.v *= int(v)
        self.v %= MOD
        return self
    def __int__(self):
        return int(self.v)
    def __str__(self):
