from scipy.sparse import csr_matrix


def main():
    S = {i:s for i, s in enumerate(input()[::-1])}
    MOD = 10**9 + 7

    DP_table = [[0] for i in range(13)]

    # 初期化
    digit = S[0]
    if digit == '?':
        for i in range(10):
            DP_table[i][0] = 1
    else:
        DP_table[int(digit)][0] = 1

    DP_table = csr_matrix(DP_table, dtype=int)

    transition_matrixes = {}
    for multiplier in range(13):
        for digit in range(10):
            transition_matrix = [[0 for i in range(13)] for j in range(13)]
            for k in range(13):
                transition_matrix[(digit * multiplier + k) % 13][k] = 1
            transition_matrixes[(multiplier, digit)] = csr_matrix(
                transition_matrix, dtype=int)

    for multiplier in range(13):
        transition_matrixes[multiplier] = csr_matrix(
            [[0 for i in range(13)] for j in range(13)], dtype=int)
        for digit in range(10):
            transition_matrixes[multiplier] = transition_matrixes[multiplier]\
            + transition_matrixes[(multiplier, digit)]

    # DP
    multiplier = 1
    for i in range(1, len(S)):
        multiplier = multiplier * 10 % 13
        digit = S[i]
        if digit == '?':
            transition_matrix = transition_matrixes[multiplier]
        else:
            transition_matrix = transition_matrixes[(multiplier, int(digit))]

        DP_table = transition_matrix * DP_table
        DP_table = DP_table.toarray() % MOD
        DP_table = csr_matrix(DP_table)

    print(int(DP_table[5][0].toarray()))


