const M: usize = 1e9 as usize + 7;

fn main() {
    input! {
        mut s: chars,
    }

    s.reverse();
    let mut dp = vec![vec![0; 13]; s.len() + 1];
    let mut mul = 1;
    dp[0][0] = 1;
    for i in 1..s.len() + 1 {
        if s[i - 1] == '?' {
            for j in 0..13 {
                for k in 0..10 {
                    dp[i][j] += dp[i - 1][(13 + j - k * mul % 13) % 13];
                    dp[i][j] %= M;
                }
            }
        } else {
            let k = s[i - 1] as usize - b'0' as usize;
            for j in 0..13 {
                dp[i][j] += dp[i - 1][(13 + j - k * mul % 13) % 13];
                dp[i][j] %= M;
            }
        }
        mul *= 10;
        mul %= 13;
    }
    println!("{:?}", dp[s.len()][5]);
}

