// 最大公約数 / 最小公倍数 / 約数
fn gcd(a:isize, b:isize) -> isize {
    if b == 0 {return a};
    gcd(b, a % b)
}
fn lcm(a:isize, b:isize) -> isize {
    a / gcd(a, b) * b
}
fn divisors(a:isize) -> Vec<isize> {
    let mut divs = vec![1, a];
    for n in 2..((a as f64).powf(0.5) as isize) + 1 {
        if a % n == 0 {
            divs.push(n);
            divs.push(a / n);
        }
    }
    divs.sort();
    divs
}
