// 検索(二分探索：右)
macro_rules! bsr {
    ($g:expr, $v:expr) => {
        bsr($g, $v, 0, $g.len() - 1)
    }
}
fn bsr(g:&[isize], v:isize, lo:usize, hi:usize) -> usize {
    if hi < lo {return lo;}
    let mi = (hi + lo) / 2;
    if g[mi] < v {
        return bsr(&g, v, mi + 1, hi);
    } else {
        return bsr(&g, v, lo, mi - 1);
    }
}

