fn main() {
    let s = read::<String>().chars().collect::<Vec<_>>();

    let mut dp = vec![vec![0; 13]; 100_001];

    dp[0][0] = 1;

    for (i, &c) in s.iter().enumerate() {

        for j in 0..10 {
            if let Some(c) = c.to_u8() {
                if c as usize != j {
                    continue;
                }
            }
            for ki in 0..13 {
                dp[i + 1][(ki * 10 + j) % 13] += dp[i][ki];
            }
        }

        for j in 0..13 {
            dp[i+1][j] %= MOD;
        }
    }

    let res = dp[s.len()][5];
    println!("{:?}", res);
}

