fn main() {
    input!{
        s: chars,
    };

    let m = 1000000007;

    let mut dp: Vec<usize>;
    let mut pre: Vec<usize> = vec![0; 13];
    pre[0] = 1;

    for c in s {
        dp = vec![0; 13];

        let range = match c {
            '?' => 0..10,
            x => {
                let d = x.to_digit(10).unwrap() as usize;
                d..d+1
            }
        };

        for i in 0..13 {
            for j in range.clone() {
                let to = (10 * i + j) % 13;
                dp[to] += pre[i];
                dp[to] %= m;
            }
        }
        pre = dp;
    }
    println!("{}", pre[5]);
}

