const MOD: u64 = 1000000000 + 7;

fn solve(mut s: Vec<char>) -> u64 {
    s.reverse();

    let mut dp = vec![vec![0; 13]; s.len()];
    if s[0] == '?' {
        for i in 0..10 {
            dp[0][i] = 1 as u64;
        }
    } else {
        let n = s[0].to_digit(10).unwrap() as usize;
        dp[0][n] = 1 as u64;
    }

    let mut pow = 1;
    for i in 1..s.len() {
        pow = pow * 10 % 13;
        if s[i] == '?' {
            for j in 0..10 {
                for k in 0..13 {
                    let rem = (k + pow * j) % 13;
                    dp[i][rem] += dp[i-1][k] % MOD;
                }
            }
        } else {
            for k in 0..13 {
                let n = s[i].to_digit(10).unwrap() as usize;
                let rem = (k + pow *  n)  % 13;
                dp[i][rem] += dp[i-1][k] % MOD;
            }
        }
    }

    dp[s.len()-1][5] % MOD
}


fn main() {
    input! {
        s: chars
    };
    println!("{}", solve(s));
}

fn read<T: std::str::FromStr>(
    stdin_lock: &mut std::io::StdinLock,
    buf: &mut Vec<u8>,
    delimiter: u8,
) -> T {
    buf.clear();
    let l = std::io::BufRead::read_until(stdin_lock, delimiter, buf).unwrap();
    buf.truncate(l - 1); // remove delimiter
    let s = unsafe { std::str::from_utf8_unchecked(&buf) };
    s.parse().unwrap_or_else(|_| panic!("read"))
}

