pub fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed reading char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed parsing")
}

fn main() {

    const M : u64 = 1_000_000_007;

    const N : usize = 13;

    let s : Vec<char> = read::<String>().chars().collect();

    let mut dp = [0; N];
    dp[0] = 1;

    for item in s {
        let mut next_dp = [0; N];

        if item == '?'{
            // ? = 0..10
            for i in 0..10 {
                for j in 0..N {
                    next_dp[ ((j * 10) + i) % N] += dp[j];
                    next_dp[ ((j * 10) + i) % N] %= M;
                }
            }
        }

        else {
            let i = item as usize - '0' as usize;

            for j in 0..N {
                next_dp[ ((j * 10) + i) % N] += dp[j];
                next_dp[ ((j * 10) + i) % N] %= M;
            }
        }

        // copy dp
        for i in 0..N{
            dp[i] = next_dp[i];
        }
    }

    println!("{}", dp[5]);

}

