const MOD: i32 = 1000000000 + 7;

fn main() {
    let mut s: Vec<char> = read::<String>().chars().collect();
    let len = s.len();
    s.reverse();
    let mut dp = vec![vec![0i32; 13]; len];
    match s[0] {
        '?' => {
            for i in 0..10 {
                dp[0][i] = 1;
            }
        },
        c => dp[0][c as usize - 48] = 1,
    }
    for i in 1..len {
        let mul = 10usize.pow((i % 13) as u32) % 13;
        match s[i] {
            '?' => {
                for m in 0..10 {
                    for n in 0..13 {
                        let new_r = (m * mul + n) % 13;
                        dp[i][new_r] += dp[i - 1][n];
                        dp[i][new_r] %= MOD;
                    }
                }
            },
            c => {
                let num = c as usize - 48;
                for n in 0..13 {
                    let new_r = (num * mul + n) % 13;
                    dp[i][new_r] += dp[i - 1][n];
                    dp[i][new_r] %= MOD;
                }
            },
        }
    }
    println!("{}", dp[len - 1][5]);
}

