        .collect();
    token.parse().ok().expect("failed to parse token")
}

const MOD: i64 = 1e+9 as i64 + 7;

fn calc(depth: usize, rest: usize, seq: &Vec<char>, memo: &mut Vec<Vec<i64>>) -> i64 {
    let n = seq.len();
    if depth == n {
        if rest == 5 {
            return 1;
        } else {
            return 0;
        }
    }
    if memo[depth][rest] != -1 {
        return memo[depth][rest];
    }
    let mut ret = 0;
    for i in 0..10 {
        if seq[depth] == '?' || (seq[depth] as u8 - '0' as u8) as usize == i {
            let nrest = (rest * 10 + i) % 13;
            ret = (ret + calc(depth + 1, nrest, seq, memo)) % MOD;
        }
    }
    memo[depth][rest] = ret;
    return ret;
}

fn main() {
    let seq = read::<String>().chars().collect::<Vec<char>>();
    let n = seq.len();
    let mut memo = vec![vec![-1; 13]; n];
    let ans = calc(0, 0, &seq, &mut memo);
    println!("{}", ans);
}

