const P: i64 = 1_000_000_007;

fn main() {
    let S = rl();
    let N = S.len();

    let S = std::iter::repeat('0')
        .take((3 - N % 3) % 3)
        .chain(S.chars())
        .collect::<Vec<_>>();
    let N = S.len();
    debug_assert_eq!(N % 3, 0);

    debug!(S, N);

    // 数字を下から3桁ごとに分けたとき各部分をブロックと呼ぶ
    // 前方のブロックの i (≥ 0) 番目の値を x とするとき t = Σ(-1)^i x とおく
    // dp[i][t] = n
    let mut dp = vec![vec![0; 13]; N / 3 + 1];

    dp[0][0] = 1;

    for bi in 0..N / 3 {
        for x in 0..13 {
            fn lb(c: char) -> usize {
                if c == '?' {
                    0
                } else {
                    (c as u8 - b'0') as usize
                }
            }
            fn ub(c: char) -> usize {
                if c == '?' {
                    10
                } else {
                    (c as u8 - b'0' + 1) as usize
                }
            }

            for d1 in lb(S[bi * 3])..ub(S[bi * 3]) {
                let a = d1 * 100;
                for d2 in lb(S[bi * 3 + 1])..ub(S[bi * 3 + 1]) {
                    let b = a + d2 * 10;
                    for d3 in lb(S[bi * 3 + 2])..ub(S[bi * 3 + 2]) {
                        let y = b + d3;
                        let z = (13 + y - x) % 13;
                        dp[bi + 1][z] += dp[bi][x];
                    }
                }
            }

            for z in 0..13 {
                dp[bi + 1][z] %= P;
            }
        }
    }

    println!("{}", dp[N / 3][5])
}

