struct State {
    counts: [u64; 13],
    power: u64,
}

fn rec(st: State, c: char) -> State {
    let power = (st.power * 10) % 13;
    let range = if let Some(x) = c.to_digit(10) {
        x..(x + 1)
    } else {
        0..10
    };
    let mut counts = [0; 13];
    for i in range {
        let base = power * i as u64;
        for (j, &count) in st.counts.iter().enumerate() {
            let rem = ((base + j as u64) % 13) as usize;
            counts[rem] += count;
            counts[rem] %= 1_000_000_007;
        }
    }

    State {
        counts: counts,
        power: power,
    }
}

fn initialize(c: char) -> [u64; 13] {
    let mut a = [0; 13];
    if let Some(x) = c.to_digit(10) {
        a[x as usize] = 1;
    } else {
        for i in 0..10 {
            a[i] = 1;
        }
    }
    a
}

fn evaluate(v: Vec<char>) -> u64 {
    let init = State {
        counts: initialize(v[0]),
        power: 1,
    };
    v[1..].into_iter().fold(init, |st, &c| rec(st, c)).counts[5]
}

