    let s = (0..2).map(|_| '?').collect::<Vec<char>>();
    let n = 13;
    let mut dp = vec![0; n];
    dp[0] = 1;
    let md = 1000_000_000 + 7;

    let mut mul = 1;
    for i in (0..s.len() - 1).rev() {
        let mut next_dp = vec![0; n];
        let c = s[i];
        if c == '?' {
            for k in 0..10 {
                for j in 0..n {
                    next_dp[(k * mul +j) % n] += dp[j];
                    next_dp[(k * mul +j) % n] %= md;
                }
            }
        } else {
            let k = c.to_digit(10).unwrap() as usize;
            for j in 0..n {
                next_dp[(k * mul +j) % n] += dp[j];
                next_dp[(k * mul +j) % n] %= md;
            }
        }
