const B : usize = 13;
const M : usize = 1000000007;

fn main() {
    input! {
        s: chars,
    }
    let n = s.len();
    let mut s = s;
    s.reverse();
    let mut count = vec![0; B];
    let mut count2 = vec![0; B];

    if s[0] == '?' {
        for d in 0..10 {
            count[d] += 1;
        }
    } else {
        count[s[0] as usize - '0' as usize] += 1;
    }

    let mut base = 10;
    for i in 1..n {
        for j in 0..B {
            count2[j] = 0;
        }
        if s[i] == '?' {
            for d in 0..10 {
                for j in 0..B {
                    let k = (d * base + j) % B;
                    count2[k] = (count2[k] + count[j]) % M;
                }
            }
        } else {
            let d = s[i] as usize - '0' as usize;
            for j in 0..B {
                let k = (d * base + j) % B;
                count2[k] = (count2[k] + count[j]) % M;
            }
        }
        for j in 0..B {
            count[j] = count2[j];
        }
        base = base * 10 % B;
    }
    println!("{}", count[5]);
}

