#[allow(unused_imports)]
use std::cmp::{min, max};
#[allow(unused_imports)]
use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      s: chars,
    }
    const MOD: usize = 1e9 as usize + 7;
    let n = s.len();
    let mut dp = vec![vec![0; 13]; n+1];
    dp[0][0] = 1;
    for i in 0..n {
        let c = s[i];
        for m in 0..13 {
            if c == '?' {
                for v in 0..10 {
                    let idx = (m*10 + v) % 13;
                    dp[i+1][ idx ] += dp[i][m];
                    dp[i+1][ idx ] %= MOD;
                }
            } else {
                let v = (c as u8 - '0' as u8) as usize;
                let idx = (m*10 + v) % 13;
                dp[i+1][ idx ] += dp[i][m];
                dp[i+1][ idx ] %= MOD;
            }
        }
    }
    puts!("{}\n", dp[n][5]);
}

