fn length_in_base2(x: usize) -> usize {
    let mut x = x;
    let mut ans = 0;
    while x > 0 {
        ans += 1;
        x >>= 1;
    }
    ans
}

fn powmod(x: i64, y: usize, z: i64) -> i64 {
    let mut ans = 1_i64;
    let mut px = x;
    let y_size = length_in_base2(y);
    for i in 0..y_size {
        if (y >> i) & 1 == 1 {
            ans = (ans * px) % z;
        }
        px = (px * px) % z;
    }
    ans
}

fn main() {
    let s: Vec<char> = read_as_chars();
    let mut xs: Vec<i64> = vec![0; 13];
    xs[0] = 1;

    for (p, &c) in s.iter().rev().enumerate() {
        let powpow = powmod(10, p, 13) as usize;
        let mut ys: Vec<i64> = vec![0; 13];
        if c == '?' {
            for k in 0..13 {
                for i in 0..10 {
                    let idx = (powpow * i + k) % 13;
                    ys[idx] = (ys[idx] + xs[k]) % BIGINT;
                }
            }
        } else {
            let n: usize = c.to_digit(10).unwrap() as usize;
            for k in 0..13 {
                let idx = (powpow * n + k) % 13;
                ys[idx] = xs[k];
            }
        }
        xs = ys;
    }
    println!("{}", xs[5]);

}

