const MOD: usize = 1_000_000_000 + 7;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let digits = scanner.read_chars().unwrap();
    let mut dp = vec![0; 13];
    dp[0] = 1;
    for i in (0..digits.len()).rev() {
        let mut dp_new = vec![0; 14];
        if digits[i].is_digit(10) {
            let digit = digits[i].to_digit(10).unwrap() as usize;
            for j in 0..13 {
                for k in 0..10 {
                    let mut num = 13 * k + j;
                    if i == digits.len() - 1 {
                        num += 5;
                    }
                    let d = num % 10;
                    let index = num / 10;
                    if d != digit {
                        continue;
                    }
                    dp_new[index] = (dp_new[index] + dp[j]) % MOD;
                }
            }
        } else {
            for j in 0..13 {
                for k in 0..10 {
                    let mut num = 13 * k + j;
                    if i == digits.len() - 1 {
                        num += 5;
                    }
                    let index = num / 10;
                    dp_new[index] = (dp_new[index] + dp[j]) % MOD;
                }
            }
        }
        dp = dp_new;
    }
    println!("{}", dp[0]);
}

