const MOD: i64 = 1000000000 + 7;

fn main() {
    let s: Vec<char> = read::<String>().chars().collect();
    let len = s.len();
    let mut dp = vec![vec![0i64; 13]; len];
    match s[0] {
        '?' => {
            for i in 0..10 {
                dp[0][i] = 1;
            }
        },
        c => dp[0][c as usize - 48] = 1,
    }
    for i in 1..len {
        match s[i] {
            '?' => {
                for m in 0..10 {
                    for n in 0..13 {
                        let new_r = ((m + 10 * n) % 13) as usize;
                        dp[i][new_r] += dp[i - 1][n as usize];
                        dp[i][new_r] %= MOD;
                    }
                }
            },
            c => {
                let num = c as i64 - 48;
                for n in 0..13 {
                    let new_r = ((num + 10 * n) % 13) as usize;
                    dp[i][new_r] += dp[i - 1][n as usize];
                    dp[i][new_r] %= MOD;
                }
            },
        }
    }
    println!("{}", dp[len - 1][5]);
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

