    let mut dp: Vec<Vec<i64>> = vec![vec![0; 14]; n + 1];
    dp[0][0] = 1;
    for i in 0..n{
        for j in 0..14{
            if s[i] == '?'{
                for k in 0..10{
                    dp[i + 1][(j * 10 + k) % 13] += dp[i][j];
                    dp[i + 1][(j * 10 + k) % 13] %= MOD;
                }
            }else{
                let t: usize = (j * 10 + s[i] as usize - '0' as usize) % 13;
