type Mod = Modular<Mod_1_000_000_007>;

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        s: chars,
    }
    let mut k_one = 1usize;
    let n = s.len();
    let mut dp = vec![Mod::new(0); 13];
    let mut s = s;
    s.reverse();
    dp[0] = Mod::new(1);
    for i in 0..n {
        let d = s[i] as i64 - '0' as i64;
        let mut dp2 = vec![Mod::new(0); 13];
        for j in 0..13 {
            for k in 0..10 {
                if k as i64 == d || s[i] == '?' {
                    dp2[(j + k_one * k) % 13] += dp[j];
                }
            }
        }
        dp = dp2;
        // eprintln!("dp = {:?}", dp);
        k_one = k_one * 10 % 13;
    }
    writeln!(buf, "{}", dp[5].as_u32());
    buf
}

use std::io::Read;

fn read<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

const MOD: u64 = 1000_000_007;

fn main() {
    let s: String = read();
    let n = s.len();
    let m = 13;

    let mut dp = vec![vec![0; m]; n + 1];
    dp[0][0] = 1;

    for i in 0..n {
        let c = s.as_bytes()[i];
        if c as char != '?' {
            // 数字の場合
            for j in 0..m {
                let digit = (c - ('0' as u8)) as usize;
                dp[i + 1][(10 * j + digit) % m] += dp[i][j];
                dp[i + 1][(10 * j + digit) % m] %= MOD;
            }
        } else {
            // `?` の場合
            for j in 0..m {
                for digit in 0..10 {
                    dp[i + 1][(10 * j + digit) % m] += dp[i][j];
                    dp[i + 1][(10 * j + digit) % m] %= MOD;
                }
            }
        }
    }

    println!("{}", dp[n][5]);
}

