fn binary_power(x: u64, n: u64) -> u64 {
    if n == 0 {
      return 1;
    }
    if n % 2 == 0 {
      return (binary_power(x, n / 2) % 13).pow(2) % 13;
    } else {
      return binary_power(x, n - 1) % 13 * x % 13;
    }
}

fn remainder(n: char, digit: u64) -> Vec<u64> {
    let mut remainders = vec![0u64; 13];
    if n == '?' {
        for i in 0..10 {
            let remainder = binary_power(10, digit) * i % 13;
            remainders[remainder as usize] += 1
        }
    } else {
        let remainder = binary_power(10, digit) * (n as u64 - 48) % 13;
        remainders[remainder as usize] = 1;
    }    
    remainders
}

fn main() {
    let s: String = input();
    let s: Vec<char> = s.chars().collect();
    let mut dp: Vec<Vec<u64>> = vec![vec![0; 13]; s.len()];
    dp[s.len() - 1] = remainder(s[s.len() - 1], 0);
    for i in (0..(s.len() - 1)).rev() {
        for j in 0..13 {
            let remainders = remainder(s[i], (s.len() - 1 - i) as u64);
            for k in 0..13 {
                let r = (13 + j - k) % 13;
                dp[i][j] += dp[i+1][r] % MOD * remainders[k] % MOD;
            }

        }
    }
    // println!("{:?}", dp);
    println!("{:?}", dp[0][5] % MOD);
}

