                    dp[i+1][(j + d * w) % 13] += dp[i][j];
                    dp[i+1][(j + d * w) % 13] %= MOD;
                }
            }
        } else {
            let d = S[i] as usize - b'0' as usize;
            for j in 0..13 {
                dp[i+1][(j + d * w) % 13] += dp[i][j];
                dp[i+1][(j + d * w) % 13] %= MOD;
            }
        }
        w *= 10;
        w %= 13;
    }
    println!("{}", dp[N][5]);
}

