fn sieve_of_eratosthenes(max: usize) -> Vec<bool> {
    let mut candidates = vec![true; max + 1];
    candidates[0] = false;
    candidates[1] = false;
    let mut num = 2;
    while num * num <= max {
        if candidates[num] {
            let prime = num;
            for n in 2..max / prime + 1 {
                candidates[prime * n] = false;
            }
        }
        num += 1;
    }
    candidates
}

