fn transit(digit: usize, dp_before: &[usize; 13], dp_after: &mut [usize; 13]) {
    for i in 0..13 {
        let j = (i + digit) % 13;
        dp_after[j] += dp_before[i];
        dp_after[j] %= MOD;
    }
}

fn main() {
    input! {
        S: chars,
    }
    let S: Vec<char> = S;
    let mut dp_before = [0usize; 13];
    let mut base = 1usize;
    dp_before[0] = 1;
    for s in S.iter().rev() {
        let mut dp_after = [0usize; 13];
        match *s {
            ss @ '0'..='9' => {
                let num = base * (ss as usize - '0' as usize) % 13;
                transit(num, &dp_before, &mut dp_after);
            }
            '?' => {
                for d in 0..=9 {
                    let num = (base * d) % 13;
                    transit(num, &dp_before, &mut dp_after);
                }
            }
            _ => panic!("wrong char in input S"),
        }
        base *= 10;
        base %= 13;
        dp_before = dp_after;
    }
    println!("{}", dp_before[5]);
}

