    let mut digit = Modint::from(13, 1);
    let mut i = 0;
    for c in s.iter().rev() {
        if *c == '?' {
            for buf in 0..10 {
                let buf = (digit.get_value() * buf) % 13;
                for z in 0..13 {
                    dp[i + 1][(buf + z) % 13] = &dp[i][z] + &dp[i + 1][(buf + z) % 13];
                }
            }
        } else {
            let buf: usize = (*c).to_digit(10).unwrap() as usize;
            let buf = (digit.get_value() * buf) % 13;
            for z in 0..13 {
                dp[i + 1][(buf + z) % 13] = &dp[i][z] + &dp[i + 1][(buf + z) % 13];
            }
        }
        digit.mul_uint(10);
        i += 1;
    }
    p(&dp[s.len()][5]);
}

